window.MD102_SUPPORT_SOURCE_AE={"files":[{"repository":"microsoft/mggraph-intune-samples","path":"LOB_Application/MSIX_Application_Add.ps1","sha":"cdd42854a485efe14b7d4c19d01ac8d3fb2675bb","lesson":13,"topic":"Add an MSIX application resource","url":"https://github.com/microsoft/mggraph-intune-samples/blob/main/LOB_Application/MSIX_Application_Add.ps1","markdown":"<#\n.COPYRIGHT\nCopyright (c) Microsoft Corporation. All rights reserved. Licensed under the MIT license.\nSee LICENSE in the project root for license information.\n#>\n\n#requires -module Microsoft.Graph.Devices.CorporateManagement\n#requires -module Microsoft.Graph.Authentication\n\n<# region Authentication\nTo authenticate, you'll use the Microsoft Graph PowerShell SDK. If you haven't already installed the SDK, see this guide:\nhttps://learn.microsoft.com/en-us/powershell/microsoftgraph/installation?view=graph-powershell-1.0\nThe PowerShell SDK supports two types of authentication: delegated access, and app-only access.\nFor details on using delegated access, see this guide here:\nhttps://learn.microsoft.com/powershell/microsoftgraph/get-started?view=graph-powershell-1.0\nFor details on using app-only access for unattended scenarios, see Use app-only authentication with the Microsoft Graph PowerShell SDK:\nhttps://learn.microsoft.com/powershell/microsoftgraph/app-only?view=graph-powershell-1.0&tabs=azure-portal\n#>\n\n<#\n.SYNOPSIS\nUploads an MSIX/AppX line-of-business app (windowsUniversalAppX) to Intune.\n\n.DESCRIPTION\nThis function uploads an MSIX/AppX line-of-business app to Intune.\n\nUnlike a Win32 (.intunewin) app, an .msix/.appx package is NOT pre-encrypted and does NOT contain a\ndetection.xml. Instead, the script:\n  1. Extracts the package manifest (AppxManifest.xml, or AppxBundleManifest.xml for *.msixbundle / *.appxbundle).\n  2. Parses the package Identity (Name, Publisher, Version, ProcessorArchitecture, ResourceId).\n  3. Computes the Identity Publisher Hash from the Identity Publisher string (the same hash that forms the\n     last segment of a package family name).\n  4. Encrypts the package locally (AES + HMAC-SHA256) and uploads the encrypted copy to Azure Storage.\n  5. Commits the encrypted file and publishes the windowsUniversalAppX app.\n\n.PARAMETER SourceFile\nThe path to the .msix, .msixbundle, .appx, or .appxbundle file.\n\n.PARAMETER displayName\nThe display name of the app. If not specified, the script uses the package DisplayName (or Identity Name) from the manifest.\n\n.PARAMETER publisher\nThe publisher of the app. If not specified, the script uses the package PublisherDisplayName (or Identity Publisher) from the manifest.\n\n.PARAMETER description\nThe description of the app. If not specified, the script uses the display name.\n\n.PARAMETER minimumSupportedOperatingSystem\nThe minimum supported operating system for the app, as a windowsMinimumOperatingSystem hashtable.\nValid keys for windowsUniversalAppX are 'v8_0', 'v8_1', and 'v10_0'. Defaults to @{ v10_0 = $true }.\n\n.PARAMETER IconFile\nThe path to an image file (.png, .jpg, .jpeg, or .gif) to use as the app icon. The image is converted to a mimeContent object and uploaded as the app's largeIcon. Optional.\n\n.EXAMPLE\n# Uploads an .msix app to Intune, letting the script parse the display name, publisher, and identity from the package.\nInvoke-MSIXAppUpload -SourceFile \"C:\\IntuneApps\\Contoso\\Contoso.DemoApp_1.0.0.0_x64.msix\"\n\n.EXAMPLE\n# Uploads an .msix app with an explicit display name, publisher, description, and app icon.\nInvoke-MSIXAppUpload -SourceFile \"C:\\IntuneApps\\Contoso\\Contoso.DemoApp_1.0.0.0_x64.msix\" -displayName \"Contoso Demo App\" -publisher \"Contoso\" -description \"Contoso Demo App (MSIX)\" -IconFile \"C:\\IntuneApps\\Contoso\\icon.png\"\n\n.EXAMPLE\n# Uploads an .msixbundle app and overrides the minimum supported operating system.\nInvoke-MSIXAppUpload -SourceFile \"C:\\IntuneApps\\Contoso\\Contoso.DemoApp_1.0.0.0_x64.msixbundle\" -displayName \"Contoso Demo App\" -minimumSupportedOperatingSystem @{ v10_0 = $true }\n#>\nfunction Invoke-MSIXAppUpload {\n    [cmdletbinding()]\n    param\n    (\n        [parameter(Mandatory = $true, Position = 1)]\n        [ValidateNotNullOrEmpty()]\n        [string]$SourceFile,\n\n        [parameter(Mandatory = $false, Position = 2)]\n        [string]$displayName,\n\n        [parameter(Mandatory = $false, Position = 3)]\n        [string]$publisher,\n\n        [parameter(Mandatory = $false, Position = 4)]\n        [string]$description,\n\n        [parameter(Mandatory = $false, Position = 5)]\n        [hashtable]$minimumSupportedOperatingSystem,\n\n        [parameter(Mandatory = $false, Position = 6)]\n        [string]$IconFile\n    )\n\n    # Temp encrypted copy of the package (created during the encryption step, removed in the finally block)\n    $tempFile = $null\n\n    try {\n        # Check if the source file exists and has a supported extension\n        Write-Host \"Testing if SourceFile '$SourceFile' Path is valid...\" -ForegroundColor Yellow\n        Test-SourceFile \"$SourceFile\"\n\n        $Ext = [System.IO.Path]::GetExtension(\"$SourceFile\").ToLower()\n        if ($Ext -notin '.msix', '.msixbundle', '.appx', '.appxbundle') {\n            throw \"Unsupported file type '$Ext'. Supported types are .msix, .msixbundle, .appx, and .appxbundle.\"\n        }\n\n        Write-Host \"Parsing the package manifest...\" -ForegroundColor Yellow\n\n        # Extract and parse the package manifest to get the identity metadata that Intune requires.\n        # This is the key difference vs. Win32: there is no detection.xml, so the metadata comes from\n        # AppxManifest.xml (or AppxBundleManifest.xml for bundles).\n        $AppInfo = Get-MSIXAppInformation -SourceFile \"$SourceFile\"\n\n        Write-Host \"Package identity parsed from manifest:\" -ForegroundColor Gray\n        Write-Host \"  Identity Name        : $($AppInfo.IdentityName)\" -ForegroundColor Gray\n        Write-Host \"  Identity Version     : $($AppInfo.IdentityVersion)\" -ForegroundColor Gray\n        Write-Host \"  Identity Publisher   : $($AppInfo.IdentityPublisher)\" -ForegroundColor Gray\n        Write-Host \"  Publisher Hash       : $($AppInfo.IdentityPublisherHash)\" -ForegroundColor Gray\n        Write-Host \"  Architecture(s)      : $($AppInfo.ApplicableArchitectures)\" -ForegroundColor Gray\n        Write-Host \"  Is Bundle            : $($AppInfo.IsBundle)\" -ForegroundColor Gray\n\n        # Resolve the values that can be overridden by the caller, otherwise fall back to the manifest.\n        if (!$displayName) { $displayName = if ($AppInfo.DisplayName) { $AppInfo.DisplayName } else { $AppInfo.IdentityName } }\n        if (!$publisher) { $publisher = if ($AppInfo.PublisherDisplayName) { $AppInfo.PublisherDisplayName } else { $AppInfo.IdentityPublisher } }\n        if (!$description) { $description = $displayName }\n        if (!$minimumSupportedOperatingSystem) { $minimumSupportedOperatingSystem = @{ \"v10_0\" = $true } }\n\n        $FileName = [System.IO.Path]::GetFileName(\"$SourceFile\")\n\n        # Build the windowsUniversalAppX app body\n        Write-Host \"Creating JSON data to pass to the service...\" -ForegroundColor Yellow\n        $mobileAppBody = New-MSIXAppBody `\n            -displayName \"$displayName\" `\n            -publisher \"$publisher\" `\n            -description \"$description\" `\n            -fileName \"$FileName\" `\n            -identityName $AppInfo.IdentityName `\n            -identityPublisherHash $AppInfo.IdentityPublisherHash `\n            -identityResourceIdentifier $AppInfo.IdentityResourceIdentifier `\n            -identityVersion $AppInfo.IdentityVersion `\n            -isBundle $AppInfo.IsBundle `\n            -applicableArchitectures $AppInfo.ApplicableArchitectures `\n            -applicableDeviceTypes \"desktop\" `\n            -minimumSupportedOperatingSystem $minimumSupportedOperatingSystem\n\n        # Add the app icon (largeIcon) if an icon file was provided\n        if ($IconFile) {\n            Write-Host \"Adding app icon from '$IconFile'...\" -ForegroundColor Yellow\n            $mobileAppBody.Add(\"largeIcon\", (New-IntuneAppIcon -IconFile $IconFile))\n        }\n\n        # Create the application in Intune and get the application ID\n        Write-Host \"Creating application in Intune...\" -ForegroundColor Yellow\n        $MobileApp = New-MgDeviceAppManagementMobileApp -BodyParameter ($mobileAppBody | ConvertTo-Json)\n        $mobileAppId = $MobileApp.id\n\n        # Create a new content version for the application\n        Write-Host \"Creating Content Version in the service for the application...\" -ForegroundColor Yellow\n        $ContentVersion = New-MgDeviceAppManagementMobileAppAsWindowsUniversalAppXContentVersion -MobileAppId $mobileAppId -BodyParameter @{}\n        $ContentVersionId = $ContentVersion.id\n\n        # Encrypt a copy of the package. Unlike a .intunewin file (which is already encrypted), the .msix is\n        # a raw file, so the script generates the encryption keys and computes the file digest itself.\n        Write-Host \"Encrypting a copy of the package '$SourceFile'...\" -ForegroundColor Yellow\n        $tempFile = [System.IO.Path]::Combine([System.IO.Path]::GetDirectoryName(\"$SourceFile\"), [System.IO.Path]::GetFileNameWithoutExtension(\"$SourceFile\") + \"_\" + [guid]::NewGuid().ToString() + \"_temp.bin\")\n        $fileEncryptionInfo = EncryptFile \"$SourceFile\" \"$tempFile\"\n\n        [int64]$Size = (Get-Item \"$SourceFile\").Length\n        $EncrySize = (Get-Item \"$tempFile\").Length\n\n        # Create a new file entry in Azure for the upload. Unlike Win32/macOS content files, a\n        # windowsUniversalAppX content file requires a (non-null) manifest. For MSIX/AppX the service only\n        # requires the base64-encoded file name here (the rich identity metadata is supplied on the app body).\n        $encodedManifest = [System.Convert]::ToBase64String([System.Text.Encoding]::ASCII.GetBytes($FileName))\n        $fileBody = GetAppFileBody \"$FileName\" $Size $EncrySize $encodedManifest\n        Write-Host \"Creating a new file entry in Azure for the upload...\" -ForegroundColor Yellow\n        $ContentVersionFile = New-MgDeviceAppManagementMobileAppAsWindowsUniversalAppXContentVersionFile -MobileAppId $mobileAppId -MobileAppContentId $ContentVersionId -BodyParameter ($fileBody | ConvertTo-Json)\n        $ContentVersionFileId = $ContentVersionFile.id\n\n        # Get the file URI for the upload\n        $fileUri = \"https://graph.microsoft.com/beta/deviceAppManagement/mobileApps/$mobileAppId/microsoft.graph.windowsUniversalAppX/contentVersions/$ContentVersionId/files/$ContentVersionFileId\"\n\n        # Wait for the Azure Storage SAS URI to be created\n        Write-Host \"Waiting for the file entry SAS URI to be created...\" -ForegroundColor Yellow\n        $file = WaitForFileProcessing $fileUri \"AzureStorageUriRequest\"\n\n        # Upload the encrypted file to Azure Storage\n        Write-Host \"Uploading the file to Azure Storage...\" -ForegroundColor Yellow\n        [UInt64]$BlockSizeMB = 4\n        UploadFileToAzureStorage $file.azureStorageUri \"$tempFile\" $BlockSizeMB\n\n        # Commit the file to the service using the encryption information\n        Write-Host \"Committing the file to the service...\" -ForegroundColor Yellow\n        Start-Sleep -Seconds 5\n        Invoke-MgCommitDeviceAppManagementMobileAppMicrosoftGraphWindowsUniversalAppXContentVersionFile -MobileAppId $mobileAppId -MobileAppContentId $ContentVersionId -MobileAppContentFileId $ContentVersionFileId -BodyParameter ($fileEncryptionInfo | ConvertTo-Json)\n\n        # Wait for the file to be processed\n        Write-Host \"Waiting for the file to be processed...\" -ForegroundColor Yellow\n        $file = WaitForFileProcessing $fileUri \"CommitFile\"\n\n        # Update the application with the committed content version\n        $params = @{\n            \"@odata.type\"           = \"#microsoft.graph.windowsUniversalAppX\"\n            committedContentVersion = \"$ContentVersionId\"\n        }\n        Write-Host \"Updating the application with the new content version...\" -ForegroundColor Yellow\n        Update-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId -BodyParameter ($params | ConvertTo-Json)\n\n        # Return the application details\n        Write-Host \"Application created successfully.\" -ForegroundColor Green\n        Write-Host \"Application Details:\"\n        Get-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId | Format-List\n    }\n    catch {\n        Write-Host -ForegroundColor Red \"Aborting with exception: $($_.Exception.ToString())\"\n\n        # In the event that the creation of the app record in Intune succeeded, but processing/file upload failed, you can remove the comment block around the code below to delete the app record.\n        # This will allow you to re-run the script without having to manually delete the incomplete app record.\n        # Note: This will only work if the app record was successfully created in Intune.\n\n        <#\n        if ($mobileAppId) {\n            Write-Host \"Removing the incomplete application record from Intune...\" -ForegroundColor Yellow\n            Remove-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId\n        }\n        #>\n        break\n    }\n    finally {\n        # Clean up the temporary encrypted copy of the package\n        if ($tempFile -and (Test-Path \"$tempFile\")) {\n            Remove-Item -Path \"$tempFile\" -Force -ErrorAction SilentlyContinue\n        }\n    }\n}\n\n<#\n.SYNOPSIS\nExtracts and parses the manifest of an MSIX/AppX package.\n\n.DESCRIPTION\nThis function opens an .msix/.appx (or .msixbundle/.appxbundle) package, extracts the package manifest,\nand returns a hashtable of the identity metadata required to create a windowsUniversalAppX app in Intune.\n\n.PARAMETER SourceFile\nThe path to the .msix, .msixbundle, .appx, or .appxbundle file.\n\n.EXAMPLE\n$AppInfo = Get-MSIXAppInformation -SourceFile \"C:\\IntuneApps\\Contoso\\Contoso.DemoApp_1.0.0.0_x64.msix\"\n#>\nfunction Get-MSIXAppInformation() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$SourceFile\n    )\n\n    $Ext = [System.IO.Path]::GetExtension(\"$SourceFile\").ToLower()\n    $IsBundle = ($Ext -eq '.msixbundle' -or $Ext -eq '.appxbundle')\n    $ManifestName = if ($IsBundle) { 'AppxBundleManifest.xml' } else { 'AppxManifest.xml' }\n\n    # Read the manifest XML out of the package (an .msix/.appx is a ZIP archive)\n    Add-Type -Assembly System.IO.Compression.FileSystem\n    $zip = [IO.Compression.ZipFile]::OpenRead(\"$SourceFile\")\n    try {\n        $entry = $zip.Entries | Where-Object { $_.FullName -ieq $ManifestName -or $_.Name -ieq $ManifestName } | Select-Object -First 1\n        if (!$entry) {\n            throw \"Could not find '$ManifestName' in '$SourceFile'. The file may not be a valid MSIX/AppX package.\"\n        }\n        $reader = New-Object System.IO.StreamReader($entry.Open())\n        $ManifestXml = $reader.ReadToEnd()\n        $reader.Close()\n    }\n    finally {\n        $zip.Dispose()\n    }\n\n    [xml]$Manifest = $ManifestXml\n\n    # The Identity element lives under <Bundle> for bundles and <Package> for single packages\n    if ($IsBundle) {\n        $Identity = $Manifest.Bundle.Identity\n        # A bundle's identity has no ProcessorArchitecture; collect the distinct architectures of the\n        # contained packages instead.\n        $Architectures = @($Manifest.Bundle.Packages.Package |\n                Where-Object { $_.Architecture } |\n                ForEach-Object { ConvertTo-WindowsArchitecture $_.Architecture } |\n                Select-Object -Unique)\n        if (!$Architectures -or $Architectures.Count -eq 0) { $Architectures = @(\"neutral\") }\n        $ApplicableArchitectures = ($Architectures -join \",\")\n        $DisplayName = $null\n        $PublisherDisplayName = $null\n    }\n    else {\n        $Identity = $Manifest.Package.Identity\n        $ApplicableArchitectures = ConvertTo-WindowsArchitecture $Identity.ProcessorArchitecture\n        $DisplayName = $Manifest.Package.Properties.DisplayName\n        $PublisherDisplayName = $Manifest.Package.Properties.PublisherDisplayName\n    }\n\n    # The identity Publisher (e.g. \"CN=Contoso\") is hashed to produce the Identity Publisher Hash that\n    # Intune stores (the same hash used as the last segment of a package family name).\n    $PublisherHash = Get-MSIXPublisherHash -Publisher $Identity.Publisher\n\n    return @{\n        IdentityName               = $Identity.Name\n        IdentityVersion            = $Identity.Version\n        IdentityPublisher          = $Identity.Publisher\n        IdentityPublisherHash      = $PublisherHash\n        IdentityResourceIdentifier = if ($Identity.ResourceId) { $Identity.ResourceId } else { \"\" }\n        ApplicableArchitectures    = $ApplicableArchitectures\n        IsBundle                   = $IsBundle\n        DisplayName                = $DisplayName\n        PublisherDisplayName       = $PublisherDisplayName\n    }\n}\n\n<#\n.SYNOPSIS\nComputes the Identity Publisher Hash for an MSIX/AppX publisher string.\n\n.DESCRIPTION\nThis function computes the publisher hash that Intune stores in the windowsUniversalAppX\nidentityPublisherHash property. This is the same hash that forms the last segment of a package family\nname (for example, the \"8wekyb3d8bbwe\" in a Microsoft package family name).\n\nThe algorithm is:\n  1. UTF-16LE encode the publisher string.\n  2. Compute its SHA-256 hash.\n  3. Take the first 8 bytes (64 bits) and pad to 65 bits.\n  4. Encode each 5-bit group using the alphabet \"0123456789abcdefghjkmnpqrstvwxyz\".\n\n.PARAMETER Publisher\nThe Identity Publisher string from the manifest (for example, \"CN=Contoso\").\n\n.EXAMPLE\nGet-MSIXPublisherHash -Publisher \"CN=Contoso\"\n#>\nfunction Get-MSIXPublisherHash() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$Publisher\n    )\n\n    $sha256 = [System.Security.Cryptography.SHA256]::Create()\n    try {\n        $hashBytes = $sha256.ComputeHash([System.Text.Encoding]::Unicode.GetBytes($Publisher))\n    }\n    finally {\n        $sha256.Dispose()\n    }\n\n    # Build a binary string from the first 8 bytes (64 bits), then pad to 65 bits so it splits into 13 groups of 5 bits.\n    $binary = -join ($hashBytes[0..7] | ForEach-Object { [System.Convert]::ToString($_, 2).PadLeft(8, '0') })\n    $binary = $binary.PadRight(65, '0')\n\n    $encoding = '0123456789abcdefghjkmnpqrstvwxyz'\n    $result = New-Object System.Text.StringBuilder\n    for ($i = 0; $i -lt 65; $i += 5) {\n        $index = [System.Convert]::ToInt32($binary.Substring($i, 5), 2)\n        [void]$result.Append($encoding[$index])\n    }\n\n    return $result.ToString()\n}\n\n<#\n.SYNOPSIS\nMaps an MSIX/AppX processor architecture to a Graph windowsArchitecture value.\n\n.DESCRIPTION\nThis function maps the ProcessorArchitecture/Architecture value from a package manifest to the\ncorresponding value used by the windowsUniversalAppX applicableArchitectures property.\n\n.PARAMETER Architecture\nThe processor architecture from the manifest (for example, \"x64\", \"x86\", \"arm\", \"arm64\", or \"neutral\").\n\n.EXAMPLE\nConvertTo-WindowsArchitecture \"x64\"\n#>\nfunction ConvertTo-WindowsArchitecture() {\n    param\n    (\n        [parameter(Mandatory = $false)]\n        [string]$Architecture\n    )\n\n    switch (\"$Architecture\".ToLower()) {\n        \"x64\" { \"x64\" }\n        \"x86\" { \"x86\" }\n        \"arm\" { \"arm\" }\n        \"arm64\" { \"arm64\" }\n        \"neutral\" { \"neutral\" }\n        default { \"neutral\" }\n    }\n}\n\n<#\n.SYNOPSIS\nConstructs the JSON body for a windowsUniversalAppX (MSIX/AppX) app.\n\n.DESCRIPTION\nThis function builds the hashtable body used to create a windowsUniversalAppX app in Intune.\n\n.EXAMPLE\n$body = New-MSIXAppBody -displayName \"Contoso Demo App\" -publisher \"Contoso\" -description \"Contoso Demo App\" -fileName \"Contoso.DemoApp_1.0.0.0_x64.msix\" -identityName \"Contoso.DemoApp\" -identityPublisherHash \"ab82cd0xyz\" -identityResourceIdentifier \"\" -identityVersion \"1.0.0.0\" -isBundle $false -applicableArchitectures \"x64\" -applicableDeviceTypes \"desktop\" -minimumSupportedOperatingSystem @{ v10_0 = $true }\n#>\nfunction New-MSIXAppBody() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [string]$displayName,\n\n        [parameter(Mandatory = $true)]\n        [string]$publisher,\n\n        [parameter(Mandatory = $true)]\n        [string]$description,\n\n        [parameter(Mandatory = $true)]\n        [string]$fileName,\n\n        [parameter(Mandatory = $true)]\n        [string]$identityName,\n\n        [parameter(Mandatory = $true)]\n        [string]$identityPublisherHash,\n\n        [parameter(Mandatory = $false)]\n        [string]$identityResourceIdentifier,\n\n        [parameter(Mandatory = $true)]\n        [string]$identityVersion,\n\n        [parameter(Mandatory = $true)]\n        [bool]$isBundle,\n\n        [parameter(Mandatory = $true)]\n        [string]$applicableArchitectures,\n\n        [parameter(Mandatory = $false)]\n        [string]$applicableDeviceTypes = \"desktop\",\n\n        [parameter(Mandatory = $true)]\n        [hashtable]$minimumSupportedOperatingSystem\n    )\n\n    $body = @{ \"@odata.type\" = \"#microsoft.graph.windowsUniversalAppX\" }\n    $body.displayName = $displayName\n    $body.publisher = $publisher\n    $body.description = $description\n    $body.fileName = $fileName\n    $body.developer = \"\"\n    $body.notes = \"\"\n    $body.owner = \"\"\n    $body.isFeatured = $false\n    $body.informationUrl = $null\n    $body.privacyInformationUrl = $null\n    $body.applicableArchitectures = $applicableArchitectures\n    $body.applicableDeviceTypes = $applicableDeviceTypes\n    $body.identityName = $identityName\n    $body.identityPublisherHash = $identityPublisherHash\n    $body.identityResourceIdentifier = $identityResourceIdentifier\n    $body.identityVersion = $identityVersion\n    $body.isBundle = $isBundle\n    $body.minimumSupportedOperatingSystem = $minimumSupportedOperatingSystem\n\n    return $body\n}\n\n<#\n.SYNOPSIS\nConverts an image file to a mimeContent object for use as an app icon.\n\n.DESCRIPTION\nThis function reads an image file from disk, base64-encodes its content, and returns a mimeContent hashtable that can be assigned to a mobileApp's largeIcon property. Supported image types are .png, .jpg, .jpeg, and .gif.\n\n.PARAMETER IconFile\nThe path to the image file to use as the app icon.\n\n.EXAMPLE\n# Creates a mimeContent icon object from a .png file.\nNew-IntuneAppIcon -IconFile \"C:\\IntuneApps\\Contoso\\icon.png\"\n#>\nfunction New-IntuneAppIcon() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$IconFile\n    )\n\n    # Check the icon file exists\n    if (!(Test-Path \"$IconFile\")) {\n        Write-Host \"Icon file '$IconFile' doesn't exist...\" -ForegroundColor Red\n        throw \"Icon file not found: $IconFile\"\n    }\n\n    # Determine the MIME type from the file extension\n    $Extension = [System.IO.Path]::GetExtension(\"$IconFile\").ToLower()\n    switch ($Extension) {\n        \".png\" { $MimeType = \"image/png\" }\n        \".jpg\" { $MimeType = \"image/jpeg\" }\n        \".jpeg\" { $MimeType = \"image/jpeg\" }\n        \".gif\" { $MimeType = \"image/gif\" }\n        default {\n            Write-Host \"Unsupported icon file type '$Extension'. Supported types are .png, .jpg, .jpeg, and .gif.\" -ForegroundColor Red\n            throw \"Unsupported icon file type: $Extension\"\n        }\n    }\n\n    # Read the image file and base64-encode its content\n    $IconContent = [System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes(\"$IconFile\"))\n\n    # Construct and return the mimeContent object (used as the app's largeIcon)\n    $Icon = @{\n        \"@odata.type\" = \"#microsoft.graph.mimeContent\"\n        \"type\"        = $MimeType\n        \"value\"       = $IconContent\n    }\n\n    return $Icon\n}\n\n####################################################\n# Function to test if the source file exists\nFunction Test-SourceFile() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        $SourceFile\n    )\n    try {\n        if (!(Test-Path \"$SourceFile\")) {\n            Write-Host\n            Write-Host \"Source File '$SourceFile' doesn't exist...\" -ForegroundColor Red\n            throw\n        }\n    }\n    catch {\n        Write-Host -ForegroundColor Red $_.Exception.Message\n        Write-Host\n        break\n    }\n}\n\n####################################################\n# Function to generate the AES encryption key\nfunction GenerateKey {\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create()\n        $aesProvider = New-Object System.Security.Cryptography.AesCryptoServiceProvider\n        $aesProvider.GenerateKey()\n        $aesProvider.Key\n    }\n    finally {\n        if ($null -ne $aesProvider) { $aesProvider.Dispose() }\n        if ($null -ne $aes) { $aes.Dispose() }\n    }\n}\n\n####################################################\n# Function to generate the AES initialization vector\nfunction GenerateIV {\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create()\n        $aes.IV\n    }\n    finally {\n        if ($null -ne $aes) { $aes.Dispose() }\n    }\n}\n\n####################################################\n# Function to create the encrypted target file, compute the HMAC value, and return the HMAC value\nfunction EncryptFileWithIV($sourceFile, $targetFile, $encryptionKey, $hmacKey, $initializationVector) {\n    $bufferBlockSize = 1024 * 4\n    $computedMac = $null\n\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create()\n        $hmacSha256 = New-Object System.Security.Cryptography.HMACSHA256\n        $hmacSha256.Key = $hmacKey\n        $hmacLength = $hmacSha256.HashSize / 8\n\n        $buffer = New-Object byte[] $bufferBlockSize\n        $bytesRead = 0\n\n        $targetStream = [System.IO.File]::Open($targetFile, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::Read)\n        $targetStream.Write($buffer, 0, $hmacLength + $initializationVector.Length)\n\n        try {\n            $encryptor = $aes.CreateEncryptor($encryptionKey, $initializationVector)\n            $sourceStream = [System.IO.File]::Open($sourceFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)\n            $cryptoStream = New-Object System.Security.Cryptography.CryptoStream -ArgumentList @($targetStream, $encryptor, [System.Security.Cryptography.CryptoStreamMode]::Write)\n\n            $targetStream = $null\n            while (($bytesRead = $sourceStream.Read($buffer, 0, $bufferBlockSize)) -gt 0) {\n                $cryptoStream.Write($buffer, 0, $bytesRead)\n                $cryptoStream.Flush()\n            }\n            $cryptoStream.FlushFinalBlock()\n        }\n        finally {\n            if ($null -ne $cryptoStream) { $cryptoStream.Dispose() }\n            if ($null -ne $sourceStream) { $sourceStream.Dispose() }\n            if ($null -ne $encryptor) { $encryptor.Dispose() }\n        }\n\n        try {\n            $finalStream = [System.IO.File]::Open($targetFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read)\n\n            $finalStream.Seek($hmacLength, [System.IO.SeekOrigin]::Begin) > $null\n            $finalStream.Write($initializationVector, 0, $initializationVector.Length)\n            $finalStream.Seek($hmacLength, [System.IO.SeekOrigin]::Begin) > $null\n\n            $hmac = $hmacSha256.ComputeHash($finalStream)\n            $computedMac = $hmac\n\n            $finalStream.Seek(0, [System.IO.SeekOrigin]::Begin) > $null\n            $finalStream.Write($hmac, 0, $hmac.Length)\n        }\n        finally {\n            if ($null -ne $finalStream) { $finalStream.Dispose() }\n        }\n    }\n    finally {\n        if ($null -ne $targetStream) { $targetStream.Dispose() }\n        if ($null -ne $aes) { $aes.Dispose() }\n    }\n\n    $computedMac\n}\n\n####################################################\n# Function to encrypt the file and return the file encryption info needed to commit the file\nfunction EncryptFile($sourceFile, $targetFile) {\n\n    $encryptionKey = GenerateKey\n    $hmacKey = GenerateKey\n    $initializationVector = GenerateIV\n\n    # Create the encrypted target file and compute the HMAC value.\n    $mac = EncryptFileWithIV $sourceFile $targetFile $encryptionKey $hmacKey $initializationVector\n\n    # Compute the SHA256 hash of the source file and convert the result to bytes.\n    $fileDigest = (Get-FileHash $sourceFile -Algorithm SHA256).Hash\n    $fileDigestBytes = New-Object byte[] ($fileDigest.Length / 2)\n    for ($i = 0; $i -lt $fileDigest.Length; $i += 2) {\n        $fileDigestBytes[$i / 2] = [System.Convert]::ToByte($fileDigest.Substring($i, 2), 16)\n    }\n\n    # Return an object that will serialize correctly to the file commit Graph API.\n    $encryptionInfo = @{}\n    $encryptionInfo.encryptionKey = [System.Convert]::ToBase64String($encryptionKey)\n    $encryptionInfo.macKey = [System.Convert]::ToBase64String($hmacKey)\n    $encryptionInfo.initializationVector = [System.Convert]::ToBase64String($initializationVector)\n    $encryptionInfo.mac = [System.Convert]::ToBase64String($mac)\n    $encryptionInfo.profileIdentifier = \"ProfileVersion1\"\n    $encryptionInfo.fileDigest = [System.Convert]::ToBase64String($fileDigestBytes)\n    $encryptionInfo.fileDigestAlgorithm = \"SHA256\"\n\n    $fileEncryptionInfo = @{}\n    $fileEncryptionInfo.fileEncryptionInfo = $encryptionInfo\n\n    $fileEncryptionInfo\n}\n\n####################################################\n# Function to wait for file processing to complete by polling the file upload state\nfunction WaitForFileProcessing($fileUri, $stage) {\n    $attempts = 60\n    $waitTimeInSeconds = 1\n    $successState = \"$($stage)Success\"\n    $pendingState = \"$($stage)Pending\"\n\n    $file = $null\n    while ($attempts -gt 0) {\n        $file = Invoke-MgGraphRequest -Method GET -Uri $fileUri\n        if ($file.uploadState -eq $successState) {\n            break\n        }\n        elseif ($file.uploadState -ne $pendingState) {\n            throw \"File upload state is not success: $($file.uploadState)\"\n        }\n\n        Start-Sleep $waitTimeInSeconds\n        $attempts--\n    }\n\n    if ($null -eq $file) {\n        throw \"File request did not complete in the allotted time.\"\n    }\n\n    $file\n}\n\n####################################################\n# Function that splits the source file into chunks and uploads them to the Azure Storage SAS URI location, then finalizes the upload\nfunction UploadFileToAzureStorage($sasUri, $filepath, $blockSizeMB) {\n    # Chunk size in MiB\n    $chunkSizeInBytes = (1024 * 1024 * $blockSizeMB)\n\n    # Read the whole file and find the total chunks.\n    $fileStream = [System.IO.File]::OpenRead($filepath)\n    $chunks = [Math]::Ceiling($fileStream.Length / $chunkSizeInBytes)\n\n    # Upload each chunk.\n    $ids = @()\n    $cc = 1\n    $chunk = 0\n    while ($fileStream.Position -lt $fileStream.Length) {\n        $id = [System.Convert]::ToBase64String([System.Text.Encoding]::ASCII.GetBytes($chunk.ToString(\"0000\")))\n        $ids += $id\n\n        $size = [Math]::Min($chunkSizeInBytes, $fileStream.Length - $fileStream.Position)\n        $body = New-Object byte[] $size\n        $fileStream.Read($body, 0, $size) > $null\n\n        Write-Progress -Activity \"Uploading File to Azure Storage\" -Status \"Uploading chunk $cc of $chunks\" -PercentComplete ($cc / $chunks * 100)\n        $cc++\n\n        UploadAzureStorageChunk $sasUri $id $body | Out-Null\n        $chunk++\n    }\n\n    $fileStream.Close()\n    Write-Progress -Completed -Activity \"Uploading File to Azure Storage\"\n\n    # Finalize the upload.\n    FinalizeAzureStorageUpload $sasUri $ids | Out-Null\n}\n\n####################################################\n# Function to upload a chunk to Azure Storage\nfunction UploadAzureStorageChunk($sasUri, $id, $body) {\n    $uri = \"$sasUri&comp=block&blockid=$id\"\n    $request = \"PUT $uri\"\n\n    $headers = @{\n        \"x-ms-blob-type\" = \"BlockBlob\"\n        \"Content-Type\"   = \"application/octet-stream\"\n    }\n\n    try {\n        Invoke-WebRequest -Headers $headers $uri -Method Put -Body $body | Out-Null\n    }\n    catch {\n        Write-Host -ForegroundColor Red $request\n        Write-Host -ForegroundColor Red $_.Exception.Message\n        throw\n    }\n}\n\n####################################################\n# Function to finalize the Azure Storage upload by joining the uploaded chunks\nfunction FinalizeAzureStorageUpload($sasUri, $ids) {\n    $uri = \"$sasUri&comp=blocklist\"\n    $request = \"PUT $uri\"\n\n    $xml = '<?xml version=\"1.0\" encoding=\"utf-8\"?><BlockList>'\n    foreach ($id in $ids) {\n        $xml += \"<Latest>$id</Latest>\"\n    }\n    $xml += '</BlockList>'\n\n    $headers = @{\n        \"Content-Type\" = \"text/plain\"\n    }\n\n    try {\n        Invoke-WebRequest $uri -Method Put -Body $xml -Headers $headers | Out-Null\n    }\n    catch {\n        Write-Host -ForegroundColor Red $request\n        Write-Host -ForegroundColor Red $_.Exception.Message\n        throw\n    }\n}\n\n####################################################\n# Function to create a new mobileAppContentFile body containing the file information\nfunction GetAppFileBody($name, $size, $sizeEncrypted, $manifest) {\n    $body = @{ \"@odata.type\" = \"#microsoft.graph.mobileAppContentFile\" }\n    $body.name = $name\n    $body.size = $size\n    $body.sizeEncrypted = $sizeEncrypted\n    $body.manifest = $manifest\n    $body.isDependency = $false\n\n    $body\n}\n","teaching":["Add an MSIX application resource","MSIX provides a Windows packaging format. App resource creation, content upload, trust, requirements and deployment are distinct operations.","Write reference only. Inspect package metadata and signer trust; do not upload or install software in a live environment.","Design a fictional package with version, publisher and test assignment.",null,"Which Windows packaging format is covered?","msix"],"kind":"write-reference-only"},{"repository":"microsoft/mggraph-intune-samples","path":"LOB_Application/MSIX_Application_Update.ps1","sha":"3f091ca973943bf2b3efaba802a28896165db77b","lesson":13,"topic":"Update an MSIX application resource","url":"https://github.com/microsoft/mggraph-intune-samples/blob/main/LOB_Application/MSIX_Application_Update.ps1","markdown":"<#\n.COPYRIGHT\nCopyright (c) Microsoft Corporation. All rights reserved. Licensed under the MIT license.\nSee LICENSE in the project root for license information.\n#>\n\n#requires -module Microsoft.Graph.Devices.CorporateManagement\n#requires -module Microsoft.Graph.Authentication\n\n<# region Authentication\nTo authenticate, you'll use the Microsoft Graph PowerShell SDK. If you haven't already installed the SDK, see this guide:\nhttps://learn.microsoft.com/en-us/powershell/microsoftgraph/installation?view=graph-powershell-1.0\nThe PowerShell SDK supports two types of authentication: delegated access, and app-only access.\nFor details on using delegated access, see this guide here:\nhttps://learn.microsoft.com/powershell/microsoftgraph/get-started?view=graph-powershell-1.0\nFor details on using app-only access for unattended scenarios, see Use app-only authentication with the Microsoft Graph PowerShell SDK:\nhttps://learn.microsoft.com/powershell/microsoftgraph/app-only?view=graph-powershell-1.0&tabs=azure-portal\n#>\n\n<#\n.SYNOPSIS\nUpdates an MSIX/AppX line-of-business app (windowsUniversalAppX) in Intune.\n\n.DESCRIPTION\nThis function updates an existing MSIX/AppX line-of-business app in Intune by uploading a new package as a\nnew content version. The new .msix/.appx is encrypted locally, uploaded to Azure Storage, and committed,\nthen the app is pointed at the new content version. A windowsUniversalAppX app's package identity\n(identityName, identityPublisherHash, identityVersion, isBundle, applicableArchitectures, etc.) is read-only\nafter creation, so an update changes only the package content plus any editable metadata (display name,\npublisher, description, icon).\n\nNote: Intune requires that an updated windowsUniversalAppX package has the same Identity Name and Publisher\nas the existing app. Typically only the Identity Version increases between updates.\n\n.PARAMETER AppId\nThe ID of the Intune windowsUniversalAppX app to update.\n\n.PARAMETER UpdateAppContentOnly\nIf $true, only the app package content is updated and other app properties (e.g. Name, identity, etc.) are not updated.\n\n.PARAMETER SourceFile\nThe path to the .msix, .msixbundle, .appx, or .appxbundle file.\n\n.PARAMETER displayName\nThe new display name of the app. Only applied when -UpdateAppContentOnly is $false. If omitted, the existing display name is left unchanged.\n\n.PARAMETER publisher\nThe new publisher of the app. Only applied when -UpdateAppContentOnly is $false. If omitted, the existing publisher is left unchanged.\n\n.PARAMETER description\nThe new description of the app. Only applied when -UpdateAppContentOnly is $false. If omitted, the existing description is left unchanged.\n\n.PARAMETER minimumSupportedOperatingSystem\nThe minimum supported operating system for the app, as a windowsMinimumOperatingSystem hashtable.\nValid keys for windowsUniversalAppX are 'v8_0', 'v8_1', and 'v10_0'. Only applied when -UpdateAppContentOnly is $false and a value is supplied.\n\n.PARAMETER IconFile\nThe path to an image file (.png, .jpg, .jpeg, or .gif) to use as the app icon. The image is converted to a mimeContent object and uploaded as the app's largeIcon. Optional, and applied whether or not -UpdateAppContentOnly is used.\n\n.EXAMPLE\n# Updates only the package content of an existing MSIX app.\nInvoke-MSIXAppUpdate -AppId \"12345678-1234-1234-1234-123456789012\" -UpdateAppContentOnly $true -SourceFile \"C:\\IntuneApps\\Contoso\\Contoso.DemoApp_1.1.0.0_x64.msix\"\n\n.EXAMPLE\n# Updates the package content and app properties of an existing MSIX app.\nInvoke-MSIXAppUpdate -AppId \"12345678-1234-1234-1234-123456789012\" -UpdateAppContentOnly $false -SourceFile \"C:\\IntuneApps\\Contoso\\Contoso.DemoApp_1.1.0.0_x64.msix\" -displayName \"Contoso Demo App\" -publisher \"Contoso\" -description \"Version 1.1.0.0\"\n\n.EXAMPLE\n# Updates only the app icon of an existing MSIX app (still requires a source package for the new content version).\nInvoke-MSIXAppUpdate -AppId \"12345678-1234-1234-1234-123456789012\" -UpdateAppContentOnly $true -SourceFile \"C:\\IntuneApps\\Contoso\\Contoso.DemoApp_1.0.0.0_x64.msix\" -IconFile \"C:\\IntuneApps\\Contoso\\icon.png\"\n#>\nfunction Invoke-MSIXAppUpdate {\n    [cmdletbinding()]\n    param\n    (\n        [parameter(Mandatory = $true, Position = 1)]\n        [ValidateNotNullOrEmpty()]\n        [string]$AppId,\n\n        [parameter(Mandatory = $true, Position = 2)]\n        [bool]$UpdateAppContentOnly,\n\n        [parameter(Mandatory = $true, Position = 3)]\n        [ValidateNotNullOrEmpty()]\n        [string]$SourceFile,\n\n        [parameter(Mandatory = $false, Position = 4)]\n        [string]$displayName,\n\n        [parameter(Mandatory = $false, Position = 5)]\n        [string]$publisher,\n\n        [parameter(Mandatory = $false, Position = 6)]\n        [string]$description,\n\n        [parameter(Mandatory = $false, Position = 7)]\n        [hashtable]$minimumSupportedOperatingSystem,\n\n        [parameter(Mandatory = $false, Position = 8)]\n        [string]$IconFile\n    )\n\n    # Temp encrypted copy of the package (created during the encryption step, removed in the finally block)\n    $tempFile = $null\n\n    try {\n        # Check if the app exists\n        $MobileApp = Get-MgDeviceAppManagementMobileApp -MobileAppId $AppId\n\n        if ($null -eq $MobileApp) {\n            Write-Host \"Application with ID '$AppId' does not exist in Intune.\" -ForegroundColor Red\n            break\n        }\n\n        Write-Host \"Application found...\" -ForegroundColor Yellow\n        $mobileAppId = $MobileApp.id\n\n        # Check if the source file exists and has a supported extension\n        Write-Host \"Testing if SourceFile '$SourceFile' Path is valid...\" -ForegroundColor Yellow\n        Test-SourceFile \"$SourceFile\"\n\n        $Ext = [System.IO.Path]::GetExtension(\"$SourceFile\").ToLower()\n        if ($Ext -notin '.msix', '.msixbundle', '.appx', '.appxbundle') {\n            throw \"Unsupported file type '$Ext'. Supported types are .msix, .msixbundle, .appx, and .appxbundle.\"\n        }\n\n        $FileName = [System.IO.Path]::GetFileName(\"$SourceFile\")\n\n        # Note: a windowsUniversalAppX app's package identity (identityName, identityPublisherHash,\n        # identityVersion, isBundle, applicableArchitectures, etc.) is read-only after creation - the\n        # service re-derives it from the newly committed package content. An update therefore only changes\n        # the package content plus any editable metadata (display name, publisher, description, icon).\n\n        # Create a new content version for the application\n        Write-Host \"Creating Content Version in the service for the updated application...\" -ForegroundColor Yellow\n        $ContentVersion = New-MgDeviceAppManagementMobileAppAsWindowsUniversalAppXContentVersion -MobileAppId $mobileAppId -BodyParameter @{}\n        $ContentVersionId = $ContentVersion.id\n\n        # Encrypt a copy of the package. Unlike a .intunewin file (which is already encrypted), the .msix is\n        # a raw file, so the script generates the encryption keys and computes the file digest itself.\n        Write-Host \"Encrypting a copy of the package '$SourceFile'...\" -ForegroundColor Yellow\n        $tempFile = [System.IO.Path]::Combine([System.IO.Path]::GetDirectoryName(\"$SourceFile\"), [System.IO.Path]::GetFileNameWithoutExtension(\"$SourceFile\") + \"_\" + [guid]::NewGuid().ToString() + \"_temp.bin\")\n        $fileEncryptionInfo = EncryptFile \"$SourceFile\" \"$tempFile\"\n\n        [int64]$Size = (Get-Item \"$SourceFile\").Length\n        $EncrySize = (Get-Item \"$tempFile\").Length\n\n        # Create a new file entry in Azure for the upload. Unlike Win32/macOS content files, a\n        # windowsUniversalAppX content file requires a (non-null) manifest. For MSIX/AppX the service only\n        # requires the base64-encoded file name here (the rich identity metadata is supplied on the app body).\n        $encodedManifest = [System.Convert]::ToBase64String([System.Text.Encoding]::ASCII.GetBytes($FileName))\n        $fileBody = GetAppFileBody \"$FileName\" $Size $EncrySize $encodedManifest\n        Write-Host \"Creating a new file entry in Azure for the upload...\" -ForegroundColor Yellow\n        $ContentVersionFile = New-MgDeviceAppManagementMobileAppAsWindowsUniversalAppXContentVersionFile -MobileAppId $mobileAppId -MobileAppContentId $ContentVersionId -BodyParameter ($fileBody | ConvertTo-Json)\n        $ContentVersionFileId = $ContentVersionFile.id\n\n        # Get the file URI for the upload\n        $fileUri = \"https://graph.microsoft.com/beta/deviceAppManagement/mobileApps/$mobileAppId/microsoft.graph.windowsUniversalAppX/contentVersions/$ContentVersionId/files/$ContentVersionFileId\"\n\n        # Wait for the Azure Storage SAS URI to be created\n        Write-Host \"Waiting for the file entry SAS URI to be created...\" -ForegroundColor Yellow\n        $file = WaitForFileProcessing $fileUri \"AzureStorageUriRequest\"\n\n        # Upload the encrypted file to Azure Storage\n        Write-Host \"Uploading the file to Azure Storage...\" -ForegroundColor Yellow\n        [UInt64]$BlockSizeMB = 4\n        UploadFileToAzureStorage $file.azureStorageUri \"$tempFile\" $BlockSizeMB\n\n        # Commit the file to the service using the encryption information\n        Write-Host \"Committing the file to the service...\" -ForegroundColor Yellow\n        Start-Sleep -Seconds 5\n        Invoke-MgCommitDeviceAppManagementMobileAppMicrosoftGraphWindowsUniversalAppXContentVersionFile -MobileAppId $mobileAppId -MobileAppContentId $ContentVersionId -MobileAppContentFileId $ContentVersionFileId -BodyParameter ($fileEncryptionInfo | ConvertTo-Json)\n\n        # Wait for the file to be processed\n        Write-Host \"Waiting for the file to be processed...\" -ForegroundColor Yellow\n        $file = WaitForFileProcessing $fileUri \"CommitFile\"\n\n        # Build the body that points the app at the new committed content version. Only editable metadata is\n        # included; the package identity is read-only and is re-derived from the committed content. Editable\n        # fields are set only when supplied so an update never overwrites the existing display name,\n        # publisher, or description with values that were not requested.\n        $params = @{\n            \"@odata.type\"           = \"#microsoft.graph.windowsUniversalAppX\"\n            committedContentVersion = \"$ContentVersionId\"\n        }\n\n        if (-not $UpdateAppContentOnly) {\n            if ($displayName) { $params.displayName = $displayName }\n            if ($publisher) { $params.publisher = $publisher }\n            if ($description) { $params.description = $description }\n            if ($minimumSupportedOperatingSystem) { $params.minimumSupportedOperatingSystem = $minimumSupportedOperatingSystem }\n        }\n\n        # Add the app icon (largeIcon) if an icon file was provided\n        if ($IconFile) {\n            Write-Host \"Adding app icon from '$IconFile'...\" -ForegroundColor Yellow\n            $params[\"largeIcon\"] = New-IntuneAppIcon -IconFile $IconFile\n        }\n\n        # Update the application with the new content version\n        Write-Host \"Updating the application with the new content version...\" -ForegroundColor Yellow\n        Update-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId -BodyParameter ($params | ConvertTo-Json)\n\n        # Return the application details\n        Write-Host \"Application updated successfully:\" -ForegroundColor Green\n        Get-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId | Format-List\n    }\n    catch {\n        Write-Host -ForegroundColor Red \"Aborting with exception: $($_.Exception.ToString())\"\n        break\n    }\n    finally {\n        # Clean up the temporary encrypted copy of the package\n        if ($tempFile -and (Test-Path \"$tempFile\")) {\n            Remove-Item -Path \"$tempFile\" -Force -ErrorAction SilentlyContinue\n        }\n    }\n}\n\n<#\n.SYNOPSIS\nConverts an image file to a mimeContent object for use as an app icon.\n\n.DESCRIPTION\nThis function reads an image file from disk, base64-encodes its content, and returns a mimeContent hashtable that can be assigned to a mobileApp's largeIcon property. Supported image types are .png, .jpg, .jpeg, and .gif.\n\n.PARAMETER IconFile\nThe path to the image file to use as the app icon.\n\n.EXAMPLE\n# Creates a mimeContent icon object from a .png file.\nNew-IntuneAppIcon -IconFile \"C:\\IntuneApps\\Contoso\\icon.png\"\n#>\nfunction New-IntuneAppIcon() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$IconFile\n    )\n\n    # Check the icon file exists\n    if (!(Test-Path \"$IconFile\")) {\n        Write-Host \"Icon file '$IconFile' doesn't exist...\" -ForegroundColor Red\n        throw \"Icon file not found: $IconFile\"\n    }\n\n    # Determine the MIME type from the file extension\n    $Extension = [System.IO.Path]::GetExtension(\"$IconFile\").ToLower()\n    switch ($Extension) {\n        \".png\" { $MimeType = \"image/png\" }\n        \".jpg\" { $MimeType = \"image/jpeg\" }\n        \".jpeg\" { $MimeType = \"image/jpeg\" }\n        \".gif\" { $MimeType = \"image/gif\" }\n        default {\n            Write-Host \"Unsupported icon file type '$Extension'. Supported types are .png, .jpg, .jpeg, and .gif.\" -ForegroundColor Red\n            throw \"Unsupported icon file type: $Extension\"\n        }\n    }\n\n    # Read the image file and base64-encode its content\n    $IconContent = [System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes(\"$IconFile\"))\n\n    # Construct and return the mimeContent object (used as the app's largeIcon)\n    $Icon = @{\n        \"@odata.type\" = \"#microsoft.graph.mimeContent\"\n        \"type\"        = $MimeType\n        \"value\"       = $IconContent\n    }\n\n    return $Icon\n}\n\n####################################################\n# Function to test if the source file exists\nFunction Test-SourceFile() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        $SourceFile\n    )\n    try {\n        if (!(Test-Path \"$SourceFile\")) {\n            Write-Host\n            Write-Host \"Source File '$SourceFile' doesn't exist...\" -ForegroundColor Red\n            throw\n        }\n    }\n    catch {\n        Write-Host -ForegroundColor Red $_.Exception.Message\n        Write-Host\n        break\n    }\n}\n\n####################################################\n# Function to generate the AES encryption key\nfunction GenerateKey {\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create()\n        $aesProvider = New-Object System.Security.Cryptography.AesCryptoServiceProvider\n        $aesProvider.GenerateKey()\n        $aesProvider.Key\n    }\n    finally {\n        if ($null -ne $aesProvider) { $aesProvider.Dispose() }\n        if ($null -ne $aes) { $aes.Dispose() }\n    }\n}\n\n####################################################\n# Function to generate the AES initialization vector\nfunction GenerateIV {\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create()\n        $aes.IV\n    }\n    finally {\n        if ($null -ne $aes) { $aes.Dispose() }\n    }\n}\n\n####################################################\n# Function to create the encrypted target file, compute the HMAC value, and return the HMAC value\nfunction EncryptFileWithIV($sourceFile, $targetFile, $encryptionKey, $hmacKey, $initializationVector) {\n    $bufferBlockSize = 1024 * 4\n    $computedMac = $null\n\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create()\n        $hmacSha256 = New-Object System.Security.Cryptography.HMACSHA256\n        $hmacSha256.Key = $hmacKey\n        $hmacLength = $hmacSha256.HashSize / 8\n\n        $buffer = New-Object byte[] $bufferBlockSize\n        $bytesRead = 0\n\n        $targetStream = [System.IO.File]::Open($targetFile, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::Read)\n        $targetStream.Write($buffer, 0, $hmacLength + $initializationVector.Length)\n\n        try {\n            $encryptor = $aes.CreateEncryptor($encryptionKey, $initializationVector)\n            $sourceStream = [System.IO.File]::Open($sourceFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)\n            $cryptoStream = New-Object System.Security.Cryptography.CryptoStream -ArgumentList @($targetStream, $encryptor, [System.Security.Cryptography.CryptoStreamMode]::Write)\n\n            $targetStream = $null\n            while (($bytesRead = $sourceStream.Read($buffer, 0, $bufferBlockSize)) -gt 0) {\n                $cryptoStream.Write($buffer, 0, $bytesRead)\n                $cryptoStream.Flush()\n            }\n            $cryptoStream.FlushFinalBlock()\n        }\n        finally {\n            if ($null -ne $cryptoStream) { $cryptoStream.Dispose() }\n            if ($null -ne $sourceStream) { $sourceStream.Dispose() }\n            if ($null -ne $encryptor) { $encryptor.Dispose() }\n        }\n\n        try {\n            $finalStream = [System.IO.File]::Open($targetFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read)\n\n            $finalStream.Seek($hmacLength, [System.IO.SeekOrigin]::Begin) > $null\n            $finalStream.Write($initializationVector, 0, $initializationVector.Length)\n            $finalStream.Seek($hmacLength, [System.IO.SeekOrigin]::Begin) > $null\n\n            $hmac = $hmacSha256.ComputeHash($finalStream)\n            $computedMac = $hmac\n\n            $finalStream.Seek(0, [System.IO.SeekOrigin]::Begin) > $null\n            $finalStream.Write($hmac, 0, $hmac.Length)\n        }\n        finally {\n            if ($null -ne $finalStream) { $finalStream.Dispose() }\n        }\n    }\n    finally {\n        if ($null -ne $targetStream) { $targetStream.Dispose() }\n        if ($null -ne $aes) { $aes.Dispose() }\n    }\n\n    $computedMac\n}\n\n####################################################\n# Function to encrypt the file and return the file encryption info needed to commit the file\nfunction EncryptFile($sourceFile, $targetFile) {\n\n    $encryptionKey = GenerateKey\n    $hmacKey = GenerateKey\n    $initializationVector = GenerateIV\n\n    # Create the encrypted target file and compute the HMAC value.\n    $mac = EncryptFileWithIV $sourceFile $targetFile $encryptionKey $hmacKey $initializationVector\n\n    # Compute the SHA256 hash of the source file and convert the result to bytes.\n    $fileDigest = (Get-FileHash $sourceFile -Algorithm SHA256).Hash\n    $fileDigestBytes = New-Object byte[] ($fileDigest.Length / 2)\n    for ($i = 0; $i -lt $fileDigest.Length; $i += 2) {\n        $fileDigestBytes[$i / 2] = [System.Convert]::ToByte($fileDigest.Substring($i, 2), 16)\n    }\n\n    # Return an object that will serialize correctly to the file commit Graph API.\n    $encryptionInfo = @{}\n    $encryptionInfo.encryptionKey = [System.Convert]::ToBase64String($encryptionKey)\n    $encryptionInfo.macKey = [System.Convert]::ToBase64String($hmacKey)\n    $encryptionInfo.initializationVector = [System.Convert]::ToBase64String($initializationVector)\n    $encryptionInfo.mac = [System.Convert]::ToBase64String($mac)\n    $encryptionInfo.profileIdentifier = \"ProfileVersion1\"\n    $encryptionInfo.fileDigest = [System.Convert]::ToBase64String($fileDigestBytes)\n    $encryptionInfo.fileDigestAlgorithm = \"SHA256\"\n\n    $fileEncryptionInfo = @{}\n    $fileEncryptionInfo.fileEncryptionInfo = $encryptionInfo\n\n    $fileEncryptionInfo\n}\n\n####################################################\n# Function to wait for file processing to complete by polling the file upload state\nfunction WaitForFileProcessing($fileUri, $stage) {\n    $attempts = 60\n    $waitTimeInSeconds = 1\n    $successState = \"$($stage)Success\"\n    $pendingState = \"$($stage)Pending\"\n\n    $file = $null\n    while ($attempts -gt 0) {\n        $file = Invoke-MgGraphRequest -Method GET -Uri $fileUri\n        if ($file.uploadState -eq $successState) {\n            break\n        }\n        elseif ($file.uploadState -ne $pendingState) {\n            throw \"File upload state is not success: $($file.uploadState)\"\n        }\n\n        Start-Sleep $waitTimeInSeconds\n        $attempts--\n    }\n\n    if ($null -eq $file) {\n        throw \"File request did not complete in the allotted time.\"\n    }\n\n    $file\n}\n\n####################################################\n# Function that splits the source file into chunks and uploads them to the Azure Storage SAS URI location, then finalizes the upload\nfunction UploadFileToAzureStorage($sasUri, $filepath, $blockSizeMB) {\n    # Chunk size in MiB\n    $chunkSizeInBytes = (1024 * 1024 * $blockSizeMB)\n\n    # Read the whole file and find the total chunks.\n    $fileStream = [System.IO.File]::OpenRead($filepath)\n    $chunks = [Math]::Ceiling($fileStream.Length / $chunkSizeInBytes)\n\n    # Upload each chunk.\n    $ids = @()\n    $cc = 1\n    $chunk = 0\n    while ($fileStream.Position -lt $fileStream.Length) {\n        $id = [System.Convert]::ToBase64String([System.Text.Encoding]::ASCII.GetBytes($chunk.ToString(\"0000\")))\n        $ids += $id\n\n        $size = [Math]::Min($chunkSizeInBytes, $fileStream.Length - $fileStream.Position)\n        $body = New-Object byte[] $size\n        $fileStream.Read($body, 0, $size) > $null\n\n        Write-Progress -Activity \"Uploading File to Azure Storage\" -Status \"Uploading chunk $cc of $chunks\" -PercentComplete ($cc / $chunks * 100)\n        $cc++\n\n        UploadAzureStorageChunk $sasUri $id $body | Out-Null\n        $chunk++\n    }\n\n    $fileStream.Close()\n    Write-Progress -Completed -Activity \"Uploading File to Azure Storage\"\n\n    # Finalize the upload.\n    FinalizeAzureStorageUpload $sasUri $ids | Out-Null\n}\n\n####################################################\n# Function to upload a chunk to Azure Storage\nfunction UploadAzureStorageChunk($sasUri, $id, $body) {\n    $uri = \"$sasUri&comp=block&blockid=$id\"\n    $request = \"PUT $uri\"\n\n    $headers = @{\n        \"x-ms-blob-type\" = \"BlockBlob\"\n        \"Content-Type\"   = \"application/octet-stream\"\n    }\n\n    try {\n        Invoke-WebRequest -Headers $headers $uri -Method Put -Body $body | Out-Null\n    }\n    catch {\n        Write-Host -ForegroundColor Red $request\n        Write-Host -ForegroundColor Red $_.Exception.Message\n        throw\n    }\n}\n\n####################################################\n# Function to finalize the Azure Storage upload by joining the uploaded chunks\nfunction FinalizeAzureStorageUpload($sasUri, $ids) {\n    $uri = \"$sasUri&comp=blocklist\"\n    $request = \"PUT $uri\"\n\n    $xml = '<?xml version=\"1.0\" encoding=\"utf-8\"?><BlockList>'\n    foreach ($id in $ids) {\n        $xml += \"<Latest>$id</Latest>\"\n    }\n    $xml += '</BlockList>'\n\n    $headers = @{\n        \"Content-Type\" = \"text/plain\"\n    }\n\n    try {\n        Invoke-WebRequest $uri -Method Put -Body $xml -Headers $headers | Out-Null\n    }\n    catch {\n        Write-Host -ForegroundColor Red $request\n        Write-Host -ForegroundColor Red $_.Exception.Message\n        throw\n    }\n}\n\n####################################################\n# Function to create a new mobileAppContentFile body containing the file information\nfunction GetAppFileBody($name, $size, $sizeEncrypted, $manifest) {\n    $body = @{ \"@odata.type\" = \"#microsoft.graph.mobileAppContentFile\" }\n    $body.name = $name\n    $body.size = $size\n    $body.sizeEncrypted = $sizeEncrypted\n    $body.manifest = $manifest\n    $body.isDependency = $false\n\n    $body\n}\n","teaching":["Update an MSIX application resource","App updates may alter resource metadata and package content. Version and compatibility determine whether existing installations update as intended.","No live update. Use a fictional version change and verify rollback planning.","Compare v1 and v2 package metadata, intended assignment and actual install evidence.",null,"What distinguishes revisions of a package?","version"],"kind":"write-reference-only"},{"repository":"microsoft/mggraph-intune-samples","path":"LOB_Application/Win32_Application_Add.ps1","sha":"bc6bb090cd689f847aa1773a7bbb8f9b52502c87","lesson":13,"topic":"Add Win32 app and upload content","url":"https://github.com/microsoft/mggraph-intune-samples/blob/main/LOB_Application/Win32_Application_Add.ps1","markdown":"<#\n.COPYRIGHT\nCopyright (c) Microsoft Corporation. All rights reserved. Licensed under the MIT license.\nSee LICENSE in the project root for license information.\n#>\n\n#requires -module Microsoft.Graph.Devices.CorporateManagement\n#requires -module Microsoft.Graph.Authentication\n\n<# region Authentication\nTo authenticate, you'll use the Microsoft Graph PowerShell SDK. If you haven't already installed the SDK, see this guide:\nhttps://learn.microsoft.com/en-us/powershell/microsoftgraph/installation?view=graph-powershell-1.0\nThe PowerShell SDK supports two types of authentication: delegated access, and app-only access.\nFor details on using delegated access, see this guide here:\nhttps://learn.microsoft.com/powershell/microsoftgraph/get-started?view=graph-powershell-1.0\nFor details on using app-only access for unattended scenarios, see Use app-only authentication with the Microsoft Graph PowerShell SDK:\nhttps://learn.microsoft.com/powershell/microsoftgraph/app-only?view=graph-powershell-1.0&tabs=azure-portal\n#>\n\n<#\n.SYNOPSIS\nUploads a Win32 app to Intune.\n\n.DESCRIPTION\nThis function uploads a Win32 app to Intune. The script extracts the detection.xml file from the .intunewin file and uses the information to create the app in Intune. The script then uploads the .intunewin file to Azure Storage and commits the file to the service.\n\n.PARAMETER SourceFile\nThe path to the .intunewin file.\n\n.PARAMETER displayName\nThe display name of the app. If not specified, the script uses the Name from the detection.xml file.\n\n.PARAMETER publisher\nThe publisher of the app.\n\n.PARAMETER description\nThe description of the app.\n\n.PARAMETER Rules\nAn array of rules to apply to the app. You can use the New-FileSystemRule, New-ProductCodeRule, New-RegistryRule, New-ScriptDetectionRule, and New-ScriptRequirementRule functions to create the rules.\n\n.PARAMETER returnCodes\nAn array of return codes to apply to the app. You can use the Get-DefaultReturnCodes and New-ReturnCode functions to create the return codes.\n\n.PARAMETER installCommandLine\nThe command line to install the app. Required for EXE files.\n\n.PARAMETER uninstallCommandLine\nThe command line to uninstall the app. Required for EXE files.\n\n.PARAMETER RunAsAccount\nThe account to run the app as. Valid values are 'system' or 'user'.\n\n.PARAMETER DeviceRestartBehavior\nThe device restart behavior for the app. Valid values are 'basedOnReturnCode', 'allow', 'suppress', 'force'.\n\n.PARAMETER IconFile\nThe path to an image file (.png, .jpg, .jpeg, or .gif) to use as the app icon. The image is converted to a mimeContent object and uploaded as the app's largeIcon. Optional.\n\n.EXAMPLE\n# Uploads a .exe Win32 app to Intune using the default return codes and a file system rule.\n$returnCodes = Get-DefaultReturnCodes\n$Rules = @()\n$Rules += New-FileSystemRule -ruleType detection -check32BitOn64System $false -operationType exists -operator notConfigured -comparisonValue $null -fileOrFolderName \"code.exe\" -path 'C:\\Program Files\\Microsoft VS Code'\nInvoke-Win32AppUpload -SourceFile \"C:\\IntuneApps\\vscode\\VSCodeSetup-x64-1.93.1.intunewin\" -displayName \"VS Code\" -publisher \"Microsoft\" -description \"VS Code\" -Rules $Rules -returnCodes $returnCodes -installCommandLine \"VSCodeSetup-x64-1.93.1.exe /VERYSILENT /MERGETASKS=!runcode\" -uninstallCommandLine \"C:\\Program Files\\Microsoft VS Code\\unins000.exe /VERYSILENT\" -DeviceRestartBehavior \"basedOnReturnCode\" -RunAsAccount \"system\" \n\n.EXAMPLE\n# Uploads a .msi Win32 app to Intune using the default return codes and a product code rule.\n$returnCodes = Get-DefaultReturnCodes\n$Rules = @()\n$Rules += New-FileSystemRule -ruleType detection -operator notConfigured -check32BitOn64System $false -operationType exists -comparisonValue $null -fileOrFolderName \"firefox.exe\" -path 'C:\\Program Files\\Mozilla Firefox\\firefox.exe'\n$Rules += New-ProductCodeRule -ruleType detection -productCode \"{3248F0A8-6813-4B6F-8C3A-4B6C4F512345}\" -productVersionOperator equal -productVersion \"130.0\"\nInvoke-Win32AppUpload -SourceFile \"C:\\IntuneApps\\Firefox\\Firefox_Setup_130.0.intunewin\" -displayName \"Firefox\" -publisher \"Mozilla\" -returnCodes $returnCodes -description \"Firefox browser\" -Rules $Rules -RunAsAccount \"system\" -DeviceRestartBehavior \"suppress\" \n\n.EXAMPLE\n# Uploads a Win32 app to Intune using the default return codes, a script detection rule, a script requirement rule, and a registry rule, and a registry rule.\n$returnCodes = Get-DefaultReturnCodes\n$Rules = @()\n$Rules += New-ScriptRequirementRule -ScriptFile \"E:\\VSCodeRequirement.ps1\" -DisplayName \"VS Code Requirement\" -EnforceSignatureCheck $false -RunAs32Bit $false -RunAsAccount \"system\" -OperationType \"integer\" -Operator \"equal\" -ComparisonValue \"0\"\n$Rules += New-ScriptDetectionRule -ScriptFile \"E:\\VSCodeDetection.ps1\" -EnforceSignatureCheck $false -RunAs32Bit $false \n$Rules += New-RegistryRule -ruleType detection -keyPath \"HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\xyz\" -valueName \"DisplayName\" -operationType string -operator equal -comparisonValue \"VSCode\"\nInvoke-Win32AppUpload -displayName \"VS Code\" -SourceFile \"C:\\IntuneApps\\vscode\\VSCodeSetup-x64-1.93.1.intunewin\" -publisher \"Microsoft\" -description \"VS Code (script detection)\" -RunAsAccount \"system\" -Rules $Rules -returnCodes $returnCodes -InstallCommandLine \"VSCodeSetup-x64-1.93.1.exe /VERYSILENT /MERGETASKS=!runcode\" -UninstallCommandLine \"C:\\Program Files\\Microsoft VS Code\\unins000.exe /VERYSILENT\" -DeviceRestartBehavior \"basedOnReturnCode\"\n#>\nfunction Invoke-Win32AppUpload {\n    [cmdletbinding()]\n    param\n    (\n        [parameter(Mandatory = $true, Position = 1)]\n        [ValidateNotNullOrEmpty()]\n        [string]$SourceFile,\n\n        [parameter(Mandatory = $false, Position = 2)]\n        [ValidateNotNullOrEmpty()]\n        [string]$displayName,\n\n        [parameter(Mandatory = $true, Position = 3)]\n        [ValidateNotNullOrEmpty()]\n        [string]$publisher,\n\n        [parameter(Mandatory = $true, Position = 4)]\n        [ValidateNotNullOrEmpty()]\n        [string]$description,\n\n        [parameter(Mandatory = $true, Position = 6)]\n        [ValidateNotNullOrEmpty()]\n        $Rules,\n\n        [parameter(Mandatory = $true, Position = 7)]\n        [ValidateNotNullOrEmpty()]\n        $returnCodes,\n\n        [parameter(Mandatory = $false, Position = 8)]\n        [string]$installCommandLine,\n\n        [parameter(Mandatory = $false, Position = 9)]\n        [string]$uninstallCommandLine,\n\n        [parameter(Mandatory = $false, Position = 10)]\n        [ValidateSet('system', 'user')]\n        [string]$RunAsAccount,\n\n        [parameter(Mandatory = $true, Position = 11)]\n        [ValidateSet('basedOnReturnCode', 'allow', 'suppress', 'force')]\n        [string]$DeviceRestartBehavior,\n\n        [parameter(Mandatory = $false, Position = 12)]\n        [string]$IconFile\n    )\n    try\t{\n\n        # Check if the source file exists\n        Write-Host \"Testing if SourceFile '$SourceFile' Path is valid...\" -ForegroundColor Yellow\n        Test-SourceFile \"$SourceFile\"\n\n        Write-Host \"Creating JSON data to pass to the service...\" -ForegroundColor Yellow\n\n        # Extract the detection.xml file from the .intunewin file\n        $DetectionXML = Get-IntuneWinXML \"$SourceFile\" -fileName \"detection.xml\" -removeitem $true\n\n        # If displayName input don't use Name from detection.xml file\n        if ($displayName) { $DisplayName = $displayName }\n        else { $DisplayName = $DetectionXML.ApplicationInfo.Name }\n         \n        $FileName = $DetectionXML.ApplicationInfo.FileName\n \n        $SetupFileName = $DetectionXML.ApplicationInfo.SetupFile\n \n        # Check if the file is an MSI or EXE\n        $Ext = [System.IO.Path]::GetExtension($SetupFileName)\n\n        if ((($Ext).contains(\"msi\") -or ($Ext).contains(\"Msi\")) -and (!$installCommandLine -or !$uninstallCommandLine)) {\n            # MSI\n            $MsiExecutionContext = $DetectionXML.ApplicationInfo.MsiInfo.MsiExecutionContext\n            $MsiPackageType = \"DualPurpose\"\n\n            if ($MsiExecutionContext -eq \"System\") { $MsiPackageType = \"PerMachine\" }\n            elseif ($MsiExecutionContext -eq \"User\") { $MsiPackageType = \"PerUser\" }\n \n            $MsiProductCode = $DetectionXML.ApplicationInfo.MsiInfo.MsiProductCode\n            $MsiProductVersion = $DetectionXML.ApplicationInfo.MsiInfo.MsiProductVersion\n            $MsiPublisher = $DetectionXML.ApplicationInfo.MsiInfo.MsiPublisher\n            $MsiRequiresReboot = $DetectionXML.ApplicationInfo.MsiInfo.MsiRequiresReboot\n            $MsiUpgradeCode = $DetectionXML.ApplicationInfo.MsiInfo.MsiUpgradeCode\n            \n            if ($MsiRequiresReboot -eq \"false\") { $MsiRequiresReboot = $false }\n            elseif ($MsiRequiresReboot -eq \"true\") { $MsiRequiresReboot = $true }\n \n            $mobileAppBody = GetWin32AppBody `\n                -MSI `\n                -displayName \"$DisplayName\" `\n                -publisher \"$publisher\" `\n                -description $description `\n                -filename $FileName `\n                -SetupFileName \"$SetupFileName\" `\n                -RunAsAccount \"$RunAsAccount\" `\n                -MsiPackageType $MsiPackageType `\n                -MsiProductCode $MsiProductCode `\n                -MsiProductName $displayName `\n                -MsiProductVersion $MsiProductVersion `\n                -MsiPublisher $MsiPublisher `\n                -MsiRequiresReboot $MsiRequiresReboot `\n                -MsiUpgradeCode $MsiUpgradeCode `\n                -DeviceRestartBehavior \"$DeviceRestartBehavior\"\n        }\n        else {\n            $mobileAppBody = GetWin32AppBody `\n                -EXE -displayName \"$DisplayName\" `\n                -publisher \"$publisher\" `\n                -description $description `\n                -filename $FileName `\n                -SetupFileName \"$SetupFileName\" `\n                -RunAsAccount $RunAsAccount `\n                -DeviceRestartBehavior \"$DeviceRestartBehavior\" `\n                -installCommandLine $installCommandLine `\n                -uninstallCommandLine $uninstallCommandLine\n        }\n\n        # Add the rules and return codes to the JSON body\n        if ($Rules) {\n            $mobileAppBody.Add(\"rules\", @($Rules))\n        }\n \n        if ($returnCodes) {\n            $mobileAppBody.Add(\"returnCodes\", @($returnCodes))\n        }\n        else {\n            Write-Warning \"Intunewin file requires ReturnCodes to be specified\"\n            Write-Warning \"If you want to use the default ReturnCode run 'Get-DefaultReturnCodes'\"\n            break\n        }\n\n        # Add the app icon (largeIcon) if an icon file was provided\n        if ($IconFile) {\n            Write-Host \"Adding app icon from '$IconFile'...\" -ForegroundColor Yellow\n            $mobileAppBody.Add(\"largeIcon\", (New-IntuneAppIcon -IconFile $IconFile))\n        }\n\n        # Create the application in Intune and get the application ID\n        Write-Host \"Creating application in Intune...\" -ForegroundColor Yellow\n        $MobileApp = New-MgDeviceAppManagementMobileApp -BodyParameter ($mobileAppBody | ConvertTo-Json)\n        $mobileAppId = $MobileApp.id\n\n        # Create a new content version for the application\n        Write-Host \"Creating Content Version in the service for the application...\" -ForegroundColor Yellow\n        $ContentVersion = New-MgDeviceAppManagementMobileAppAsWin32LobAppContentVersion -MobileAppId $mobileAppId -BodyParameter @{}\n\n        # Extract the encryption information from the .intunewin file\n        Write-Host \"Retrieving encryption information from .intunewin file.\" -ForegroundColor Yellow\n        $encryptionInfo = @{}\n        $encryptionInfo.encryptionKey = $DetectionXML.ApplicationInfo.EncryptionInfo.EncryptionKey\n        $encryptionInfo.macKey = $DetectionXML.ApplicationInfo.EncryptionInfo.macKey\n        $encryptionInfo.initializationVector = $DetectionXML.ApplicationInfo.EncryptionInfo.initializationVector\n        $encryptionInfo.mac = $DetectionXML.ApplicationInfo.EncryptionInfo.mac\n        $encryptionInfo.profileIdentifier = \"ProfileVersion1\"\n        $encryptionInfo.fileDigest = $DetectionXML.ApplicationInfo.EncryptionInfo.fileDigest\n        $encryptionInfo.fileDigestAlgorithm = $DetectionXML.ApplicationInfo.EncryptionInfo.fileDigestAlgorithm\n\n        $fileEncryptionInfo = @{}\n        $fileEncryptionInfo.fileEncryptionInfo = $encryptionInfo\n\n        # Extracting encrypted file\n        $IntuneWinFile = Get-IntuneWinFile \"$SourceFile\" -fileName \"$FileName\"\n        [int64]$Size = $DetectionXML.ApplicationInfo.UnencryptedContentSize\n        $EncrySize = (Get-Item \"$IntuneWinFile\").Length\n\n        # Create a new file entry in Azure for the upload\n        $ContentVersionId = $ContentVersion.Id\n        $fileBody = GetAppFileBody \"$FileName\" $Size $EncrySize $null\n        $fileBody = $fileBody | ConvertTo-Json \n\n        # Create a new file entry in Azure for the upload and get the file ID\n        Write-Host \"Creating a new file entry in Azure for the upload...\" -ForegroundColor Yellow\n        $ContentVersionFile = New-MgDeviceAppManagementMobileAppAsWin32LobAppContentVersionFile -MobileAppId $mobileAppId -MobileAppContentId $ContentVersionId -BodyParameter $fileBody\n        $ContentVersionFileId = $ContentVersionFile.id\n        \n        # Get the file URI for the upload\n        $fileUri = \"https://graph.microsoft.com/beta/deviceAppManagement/mobileApps/$mobileAppId/microsoft.graph.win32LobApp/contentVersions/$contentVersionId/files/$contentVersionFileId\"\n\n        # Upload the file to Azure Storage\n        Write-Host \"Uploading the file to Azure Storage...\" -ForegroundColor Yellow\n        $file = WaitForFileProcessing $fileUri \"AzureStorageUriRequest\"\n        [UInt32]$BlockSizeMB = 1\n        UploadFileToAzureStorage $file.azureStorageUri $IntuneWinFile $BlockSizeMB\n\n        # Commit the file to the service\n        $params = $fileEncryptionInfo | ConvertTo-Json\n        Write-Host \"Committing the file to the service...\" -ForegroundColor Yellow\n        #Wait 5 seconds before committing the file\n        Start-Sleep -Seconds 5\n\n        # Commit the file to the service\n        Invoke-MgCommitDeviceAppManagementMobileAppMicrosoftGraphWin32LobAppContentVersionFile -MobileAppId $mobileAppId -MobileAppContentId $ContentVersionId -MobileAppContentFileId $ContentVersionFileId -BodyParameter $params\n\n        # Wait for the file to be processed\n        Write-Host \"Waiting for the file to be processed...\" -ForegroundColor Yellow\n        $file = WaitForFileProcessing $fileUri \"CommitFile\"\n\n        $params = @{\n            \"@odata.type\"           = \"#microsoft.graph.win32LobApp\"\n            committedContentVersion = \"1\"\n        }\n\n        $params = $params | ConvertTo-Json\n\n        # Update the application with the new content version\n        Write-Host \"Updating the application with the new content version...\" -ForegroundColor Yellow\n        Update-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId -BodyParameter $params\n\n        # Return the application ID\n        Write-Host \"Application created successfully.\" -ForegroundColor Green\n        Write-Host \"Application Details:\"\n        Get-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId | Format-List\n    }\n    catch {\n        Write-Host -ForegroundColor Red \"Aborting with exception: $($_.Exception.ToString())\"\n       \n        # In the event that the creation of the app record in Intune succeeded, but processing/file upload failed, you can remove the comment block around the code below to delete the app record.\n        # This will allow you to re-run the script without having to manually delete the incomplete app record.\n        # Note: This will only work if the app record was successfully created in Intune.\n\n        <#\n        if ($mobileAppId) {\n            Write-Host \"Removing the incomplete application record from Intune...\" -ForegroundColor Yellow\n            Remove-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId\n        }\n        #>\n        break\n    }\n}\n\n<#\n.SYNOPSIS\nCreates a new file system rule.\n\n.DESCRIPTION\nThis function creates a new file system rule that you can use to specify a detection or requirement for a Win32 app.\n\n.PARAMETER ruleType\nThe type of rule. Valid values are 'detection' or 'requirement'.\n\n.PARAMETER path\nThe path to the file or folder.\n\n.PARAMETER fileOrFolderName\nThe name of the file or folder.\n\n.PARAMETER check32BitOn64System\nSpecifies whether to check for 32-bit on a 64-bit system.\n\n.PARAMETER operationType\nThe value type returned by the script. Valid values are 'notConfigured', 'exists', 'modifiedDate', 'createdDate', 'version', 'sizeInMB', 'doesNotExist', 'sizeInBytes', 'appVersion'.\n\n.PARAMETER operator\nThe operator for the detection script output comparison. Valid values are 'notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual'.\n\n.PARAMETER comparisonValue\nThe value to compare the script output to.\n\n.EXAMPLE\n# Creates a new file system rule for a Win32 app.\nNew-FileSystemRule -ruleType detection -path 'C:\\Program Files\\Microsoft VS Code' -fileOrFolderName 'code.exe' -check32BitOn64System $false -operationType exists -operator notConfigured -comparisonValue $null\n#>\nfunction New-FileSystemRule() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateSet(\"detection\", \"requirement\")]\n        [string]$ruleType,\n    \n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$path,\n    \n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$fileOrFolderName,\n    \n        [parameter(Mandatory = $true)]\n        [bool]$check32BitOn64System,\n    \n        [parameter(Mandatory = $false)]\n        [ValidateSet(\"notConfigured\", \"exists\", \"modifiedDate\", \"createdDate\", \"version\", \"sizeInMB\", \"doesNotExist\", \"sizeInBytes\", \"appVersion\")]\n        [string]$operationType,\n\n        [parameter(Mandatory = $false)]\n        [ValidateSet(\"notConfigured\", \"equal\", \"notEqual\", \"greaterThan\", \"greaterThanOrEqual\", \"lessThan\", \"lessThanOrEqual\")]\n        [string]$operator = \"notConfigured\",\n\n        [parameter(Mandatory = $false)]\n        $comparisonValue\n    )\n\n    $Rule = @{}\n\n    if ($null -ne $comparisonValue -and $comparisonValue -ne \"\") {\n        $Rule.comparisonValue = $comparisonValue\n    }\n    else {\n        $Rule.comparisonValue = $null\n    }\n\n    $Rule.\"@odata.type\" = \"#microsoft.graph.win32LobAppFileSystemRule\" \n    $Rule.ruleType = $ruleType\n    $Rule.path = $path\n    $Rule.fileOrFolderName = $fileOrFolderName\n    $Rule.check32BitOn64System = $check32BitOn64System\n    $Rule.operationType = $operationType\n    $Rule.operator = $operator\n\n    return $Rule\n}\n\n<#\n.SYNOPSIS\nCreates a new product code rule.\n\n.DESCRIPTION\nThis function creates a new product code rule that you can use to specify a detection or requirement for a Win32 app.\n\n.PARAMETER ruleType\nThe type of rule. Valid values are 'detection' or 'requirement'.\n\n.PARAMETER productCode\nThe product code.\n\n.PARAMETER productVersionOperator\nThe operator for the detection script output comparison. Valid values are 'notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual'.\n\n.PARAMETER productVersion\nThe value to compare the script output to.\n\n.EXAMPLE\n# Creates a new product code rule for a Win32 app.\nNew-ProductCodeRule -ruleType detection -productCode \"{3248F0A8-6813-4B6F-8C3A-4B6C4F512345}\" -productVersionOperator equal -productVersion \"130.0\"\n#>\nfunction New-ProductCodeRule {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateSet('detection', 'requirement')]\n        [string]$ruleType,\n\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$productCode,\n\n        [parameter(Mandatory = $true)]\n        [ValidateSet('notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual')]\n        [string]$productVersionOperator,\n\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$productVersion\n    )\n\n    $Rule = @{}\n    $Rule.\"@odata.type\" = \"#microsoft.graph.win32LobAppProductCodeRule\"\n    $Rule.ruleType = $ruleType\n    $Rule.productCode = $productCode\n    $Rule.productVersionOperator = $productVersionOperator\n    $Rule.productVersion = $productVersion\n\n    return $Rule\n}\n\n<#\n.SYNOPSIS\nCreates a new registry rule.\n\n.DESCRIPTION\nThis function creates a new registry rule that you can use to specify a detection or requirement for a Win32 app.\n\n.PARAMETER ruleType\nThe type of rule. Valid values are 'detection' or 'requirement'.\n\n.PARAMETER keyPath\nThe registry key path.\n\n.PARAMETER valueName\nThe registry value name.\n\n.PARAMETER operationType\nThe operation data type (data type returned by the script). Valid values are 'notConfigured', 'exists', 'doesNotExist', 'string', 'integer', 'float', 'version'.\n\n.PARAMETER operator\nThe operator for the detection script output comparison. Valid values are 'notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual'.\n\n.PARAMETER comparisonValue\nThe value to compare the script output to.\n\n.EXAMPLE\n# Creates a new registry rule for a Win32 app.\nNew-RegistryRule -ruleType detection -keyPath \"HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\xyz\" -valueName \"DisplayName\" -operationType string -operator equal -comparisonValue \"VSCode\"\n#>\nfunction New-RegistryRule {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateSet('detection', 'requirement')]\n        [string]$ruleType,\n\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$keyPath,\n\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$valueName,\n\n        [parameter(Mandatory = $true)]\n        [ValidateSet('notConfigured', 'exists', 'doesNotExist', 'string', 'integer', 'float', 'version')]\n        [string]$operationType,\n\n        [parameter(Mandatory = $true)]\n        [ValidateSet('notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual')]\n        [string]$operator,\n\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$comparisonValue\n    )\n\n    $Rule = @{}\n    $Rule.\"@odata.type\" = \"#microsoft.graph.win32LobAppRegistryRule\"\n    $Rule.ruleType = $ruleType\n    $Rule.keyPath = $keyPath\n    $Rule.valueName = $valueName\n    $Rule.operationType = $operationType\n    $Rule.operator = $operator\n    $Rule.comparisonValue = $comparisonValue\n\n    return $Rule\n}\n\n<#\n.SYNOPSIS\nCreates a new script detection rule.\n\n.DESCRIPTION\nThis function creates a new script detection rule that you can use to specify a detection for a Win32 app.\n\n.PARAMETER ScriptFile\nThe path to the script file.\n\n.PARAMETER EnforceSignatureCheck\nSpecifies whether to enforce signature check.\n\n.PARAMETER RunAs32Bit\nSpecifies whether to run the script as 32-bit.\n\n.EXAMPLE\n# Creates a new script detection rule for a Win32 app.\nNew-ScriptDetectionRule -ScriptFile \"E:\\VSCodeDetection.ps1\" -EnforceSignatureCheck $false -RunAs32Bit $false\n\n.NOTES\nThis function only creates a script detection rule. To create a script requirement rule, use the New-ScriptRequirementRule function.\n#>\nfunction New-ScriptDetectionRule() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$ScriptFile,\n\n        [parameter(Mandatory = $true)]\n        [bool]$EnforceSignatureCheck,\n\n        [parameter(Mandatory = $true)]\n        [bool]$RunAs32Bit\n\n    )\n    if (!(Test-Path \"$ScriptFile\")) {\n        Write-Host \"Could not find file '$ScriptFile'...\" -ForegroundColor Red\n        Write-Host \"Script can't continue...\" -ForegroundColor Red\n        break\n    }\n        \n    $ScriptContent = [System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes(\"$ScriptFile\"))\n        \n    $Rule = @{}\n    $Rule.\"@odata.type\" = \"#microsoft.graph.win32LobAppPowerShellScriptRule\"\n    $Rule.ruleType = \"detection\"\n    $Rule.enforceSignatureCheck = $EnforceSignatureCheck\n    $Rule.runAs32Bit = $RunAs32Bit\n    $Rule.scriptContent = \"$ScriptContent\"\n    $Rule.operationType = \"notConfigured\"\n    $Rule.operator = \"notConfigured\"\n\n    return $Rule\n}\n\n<#\n.SYNOPSIS\nCreates a new script requirement rule.\n\n.DESCRIPTION\nThis function creates a new script requirement rule that you can use to specify a requirement for a Win32 app.\n\n.PARAMETER ScriptFile\nThe path to the script file.\n\n.PARAMETER DisplayName\nThe display name of the rule.\n\n.PARAMETER EnforceSignatureCheck\nSpecifies whether to enforce signature check.\n\n.PARAMETER RunAs32Bit\nSpecifies whether to run the script as 32-bit.\n\n.PARAMETER RunAsAccount\nThe account to run the script as. Valid values are 'system' or 'user'.\n\n.PARAMETER OperationType\nThe operation data type (data type returned by the script). Valid values are 'notConfigured', 'string', 'dateTime', 'integer', 'float', 'version', 'boolean'.\n\n.PARAMETER Operator\nThe operator for the detection script output comparison. Valid values are 'notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual'.\n\n.PARAMETER ComparisonValue\nThe value to compare the script output to.\n\n.EXAMPLE\n# Creates a new script requirement rule for a Win32 app.\nNew-ScriptRequirementRule -ScriptFile \"E:\\VSCodeRequirement.ps1\" -DisplayName \"VS Code Requirement\" -EnforceSignatureCheck $false -RunAs32Bit $false -RunAsAccount \"system\" -OperationType \"integer\" -Operator \"equal\" -ComparisonValue \"0\"\n\n.NOTES\nThis function only creates a script requirement rule. To create a script detection rule, use the New-ScriptDetectionRule function.\n#>\nfunction New-ScriptRequirementRule {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$ScriptFile,\n\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$DisplayName,\n\n        [parameter(Mandatory = $true)]\n        [bool]$EnforceSignatureCheck,\n\n        [parameter(Mandatory = $true)]\n        [bool]$RunAs32Bit,\n\n        #Valid values are 'system' or 'user'\n        [parameter(Mandatory = $true)]\n        [ValidateSet('system', 'user')]\n        [string]$RunAsAccount,\n\n        [parameter(Mandatory = $true)]\n        [ValidateSet('notConfigured', 'string', 'dateTime', 'integer', 'float', 'version', 'boolean')]\n        [string]$OperationType,\n\n        [parameter(Mandatory = $true)]\n        [ValidateSet('notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual')]\n        [string]$Operator,\n\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$ComparisonValue\n    )\n\n    if (!(Test-Path \"$ScriptFile\")) {\n        Write-Host \"Could not find file '$ScriptFile'...\" -ForegroundColor Red\n        Write-Host \"Script can't continue...\" -ForegroundColor Red\n        break\n    }\n\n    $ScriptContent = [System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes(\"$ScriptFile\"))\n        \n    $Rule = @{}\n    $Rule.\"@odata.type\" = \"#microsoft.graph.win32LobAppPowerShellScriptRule\"\n    $Rule.displayName = $DisplayName\n    $Rule.ruleType = \"requirement\"\n    $Rule.enforceSignatureCheck = $EnforceSignatureCheck\n    $Rule.runAs32Bit = $RunAs32Bit\n    $Rule.scriptContent = \"$ScriptContent\"\n    $Rule.operationType = $OperationType\n    $Rule.operator = $Operator\n    $Rule.comparisonValue = $ComparisonValue\n    $Rule.runAsAccount = $RunAsAccount\n\n    return $Rule\n}\n\n<#\n.SYNOPSIS\nCreates a new return code object.\n\n.DESCRIPTION\nThis function creates a new return code object that you can use to specify the return codes for a Win32 app.\n\n.PARAMETER returnCode\nThe return code value.\n\n.PARAMETER type\nThe type of return code. Valid values are 'success', 'softReboot', 'hardReboot\n\n.EXAMPLE\n# Creates a new return code object with a return code of 0 and a type of 'success'\nNew-ReturnCode -returnCode 0 -type 'success'\n#>\nfunction New-ReturnCode() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [int]$returnCode,\n        [parameter(Mandatory = $true)]\n        [ValidateSet('success', 'softReboot', 'hardReboot', 'retry')]\n        $type\n    )\n\n    @{\"returnCode\" = $returnCode; \"type\" = \"$type\" }\n}\n\n<#\n.SYNOPSIS\nConverts an image file to a mimeContent object for use as a Win32 app icon.\n\n.DESCRIPTION\nThis function reads an image file from disk, base64-encodes its content, and returns a mimeContent hashtable that can be assigned to a mobileApp's largeIcon property. Supported image types are .png, .jpg, .jpeg, and .gif.\n\n.PARAMETER IconFile\nThe path to the image file to use as the app icon.\n\n.EXAMPLE\n# Creates a mimeContent icon object from a .png file.\nNew-IntuneAppIcon -IconFile \"C:\\IntuneApps\\vscode\\icon.png\"\n#>\nfunction New-IntuneAppIcon() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$IconFile\n    )\n\n    # Check the icon file exists\n    if (!(Test-Path \"$IconFile\")) {\n        Write-Host \"Icon file '$IconFile' doesn't exist...\" -ForegroundColor Red\n        throw \"Icon file not found: $IconFile\"\n    }\n\n    # Determine the MIME type from the file extension\n    $Extension = [System.IO.Path]::GetExtension(\"$IconFile\").ToLower()\n    switch ($Extension) {\n        \".png\" { $MimeType = \"image/png\" }\n        \".jpg\" { $MimeType = \"image/jpeg\" }\n        \".jpeg\" { $MimeType = \"image/jpeg\" }\n        \".gif\" { $MimeType = \"image/gif\" }\n        default {\n            Write-Host \"Unsupported icon file type '$Extension'. Supported types are .png, .jpg, .jpeg, and .gif.\" -ForegroundColor Red\n            throw \"Unsupported icon file type: $Extension\"\n        }\n    }\n\n    # Read the image file and base64-encode its content\n    $IconContent = [System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes(\"$IconFile\"))\n\n    # Construct and return the mimeContent object (used as the app's largeIcon)\n    $Icon = @{\n        \"@odata.type\" = \"#microsoft.graph.mimeContent\"\n        \"type\"        = $MimeType\n        \"value\"       = $IconContent\n    }\n\n    return $Icon\n}\n\n####################################################\n# Function to wait for file processing to complete by polling the file upload state\nfunction WaitForFileProcessing($fileUri, $stage) {\n    $attempts = 60\n    $waitTimeInSeconds = 1\n    $successState = \"$($stage)Success\"\n    $pendingState = \"$($stage)Pending\"\n\n    $file = $null\n    while ($attempts -gt 0) {\n        $file = Invoke-MgGraphRequest -Method GET -Uri $fileUri\n        if ($file.uploadState -eq $successState) {\n            break\n        }\n        elseif ($file.uploadState -ne $pendingState) {\n            throw \"File upload state is not success: $($file.uploadState)\"\n        }\n\n        Start-Sleep $waitTimeInSeconds\n        $attempts--\n    }\n\n    if ($null -eq $file) {\n        throw \"File request did not complete in the allotted time.\"\n    }\n\n    $file\n}\n\n####################################################\n# Function to upload a file to Azure Storage using the SAS URI\nfunction UploadFileToAzureStorage($sasUri, $filepath, $blockSizeMB) {\n    # Chunk size in MiB\n    $chunkSizeInBytes = (1024 * 1024 * $blockSizeMB)  \n\n    # Read the whole file and find the total chunks.\n    #[byte[]]$bytes = Get-Content $filepath -Encoding byte;\n    # Using ReadAllBytes method as the Get-Content used alot of memory on the machine\n    $fileStream = [System.IO.File]::OpenRead($filepath)\n    $chunks = [Math]::Ceiling($fileStream.Length / $chunkSizeInBytes)\n\n    # Upload each chunk.\n    $ids = @()\n    $cc = 1\n    $chunk = 0\n    while ($fileStream.Position -lt $fileStream.Length) {\n        $id = [System.Convert]::ToBase64String([System.Text.Encoding]::ASCII.GetBytes($chunk.ToString(\"0000\")))\n        $ids += $id\n\n        $size = [Math]::Min($chunkSizeInBytes, $fileStream.Length - $fileStream.Position)\n        $body = New-Object byte[] $size\n        $fileStream.Read($body, 0, $size) > $null\n        $totalBytes += $size\n\n        Write-Progress -Activity \"Uploading File to Azure Storage\" -Status \"Uploading chunk $cc of $chunks\" -PercentComplete ($cc / $chunks * 100)\n        $cc++\n\n        UploadAzureStorageChunk $sasUri $id $body | Out-Null\n        $chunk++\n    }\n\n    $fileStream.Close()\n    Write-Progress -Completed -Activity \"Uploading File to Azure Storage\"\n\n    # Finalize the upload.\n    FinalizeAzureStorageUpload $sasUri $ids | Out-Null\n}\n\n####################################################\n# Function to upload a chunk to Azure Storage\nfunction UploadAzureStorageChunk($sasUri, $id, $body) {\n    $uri = \"$sasUri&comp=block&blockid=$id\"\n    $request = \"PUT $uri\"\n\n    $headers = @{\n        \"x-ms-blob-type\" = \"BlockBlob\"\n        \"Content-Type\"   = \"application/octet-stream\"\n    }\n\n    try {\n        Invoke-WebRequest -Headers $headers $uri -Method Put -Body $body | Out-Null\n    }\n    catch {\n        Write-Host -ForegroundColor Red $request\n        Write-Host -ForegroundColor Red $_.Exception.Message\n        throw\n    }\n}\n\n####################################################\n# Function to finalize the Azure Storage upload\nfunction FinalizeAzureStorageUpload($sasUri, $ids) {\n    $uri = \"$sasUri&comp=blocklist\"\n    $request = \"PUT $uri\"\n\n    $xml = '<?xml version=\"1.0\" encoding=\"utf-8\"?><BlockList>'\n    foreach ($id in $ids) {\n        $xml += \"<Latest>$id</Latest>\"\n    }\n    $xml += '</BlockList>'\n\n    if ($logRequestUris) { Write-Host $request; }\n    if ($logContent) { Write-Host -ForegroundColor Gray $xml; }\n\n    $headers = @{\n        \"Content-Type\" = \"text/plain\"\n    }\n\n    try {\n        Invoke-WebRequest $uri -Method Put -Body $xml -Headers $headers\n    }\n    catch {\n        Write-Host -ForegroundColor Red $request\n        Write-Host -ForegroundColor Red $_.Exception.Message\n        throw\n    }\n}\n\n####################################################\n# Function to construct the JSON body for a Win32 app\nfunction GetWin32AppBody() {\n    param\n    (\n        [parameter(Mandatory = $true, ParameterSetName = \"MSI\", Position = 1)]\n        [Switch]$MSI,\n    \n        [parameter(Mandatory = $true, ParameterSetName = \"EXE\", Position = 1)]\n        [Switch]$EXE,\n    \n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$displayName,\n    \n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$publisher,\n    \n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$description,\n    \n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$filename,\n    \n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [string]$SetupFileName,\n    \n        [parameter(Mandatory = $true)]\n        [ValidateSet('system', 'user')]\n        [string]$RunAsAccount,\n\n        [parameter(Mandatory = $true)]\n        [ValidateSet('basedOnReturnCode', 'allow', 'suppress', 'force')]\n        [string]$DeviceRestartBehavior,\n    \n        [parameter(Mandatory = $true, ParameterSetName = \"EXE\")]\n        [ValidateNotNullOrEmpty()]\n        $installCommandLine,\n    \n        [parameter(Mandatory = $true, ParameterSetName = \"EXE\")]\n        [ValidateNotNullOrEmpty()]\n        $uninstallCommandLine,\n    \n        [parameter(Mandatory = $true, ParameterSetName = \"MSI\")]\n        [ValidateNotNullOrEmpty()]\n        $MsiPackageType,\n    \n        [parameter(Mandatory = $true, ParameterSetName = \"MSI\")]\n        [ValidateNotNullOrEmpty()]\n        $MsiProductCode,\n    \n        [parameter(Mandatory = $false, ParameterSetName = \"MSI\")]\n        $MsiProductName,\n    \n        [parameter(Mandatory = $true, ParameterSetName = \"MSI\")]\n        [ValidateNotNullOrEmpty()]\n        $MsiProductVersion,\n    \n        [parameter(Mandatory = $false, ParameterSetName = \"MSI\")]\n        $MsiPublisher,\n    \n        [parameter(Mandatory = $true, ParameterSetName = \"MSI\")]\n        [ValidateNotNullOrEmpty()]\n        $MsiRequiresReboot,\n    \n        [parameter(Mandatory = $true, ParameterSetName = \"MSI\")]\n        [ValidateNotNullOrEmpty()]\n        $MsiUpgradeCode\n    )\n    \n    if ($MSI) {\n        $body = @{ \"@odata.type\" = \"#microsoft.graph.win32LobApp\" }\n        $body.applicableArchitectures = \"x64,x86\"\n        $body.description = $description\n        $body.developer = \"\"\n        $body.displayName = $displayName\n        $body.fileName = $filename\n        $body.installCommandLine = \"msiexec /i `\"$SetupFileName`\"\"\n        $body.installExperience = @{\n            \"runAsAccount\"          = \"$RunAsAccount\"\n            \"deviceRestartBehavior\" = $DeviceRestartBehavior \n        }\n        $body.informationUrl = $null\n        $body.isFeatured = $false\n        $body.minimumSupportedOperatingSystem = @{\"v10_1607\" = $true }\n        $body.msiInformation = @{\n            \"packageType\"    = \"$MsiPackageType\"\n            \"productCode\"    = \"$MsiProductCode\"\n            \"productName\"    = \"$MsiProductName\"\n            \"productVersion\" = \"$MsiProductVersion\"\n            \"publisher\"      = \"$MsiPublisher\"\n            \"requiresReboot\" = \"$MsiRequiresReboot\"\n            \"upgradeCode\"    = \"$MsiUpgradeCode\"\n            \"@odata.type\"    = \"#microsoft.graph.win32LobAppMsiInformation\"\n        }\n        $body.notes = \"\"\n        $body.owner = \"\"\n        $body.privacyInformationUrl = $null\n        $body.publisher = $publisher\n        $body.runAs32bit = $false\n        $body.setupFilePath = $SetupFileName\n        $body.uninstallCommandLine = \"msiexec /x `\"$MsiProductCode`\"\"\n    }\n    elseif ($EXE) {\n        $body = @{ \"@odata.type\" = \"#microsoft.graph.win32LobApp\" }\n        $body.description = $description\n        $body.developer = \"\"\n        $body.displayName = $displayName\n        $body.fileName = $filename\n        $body.installCommandLine = $installCommandLine\n        $body.installExperience = @{\n            \"runAsAccount\"          = $RunAsAccount\n            \"deviceRestartBehavior\" = $DeviceRestartBehavior \n        }\n        $body.informationUrl = $null\n        $body.isFeatured = $false\n        $body.minimumSupportedOperatingSystem = @{\"v10_1607\" = $true }\n        $body.msiInformation = $null\n        $body.notes = \"\"\n        $body.owner = \"\"\n        $body.privacyInformationUrl = $null\n        $body.publisher = $publisher\n        $body.runAs32bit = $false\n        $body.setupFilePath = $SetupFileName\n        $body.uninstallCommandLine = $uninstallCommandLine\n    }\n\n    $body\n}\n\n####################################################\n# Function to test if the source file exists\nFunction Test-SourceFile() {\n    param\n    (\n        [parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        $SourceFile\n    )\n    try {\n    \n        if (!(test-path \"$SourceFile\")) {\n            Write-Host\n            Write-Host \"Source File '$sourceFile' doesn't exist...\" -ForegroundColor Red\n            throw\n        }\n    }\n    \n    catch {\n        Write-Host -ForegroundColor Red $_.Exception.Message\n        Write-Host\n        break\n    }\n}\n\n####################################################\n# Function to get the default return codes    \nfunction Get-DefaultReturnCodes() {\n    @{\"returnCode\" = 0; \"type\" = \"success\" }, `\n    @{\"returnCode\" = 1707; \"type\" = \"success\" }, `\n    @{\"returnCode\" = 3010; \"type\" = \"softReboot\" }, `\n    @{\"returnCode\" = 1641; \"type\" = \"hardReboot\" }, `\n    @{\"returnCode\" = 1618; \"type\" = \"retry\" }\n    \n}\n\n####################################################\n# Function to extract the IntuneWin XML file from the .intunewin file\nFunction Get-IntuneWinXML() {\n    param\n    (\n        [Parameter(Mandatory = $true)]\n        $SourceFile,\n    \n        [Parameter(Mandatory = $true)]\n        $fileName,\n    \n        [Parameter(Mandatory = $false)]\n        [bool]$removeitem = $true\n    )\n    \n    Test-SourceFile \"$SourceFile\"\n    \n    $Directory = [System.IO.Path]::GetDirectoryName(\"$SourceFile\")\n    \n    Add-Type -Assembly System.IO.Compression.FileSystem\n    $zip = [IO.Compression.ZipFile]::OpenRead(\"$SourceFile\")\n    \n    $zip.Entries | Where-Object { $_.Name -like \"$filename\" } | ForEach-Object {\n        [System.IO.Compression.ZipFileExtensions]::ExtractToFile($_, \"$Directory\\$filename\", $true)\n    }\n    \n    $zip.Dispose()\n    \n    [xml]$IntuneWinXML = Get-Content \"$Directory\\$filename\"\n    \n    return $IntuneWinXML\n    \n    if ($removeitem -eq $true) { remove-item \"$Directory\\$filename\" }\n}\n\n####################################################\n# Function to extract the IntuneWin file from the .intunewin file\nFunction Get-IntuneWinFile() {\n    param\n    (\n        [Parameter(Mandatory = $true)]\n        $SourceFile,\n    \n        [Parameter(Mandatory = $true)]\n        $fileName,\n    \n        [Parameter(Mandatory = $false)]\n        [string]$Folder = \"win32\"\n    )\n    \n    $Directory = [System.IO.Path]::GetDirectoryName(\"$SourceFile\")\n    \n    if (!(Test-Path \"$Directory\\$folder\")) {\n        New-Item -ItemType Directory -Path \"$Directory\" -Name \"$folder\" -Force\n    }\n    \n    Add-Type -Assembly System.IO.Compression.FileSystem\n    $zip = [IO.Compression.ZipFile]::OpenRead((\"$SourceFile\"))\n    $zip.Entries | Where-Object { $_.Name -like \"$filename\" } | ForEach-Object {\n        [System.IO.Compression.ZipFileExtensions]::ExtractToFile($_, \"$Directory\\$folder\\$filename\", $true)\n    }\n    \n    $zip.Dispose()\n    \n    return \"$Directory\\$folder\\$filename\"\n    \n    if ($removeitem -eq $true) { remove-item \"$Directory\\$filename\" }\n}\n\n####################################################\n# Function to create a new app file body containing the file and encryption information\nfunction GetAppFileBody($name, $size, $sizeEncrypted, $manifest) {\n    $body = @{ \"@odata.type\" = \"#microsoft.graph.mobileAppContentFile\" }\n    $body.name = $name\n    $body.size = $size\n    $body.sizeEncrypted = $sizeEncrypted\n    $body.manifest = $manifest\n    $body.isDependency = $false\n        \n    $body\n}\n","teaching":["Add Win32 app and upload content","Win32 deployment separates installer packaging, metadata, content version, content upload and commit, requirements, detection and assignments. Each stage has distinct failure evidence.","Read only. Do not execute an installer or upload files. Verify supported API and permissions before authorized deployment.","Trace a fictional .intunewin package through metadata, content commit, assignment and installed-state detection.",null,"Which rule verifies that the intended app is installed?","detection rule"],"kind":"write-reference-only"},{"repository":"microsoft/mggraph-intune-samples","path":"LOB_Application/Win32_Application_Update.ps1","sha":"62833a86776b8e72314ce80a95eb9f5f0b1c3b81","lesson":13,"topic":"Update Win32 app content","url":"https://github.com/microsoft/mggraph-intune-samples/blob/main/LOB_Application/Win32_Application_Update.ps1","markdown":"<#\r\n.COPYRIGHT\r\nCopyright (c) Microsoft Corporation. All rights reserved. Licensed under the MIT license.\r\nSee LICENSE in the project root for license information.\r\n#>\r\n\r\n#requires -module Microsoft.Graph.Devices.CorporateManagement\r\n#requires -module Microsoft.Graph.Authentication\r\n\r\n<# region Authentication\r\nTo authenticate, you'll use the Microsoft Graph PowerShell SDK. If you haven't already installed the SDK, see this guide:\r\nhttps://learn.microsoft.com/en-us/powershell/microsoftgraph/installation?view=graph-powershell-1.0\r\nThe PowerShell SDK supports two types of authentication: delegated access, and app-only access.\r\nFor details on using delegated access, see this guide here:\r\nhttps://learn.microsoft.com/powershell/microsoftgraph/get-started?view=graph-powershell-1.0\r\nFor details on using app-only access for unattended scenarios, see Use app-only authentication with the Microsoft Graph PowerShell SDK:\r\nhttps://learn.microsoft.com/powershell/microsoftgraph/app-only?view=graph-powershell-1.0&tabs=azure-portal\r\n#>\r\n\r\n<#\r\n.SYNOPSIS\r\nUpdates a Win32 app in Intune.\r\n\r\n.DESCRIPTION\r\nThis function updates a Win32 app in Intune. The script extracts the detection.xml file from the .intunewin file and uses the information to update the app in Intune. The script then uploads the .intunewin file to Azure Storage and commits the file to the service.\r\n\r\n.PARAMETER AppId\r\nThe ID of the Intune win32 app to update.\r\n\r\n.PARAMETER UpdateAppContentOnly\r\nIf $true, only the app package content will be updated and other app properties (e.g. Name, detection rules, etc.) will not be updated.\r\n\r\n.PARAMETER SourceFile\r\nThe path to the .intunewin file.\r\n\r\n.PARAMETER displayName\r\nThe display name of the app. If not specified, the script uses the Name from the detection.xml file.\r\n\r\n.PARAMETER publisher\r\nThe publisher of the app.\r\n\r\n.PARAMETER description\r\nThe description of the app.\r\n\r\n.PARAMETER Rules\r\nAn array of rules to apply to the app. You can use the New-FileSystemRule, New-ProductCodeRule, New-RegistryRule, New-ScriptDetectionRule, and New-ScriptRequirementRule functions to create the rules.\r\n\r\n.PARAMETER returnCodes\r\nAn array of return codes to apply to the app. You can use the Get-DefaultReturnCodes and New-ReturnCode functions to create the return codes.\r\n\r\n.PARAMETER installCommandLine\r\nThe command line to install the app. Required for EXE files.\r\n\r\n.PARAMETER uninstallCommandLine\r\nThe command line to uninstall the app. Required for EXE files.\r\n\r\n.PARAMETER RunAsAccount\r\nThe account to run the app as. Valid values are 'system' or 'user'.\r\n\r\n.PARAMETER DeviceRestartBehavior\r\nThe device restart behavior for the app. Valid values are 'basedOnReturnCode', 'allow', 'suppress', 'force'.\r\n\r\n.PARAMETER IconFile\r\nThe path to an image file (.png, .jpg, .jpeg, or .gif) to use as the app icon. The image is converted to a mimeContent object and uploaded as the app's largeIcon. Optional, and applied whether or not -UpdateAppContentOnly is used.\r\n\r\n.EXAMPLE\r\n# Updates a .exe Win32 app in Intune (only the app package content).\r\nInvoke-Win32AppUpdate -AppId \"12345678-1234-1234-1234-123456789012\" -UpdateAppContentOnly -SourceFile \"C:\\IntuneApps\\vscode\\VSCodeSetup-x64-1.93.1.intunewin\"\r\n\r\n.EXAMPLE\r\n# Updates a .exe Win32 app in Intune (both app package + app properties) using the default return codes, a script detection rule, and a script requirement rule.\r\n$returnCodes = Get-DefaultReturnCodes\r\n$Rules = @()\r\n$Rules += New-ScriptRequirementRule -ScriptFile \"E:\\VSCodeRequirement.ps1\" -DisplayName \"VS Code Requirement1\" -EnforceSignatureCheck $false -RunAs32Bit $false -RunAsAccount \"system\" -OperationType \"integer\" -Operator \"equal\" -ComparisonValue \"0\"\r\n$Rules += New-ScriptDetectionRule -ScriptFile \"E:\\VSCodeDetection.ps1\" -EnforceSignatureCheck $false -RunAs32Bit $false\r\n\r\n\r\nInvoke-Win32AppUpdate -AppId \"12345678-1234-1234-1234-123456789012\" -UpdateAppContentOnly $false -displayName \"VS Code\" -SourceFile \"E:\\VSCodeSetup-x64-1.96.2.intunewin\" -publisher \"Microsoft\" -description \"Version 1.96.2\" -RunAsAccount \"system\" -Rules $Rules -returnCodes $returnCodes -InstallCommandLine \"VSCodeSetup-x64-1.96.2.exe /VERYSILENT /MERGETASKS=!runcode\" -UninstallCommandLine \"C:\\Program Files\\Microsoft VS Code\\unins000.exe /VERYSILENT\" -DeviceRestartBehavior \"basedOnReturnCode\"\r\n#>\r\nfunction Invoke-Win32AppUpdate {\r\n\t[cmdletbinding()]\r\n\tparam\r\n\t(\r\n\t\t[parameter(Mandatory = $true, Position = 1)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$AppId,\r\n\r\n\t\t[parameter(Mandatory = $true, Position = 2)]\r\n\t\t[bool]$UpdateAppContentOnly,\r\n\r\n\t\t[parameter(Mandatory = $true, Position = 3)]\r\n\t\t[string]$SourceFile,\r\n\r\n\t\t[parameter(Mandatory = $false, Position = 4)]\r\n\t\t[string]$displayName,\r\n\r\n\t\t[parameter(Mandatory = $false, Position = 5)]\r\n\t\t[string]$publisher,\r\n\r\n\t\t[parameter(Mandatory = $false, Position = 6)]\r\n\t\t[string]$description,\r\n\r\n\t\t[parameter(Mandatory = $false, Position = 7)]\r\n\t\t$Rules,\r\n\r\n\t\t[parameter(Mandatory = $false, Position = 8)]\r\n\t\t$returnCodes,\r\n\r\n\t\t[parameter(Mandatory = $false, Position = 9)]\r\n\t\t[string]$installCommandLine,\r\n\r\n\t\t[parameter(Mandatory = $false, Position = 10)]\r\n\t\t[string]$uninstallCommandLine,\r\n\r\n\t\t[parameter(Mandatory = $false, Position = 11)]\r\n\t\t[ValidateSet('system', 'user')]\r\n\t\t[string]$RunAsAccount,\r\n\r\n\t\t[parameter(Mandatory = $false, Position = 12)]\r\n\t\t[ValidateSet('basedOnReturnCode', 'allow', 'suppress', 'force')]\r\n\t\t[string]$DeviceRestartBehavior,\r\n\r\n\t\t[parameter(Mandatory = $false, Position = 13)]\r\n\t\t[string]$IconFile\r\n\t)\r\n\ttry\t{\r\n\t\t#Check if the app exists\r\n\t\t$MobileApp = Get-MgDeviceAppManagementMobileApp -MobileAppId $AppId\r\n\r\n\t\tif ($null -eq $MobileApp) {\r\n\t\t\tWrite-Host \"Application with ID '$AppId' does not exist in Intune.\" -ForegroundColor Red\r\n\t\t\tbreak\r\n\t\t}\r\n\r\n\t\tWrite-Host \"Application found...\" -ForegroundColor Yellow\r\n\t\t$mobileAppId = $MobileApp.id\r\n\r\n\t\t# Check if the source file exists\r\n\t\tWrite-Host \"Testing if SourceFile '$SourceFile' Path is valid...\" -ForegroundColor Yellow\r\n\t\tTest-SourceFile \"$SourceFile\"\r\n\r\n\t\tWrite-Host \"Creating JSON data to pass to the service...\" -ForegroundColor Yellow\r\n\r\n\t\t# Extract the detection.xml file from the .intunewin file\r\n\t\t$DetectionXML = Get-IntuneWinXML \"$SourceFile\" -fileName \"detection.xml\" -removeitem $true\r\n\r\n\t\t# If displayName input don't use Name from detection.xml file\r\n\t\tif ($displayName) { $DisplayName = $displayName }\r\n\t\telse { $DisplayName = $DetectionXML.ApplicationInfo.Name }\r\n\r\n\t\t$FileName = $DetectionXML.ApplicationInfo.FileName\r\n\r\n\t\t$SetupFileName = $DetectionXML.ApplicationInfo.SetupFile\r\n\r\n\t\t# Check if the file is an MSI or EXE\r\n\t\t$Ext = [System.IO.Path]::GetExtension($SetupFileName)\r\n\r\n\t\tif ($UpdateAppContentOnly) {\r\n\t\t\t$mobileAppBody = @{ \"#odata.type\" = \"#microsoft.graph.win32LobApp\" }\r\n\t\t}\r\n\t\telse {\r\n\r\n\t\t\tif ((($Ext).contains(\"msi\") -or ($Ext).contains(\"Msi\")) -and (!$installCommandLine -or !$uninstallCommandLine)) {\r\n\t\t\t\t# MSI\r\n\t\t\t\t$MsiExecutionContext = $DetectionXML.ApplicationInfo.MsiInfo.MsiExecutionContext\r\n\t\t\t\t$MsiPackageType = \"DualPurpose\"\r\n\r\n\t\t\t\tif ($MsiExecutionContext -eq \"System\") { $MsiPackageType = \"PerMachine\" }\r\n\t\t\t\telseif ($MsiExecutionContext -eq \"User\") { $MsiPackageType = \"PerUser\" }\r\n\r\n\t\t\t\t$MsiProductCode = $DetectionXML.ApplicationInfo.MsiInfo.MsiProductCode\r\n\t\t\t\t$MsiProductVersion = $DetectionXML.ApplicationInfo.MsiInfo.MsiProductVersion\r\n\t\t\t\t$MsiPublisher = $DetectionXML.ApplicationInfo.MsiInfo.MsiPublisher\r\n\t\t\t\t$MsiRequiresReboot = $DetectionXML.ApplicationInfo.MsiInfo.MsiRequiresReboot\r\n\t\t\t\t$MsiUpgradeCode = $DetectionXML.ApplicationInfo.MsiInfo.MsiUpgradeCode\r\n\r\n\t\t\t\tif ($MsiRequiresReboot -eq \"false\") { $MsiRequiresReboot = $false }\r\n\t\t\t\telseif ($MsiRequiresReboot -eq \"true\") { $MsiRequiresReboot = $true }\r\n\r\n\t\t\t\t$mobileAppBody = GetWin32AppBody `\r\n\t\t\t\t\t-MSI `\r\n\t\t\t\t\t-displayName \"$DisplayName\" `\r\n\t\t\t\t\t-publisher \"$publisher\" `\r\n\t\t\t\t\t-description $description `\r\n\t\t\t\t\t-filename $FileName `\r\n\t\t\t\t\t-SetupFileName \"$SetupFileName\" `\r\n\t\t\t\t\t-RunAsAccount \"$RunAsAccount\" `\r\n\t\t\t\t\t-MsiPackageType $MsiPackageType `\r\n\t\t\t\t\t-MsiProductCode $MsiProductCode `\r\n\t\t\t\t\t-MsiProductName $displayName `\r\n\t\t\t\t\t-MsiProductVersion $MsiProductVersion `\r\n\t\t\t\t\t-MsiPublisher $MsiPublisher `\r\n\t\t\t\t\t-MsiRequiresReboot $MsiRequiresReboot `\r\n\t\t\t\t\t-MsiUpgradeCode $MsiUpgradeCode `\r\n\t\t\t\t\t-DeviceRestartBehavior \"$DeviceRestartBehavior\"\r\n\t\t\t}\r\n\t\t\telse {\r\n\t\t\t\t$mobileAppBody = GetWin32AppBody `\r\n\t\t\t\t\t-EXE -displayName \"$DisplayName\" `\r\n\t\t\t\t\t-publisher \"$publisher\" `\r\n\t\t\t\t\t-description $description `\r\n\t\t\t\t\t-filename $FileName `\r\n\t\t\t\t\t-SetupFileName \"$SetupFileName\" `\r\n\t\t\t\t\t-RunAsAccount $RunAsAccount `\r\n\t\t\t\t\t-DeviceRestartBehavior \"$DeviceRestartBehavior\" `\r\n\t\t\t\t\t-installCommandLine $installCommandLine `\r\n\t\t\t\t\t-uninstallCommandLine $uninstallCommandLine\r\n\t\t\t}\r\n\r\n\t\t\t# Add the rules and return codes to the JSON body\r\n\t\t\tif ($Rules) {\r\n\t\t\t\t$mobileAppBody.Add(\"rules\", @($Rules))\r\n\t\t\t}\r\n\r\n\t\t\tif ($returnCodes) {\r\n\t\t\t\t$mobileAppBody.Add(\"returnCodes\", @($returnCodes))\r\n\t\t\t}\r\n\t\t\telse {\r\n\t\t\t\tWrite-Warning \"Intunewin file requires ReturnCodes to be specified\"\r\n\t\t\t\tWrite-Warning \"If you want to use the default ReturnCode run 'Get-DefaultReturnCodes'\"\r\n\t\t\t\tbreak\r\n\t\t\t}\r\n\t\t}\r\n\r\n\t\t# Create a new content version for the application\r\n\t\tWrite-Host \"Creating Content Version in the service for the updated application...\" -ForegroundColor Yellow\r\n\t\t$ContentVersion = New-MgDeviceAppManagementMobileAppAsWin32LobAppContentVersion -MobileAppId $mobileAppId -BodyParameter @{}\r\n\t\t$ContentVersionId = $ContentVersion.id\r\n\r\n\t\t# Extract the encryption information from the .intunewin file\r\n\t\tWrite-Host \"Retrieving encryption information from .intunewin file.\" -ForegroundColor Yellow\r\n\t\t$encryptionInfo = @{}\r\n\t\t$encryptionInfo.encryptionKey = $DetectionXML.ApplicationInfo.EncryptionInfo.EncryptionKey\r\n\t\t$encryptionInfo.macKey = $DetectionXML.ApplicationInfo.EncryptionInfo.macKey\r\n\t\t$encryptionInfo.initializationVector = $DetectionXML.ApplicationInfo.EncryptionInfo.initializationVector\r\n\t\t$encryptionInfo.mac = $DetectionXML.ApplicationInfo.EncryptionInfo.mac\r\n\t\t$encryptionInfo.profileIdentifier = \"ProfileVersion1\"\r\n\t\t$encryptionInfo.fileDigest = $DetectionXML.ApplicationInfo.EncryptionInfo.fileDigest\r\n\t\t$encryptionInfo.fileDigestAlgorithm = $DetectionXML.ApplicationInfo.EncryptionInfo.fileDigestAlgorithm\r\n\r\n\t\t$fileEncryptionInfo = @{}\r\n\t\t$fileEncryptionInfo.fileEncryptionInfo = $encryptionInfo\r\n\r\n\t\t# Extracting encrypted file\r\n\t\t$IntuneWinFile = Get-IntuneWinFile \"$SourceFile\" -fileName \"$FileName\"\r\n\t\t[int64]$Size = $DetectionXML.ApplicationInfo.UnencryptedContentSize\r\n\t\t$EncrySize = (Get-Item \"$IntuneWinFile\").Length\r\n\r\n\t\t# Create a new file entry in Azure for the upload\r\n\t\t$ContentVersionId = $ContentVersion.Id\r\n\t\t$fileBody = GetAppFileBody \"$FileName\" $Size $EncrySize $null\r\n\t\t$fileBody = $fileBody | ConvertTo-Json\r\n\r\n\t\t# Create a new file entry in Azure for the upload and get the file ID\r\n\t\tWrite-Host \"Creating a new file entry in Azure for the upload...\" -ForegroundColor Yellow\r\n\t\t$ContentVersionFile = New-MgDeviceAppManagementMobileAppAsWin32LobAppContentVersionFile -MobileAppId $mobileAppId -MobileAppContentId $ContentVersionId -BodyParameter $fileBody\r\n\t\t$ContentVersionFileId = $ContentVersionFile.id\r\n\r\n\t\t# Get the file URI for the upload\r\n\t\t$fileUri = \"https://graph.microsoft.com/beta/deviceAppManagement/mobileApps/$mobileAppId/microsoft.graph.win32LobApp/contentVersions/$ContentVersionId/files/$ContentVersionFileId\"\r\n\r\n\t\t# Upload the file to Azure Storage\r\n\t\tWrite-Host \"Uploading the file to Azure Storage...\" -ForegroundColor Yellow\r\n\t\t$file = WaitForFileProcessing $fileUri \"AzureStorageUriRequest\"\r\n\t\t# To support large file, this must be Uint64\r\n\t\t[UInt64]$BlockSizeMB = 4\r\n\t\tUploadFileToAzureStorage $file.azureStorageUri $IntuneWinFile $BlockSizeMB\r\n\r\n\t\t# Commit the file to the service\r\n\t\t$params = $fileEncryptionInfo | ConvertTo-Json\r\n\t\tWrite-Host \"Committing the file to the service...\" -ForegroundColor Yellow\r\n\t\t#Wait 5 seconds before committing the file\r\n\t\tStart-Sleep -Seconds 5\r\n\r\n\t\t# Commit the file to the service\r\n\t\tInvoke-MgCommitDeviceAppManagementMobileAppMicrosoftGraphWin32LobAppContentVersionFile -MobileAppId $mobileAppId -MobileAppContentId $ContentVersionId -MobileAppContentFileId $ContentVersionFileId -BodyParameter $params\r\n\r\n\t\t# Wait for the file to be processed\r\n\t\tWrite-Host \"Waiting for the file to be processed...\" -ForegroundColor Yellow\r\n\t\t$file = WaitForFileProcessing $fileUri \"CommitFile\"\r\n\r\n\t\t# This Sleep will prevent 400 error if large file is uploaded.\r\n\t\tStart-Sleep -Seconds 180\r\n\r\n\t\t# Check if we are only updating the content\r\n\t\tif ($UpdateAppContentOnly) {\r\n\t\t\t$params = @{\r\n\t\t\t\t\"@odata.type\"           = \"#microsoft.graph.win32LobApp\"\r\n\t\t\t\tcommittedContentVersion = \"$ContentVersionId\"\r\n\t\t\t}\r\n\t\t}\r\n\t\telse {\r\n\t\t\t$params = $mobileAppBody\r\n\t\t\t$params.committedContentVersion = \"$ContentVersionId\"\r\n\t\t}\r\n\r\n\t\t# Add the app icon (largeIcon) if an icon file was provided\r\n\t\tif ($IconFile) {\r\n\t\t\tWrite-Host \"Adding app icon from '$IconFile'...\" -ForegroundColor Yellow\r\n\t\t\t$params[\"largeIcon\"] = New-IntuneAppIcon -IconFile $IconFile\r\n\t\t}\r\n\r\n\t\t$params = $params | ConvertTo-Json\r\n\r\n\t\t# Update the application with the new content version\r\n\t\tWrite-Host \"Updating the application with the new content version...\" -ForegroundColor Yellow\r\n\t\tUpdate-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId -BodyParameter $params\r\n\r\n\t\t# Return the application ID\r\n\t\tWrite-Host \"Application updated successfully:\" -ForegroundColor Green\r\n\t\tGet-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId | Format-List\r\n\t}\r\n\tcatch {\r\n\t\tWrite-Host -ForegroundColor Red \"Aborting with exception: $($_.Exception.ToString())\"\r\n\t\tbreak\r\n\t}\r\n}\r\n\r\n<#\r\n.SYNOPSIS\r\nCreates a new file system rule.\r\n\r\n.DESCRIPTION\r\nThis function creates a new file system rule that you can use to specify a detection or requirement for a Win32 app.\r\n\r\n.PARAMETER ruleType\r\nThe type of rule. Valid values are 'detection' or 'requirement'.\r\n\r\n.PARAMETER path\r\nThe path to the file or folder.\r\n\r\n.PARAMETER fileOrFolderName\r\nThe name of the file or folder.\r\n\r\n.PARAMETER check32BitOn64System\r\nSpecifies whether to check for 32-bit on a 64-bit system.\r\n\r\n.PARAMETER operationType\r\nThe value type returned by the script. Valid values are 'notConfigured', 'exists', 'modifiedDate', 'createdDate', 'version', 'sizeInMB', 'doesNotExist', 'sizeInBytes', 'appVersion'.\r\n\r\n.PARAMETER operator\r\nThe operator for the detection script output comparison. Valid values are 'notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual'.\r\n\r\n.PARAMETER comparisonValue\r\nThe value to compare the script output to.\r\n\r\n.EXAMPLE\r\n# Creates a new file system rule for a Win32 app.\r\nNew-FileSystemRule -ruleType detection -path 'C:\\Program Files\\Microsoft VS Code' -fileOrFolderName 'code.exe' -check32BitOn64System $false -operationType exists -operator notConfigured -comparisonValue $null\r\n#>\r\nfunction New-FileSystemRule() {\r\n\tparam\r\n\t(\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet(\"detection\", \"requirement\")]\r\n\t\t[string]$ruleType,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$path,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$fileOrFolderName,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[bool]$check32BitOn64System,\r\n\r\n\t\t[parameter(Mandatory = $false)]\r\n\t\t[ValidateSet(\"notConfigured\", \"exists\", \"modifiedDate\", \"createdDate\", \"version\", \"sizeInMB\", \"doesNotExist\", \"sizeInBytes\", \"appVersion\")]\r\n\t\t[string]$operationType,\r\n\r\n\t\t[parameter(Mandatory = $false)]\r\n\t\t[ValidateSet(\"notConfigured\", \"equal\", \"notEqual\", \"greaterThan\", \"greaterThanOrEqual\", \"lessThan\", \"lessThanOrEqual\")]\r\n\t\t[string]$operator = \"notConfigured\",\r\n\r\n\t\t[parameter(Mandatory = $false)]\r\n\t\t$comparisonValue\r\n\t)\r\n\r\n\t$Rule = @{}\r\n\r\n\tif ($null -ne $comparisonValue -and $comparisonValue -ne \"\") {\r\n\t\t$Rule.comparisonValue = $comparisonValue\r\n\t}\r\n\telse {\r\n\t\t$Rule.comparisonValue = $null\r\n\t}\r\n\r\n\t$Rule.\"@odata.type\" = \"#microsoft.graph.win32LobAppFileSystemRule\"\r\n\t$Rule.ruleType = $ruleType\r\n\t$Rule.path = $path\r\n\t$Rule.fileOrFolderName = $fileOrFolderName\r\n\t$Rule.check32BitOn64System = $check32BitOn64System\r\n\t$Rule.operationType = $operationType\r\n\t$Rule.operator = $operator\r\n\r\n\treturn $Rule\r\n}\r\n\r\n<#\r\n.SYNOPSIS\r\nCreates a new product code rule.\r\n\r\n.DESCRIPTION\r\nThis function creates a new product code rule that you can use to specify a detection or requirement for a Win32 app.\r\n\r\n.PARAMETER ruleType\r\nThe type of rule. Valid values are 'detection' or 'requirement'.\r\n\r\n.PARAMETER productCode\r\nThe product code.\r\n\r\n.PARAMETER productVersionOperator\r\nThe operator for the detection script output comparison. Valid values are 'notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual'.\r\n\r\n.PARAMETER productVersion\r\nThe value to compare the script output to.\r\n\r\n.EXAMPLE\r\n# Creates a new product code rule for a Win32 app.\r\nNew-ProductCodeRule -ruleType detection -productCode \"{3248F0A8-6813-4B6F-8C3A-4B6C4F512345}\" -productVersionOperator equal -productVersion \"130.0\"\r\n#>\r\nfunction New-ProductCodeRule {\r\n\tparam\r\n\t(\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet('detection', 'requirement')]\r\n\t\t[string]$ruleType,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$productCode,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet('notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual')]\r\n\t\t[string]$productVersionOperator,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$productVersion\r\n\t)\r\n\r\n\t$Rule = @{}\r\n\t$Rule.\"@odata.type\" = \"#microsoft.graph.win32LobAppProductCodeRule\"\r\n\t$Rule.ruleType = $ruleType\r\n\t$Rule.productCode = $productCode\r\n\t$Rule.productVersionOperator = $productVersionOperator\r\n\t$Rule.productVersion = $productVersion\r\n\r\n\treturn $Rule\r\n}\r\n\r\n<#\r\n.SYNOPSIS\r\nCreates a new registry rule.\r\n\r\n.DESCRIPTION\r\nThis function creates a new registry rule that you can use to specify a detection or requirement for a Win32 app.\r\n\r\n.PARAMETER ruleType\r\nThe type of rule. Valid values are 'detection' or 'requirement'.\r\n\r\n.PARAMETER keyPath\r\nThe registry key path.\r\n\r\n.PARAMETER valueName\r\nThe registry value name.\r\n\r\n.PARAMETER operationType\r\nThe operation data type (data type returned by the script). Valid values are 'notConfigured', 'exists', 'doesNotExist', 'string', 'integer', 'float', 'version'.\r\n\r\n.PARAMETER operator\r\nThe operator for the detection script output comparison. Valid values are 'notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual'.\r\n\r\n.PARAMETER comparisonValue\r\nThe value to compare the script output to.\r\n\r\n.EXAMPLE\r\n# Creates a new registry rule for a Win32 app.\r\nNew-RegistryRule -ruleType detection -keyPath \"HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\xyz\" -valueName \"DisplayName\" -operationType string -operator equal -comparisonValue \"VSCode\"\r\n#>\r\nfunction New-RegistryRule {\r\n\tparam\r\n\t(\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet('detection', 'requirement')]\r\n\t\t[string]$ruleType,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$keyPath,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$valueName,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet('notConfigured', 'exists', 'doesNotExist', 'string', 'integer', 'float', 'version')]\r\n\t\t[string]$operationType,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet('notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual')]\r\n\t\t[string]$operator,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$comparisonValue\r\n\t)\r\n\r\n\t$Rule = @{}\r\n\t$Rule.\"@odata.type\" = \"#microsoft.graph.win32LobAppRegistryRule\"\r\n\t$Rule.ruleType = $ruleType\r\n\t$Rule.keyPath = $keyPath\r\n\t$Rule.valueName = $valueName\r\n\t$Rule.operationType = $operationType\r\n\t$Rule.operator = $operator\r\n\t$Rule.comparisonValue = $comparisonValue\r\n\r\n\treturn $Rule\r\n}\r\n\r\n<#\r\n.SYNOPSIS\r\nCreates a new script detection rule.\r\n\r\n.DESCRIPTION\r\nThis function creates a new script detection rule that you can use to specify a detection for a Win32 app.\r\n\r\n.PARAMETER ScriptFile\r\nThe path to the script file.\r\n\r\n.PARAMETER EnforceSignatureCheck\r\nSpecifies whether to enforce signature check.\r\n\r\n.PARAMETER RunAs32Bit\r\nSpecifies whether to run the script as 32-bit.\r\n\r\n.EXAMPLE\r\n# Creates a new script detection rule for a Win32 app.\r\nNew-ScriptDetectionRule -ScriptFile \"E:\\VSCodeDetection.ps1\" -EnforceSignatureCheck $false -RunAs32Bit $false\r\n\r\n.NOTES\r\nThis function only creates a script detection rule. To create a script requirement rule, use the New-ScriptRequirementRule function.\r\n#>\r\nfunction New-ScriptDetectionRule() {\r\n\tparam\r\n\t(\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$ScriptFile,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[bool]$EnforceSignatureCheck,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[bool]$RunAs32Bit\r\n\r\n\t)\r\n\tif (!(Test-Path \"$ScriptFile\")) {\r\n\t\tWrite-Host \"Could not find file '$ScriptFile'...\" -ForegroundColor Red\r\n\t\tWrite-Host \"Script can't continue...\" -ForegroundColor Red\r\n\t\tbreak\r\n\t}\r\n\r\n\t$ScriptContent = [System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes(\"$ScriptFile\"))\r\n\r\n\t$Rule = @{}\r\n\t$Rule.\"@odata.type\" = \"#microsoft.graph.win32LobAppPowerShellScriptRule\"\r\n\t$Rule.ruleType = \"detection\"\r\n\t$Rule.enforceSignatureCheck = $EnforceSignatureCheck\r\n\t$Rule.runAs32Bit = $RunAs32Bit\r\n\t$Rule.scriptContent = \"$ScriptContent\"\r\n\t$Rule.operationType = \"notConfigured\"\r\n\t$Rule.operator = \"notConfigured\"\r\n\r\n\treturn $Rule\r\n}\r\n\r\n<#\r\n.SYNOPSIS\r\nCreates a new script requirement rule.\r\n\r\n.DESCRIPTION\r\nThis function creates a new script requirement rule that you can use to specify a requirement for a Win32 app.\r\n\r\n.PARAMETER ScriptFile\r\nThe path to the script file.\r\n\r\n.PARAMETER DisplayName\r\nThe display name of the rule.\r\n\r\n.PARAMETER EnforceSignatureCheck\r\nSpecifies whether to enforce signature check.\r\n\r\n.PARAMETER RunAs32Bit\r\nSpecifies whether to run the script as 32-bit.\r\n\r\n.PARAMETER RunAsAccount\r\nThe account to run the script as. Valid values are 'system' or 'user'.\r\n\r\n.PARAMETER OperationType\r\nThe operation data type (data type returned by the script). Valid values are 'notConfigured', 'string', 'dateTime', 'integer', 'float', 'version', 'boolean'.\r\n\r\n.PARAMETER Operator\r\nThe operator for the detection script output comparison. Valid values are 'notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual'.\r\n\r\n.PARAMETER ComparisonValue\r\nThe value to compare the script output to.\r\n\r\n.EXAMPLE\r\n# Creates a new script requirement rule for a Win32 app.\r\nNew-ScriptRequirementRule -ScriptFile \"E:\\VSCodeRequirement.ps1\" -DisplayName \"VS Code Requirement\" -EnforceSignatureCheck $false -RunAs32Bit $false -RunAsAccount \"system\" -OperationType \"integer\" -Operator \"equal\" -ComparisonValue \"0\"\r\n\r\n.NOTES\r\nThis function only creates a script requirement rule. To create a script detection rule, use the New-ScriptDetectionRule function.\r\n#>\r\nfunction New-ScriptRequirementRule {\r\n\tparam\r\n\t(\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$ScriptFile,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$DisplayName,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[bool]$EnforceSignatureCheck,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[bool]$RunAs32Bit,\r\n\r\n\t\t#Valid values are 'system' or 'user'\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet('system', 'user')]\r\n\t\t[string]$RunAsAccount,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet('notConfigured', 'string', 'dateTime', 'integer', 'float', 'version', 'boolean')]\r\n\t\t[string]$OperationType,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet('notConfigured', 'equal', 'notEqual', 'greaterThan', 'greaterThanOrEqual', 'lessThan', 'lessThanOrEqual')]\r\n\t\t[string]$Operator,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$ComparisonValue\r\n\t)\r\n\r\n\tif (!(Test-Path \"$ScriptFile\")) {\r\n\t\tWrite-Host \"Could not find file '$ScriptFile'...\" -ForegroundColor Red\r\n\t\tWrite-Host \"Script can't continue...\" -ForegroundColor Red\r\n\t\tbreak\r\n\t}\r\n\r\n\t$ScriptContent = [System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes(\"$ScriptFile\"))\r\n\r\n\t$Rule = @{}\r\n\t$Rule.\"@odata.type\" = \"#microsoft.graph.win32LobAppPowerShellScriptRule\"\r\n\t$Rule.displayName = $DisplayName\r\n\t$Rule.ruleType = \"requirement\"\r\n\t$Rule.enforceSignatureCheck = $EnforceSignatureCheck\r\n\t$Rule.runAs32Bit = $RunAs32Bit\r\n\t$Rule.scriptContent = \"$ScriptContent\"\r\n\t$Rule.operationType = $OperationType\r\n\t$Rule.operator = $Operator\r\n\t$Rule.comparisonValue = $ComparisonValue\r\n\t$Rule.runAsAccount = $RunAsAccount\r\n\r\n\treturn $Rule\r\n}\r\n\r\n<#\r\n.SYNOPSIS\r\nCreates a new return code object.\r\n\r\n.DESCRIPTION\r\nThis function creates a new return code object that you can use to specify the return codes for a Win32 app.\r\n\r\n.PARAMETER returnCode\r\nThe return code value.\r\n\r\n.PARAMETER type\r\nThe type of return code. Valid values are 'success', 'softReboot', 'hardReboot\r\n\r\n.EXAMPLE\r\n# Creates a new return code object with a return code of 0 and a type of 'success'\r\nNew-ReturnCode -returnCode 0 -type 'success'\r\n#>\r\nfunction New-ReturnCode() {\r\n\tparam\r\n\t(\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[int]$returnCode,\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet('success', 'softReboot', 'hardReboot', 'retry')]\r\n\t\t$type\r\n\t)\r\n\r\n\t@{\"returnCode\" = $returnCode; \"type\" = \"$type\" }\r\n}\r\n\r\n<#\r\n.SYNOPSIS\r\nConverts an image file to a mimeContent object for use as a Win32 app icon.\r\n\r\n.DESCRIPTION\r\nThis function reads an image file from disk, base64-encodes its content, and returns a mimeContent hashtable that can be assigned to a mobileApp's largeIcon property. Supported image types are .png, .jpg, .jpeg, and .gif.\r\n\r\n.PARAMETER IconFile\r\nThe path to the image file to use as the app icon.\r\n\r\n.EXAMPLE\r\n# Creates a mimeContent icon object from a .png file.\r\nNew-IntuneAppIcon -IconFile \"C:\\IntuneApps\\vscode\\icon.png\"\r\n#>\r\nfunction New-IntuneAppIcon() {\r\n\tparam\r\n\t(\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$IconFile\r\n\t)\r\n\r\n\t# Check the icon file exists\r\n\tif (!(Test-Path \"$IconFile\")) {\r\n\t\tWrite-Host \"Icon file '$IconFile' doesn't exist...\" -ForegroundColor Red\r\n\t\tthrow \"Icon file not found: $IconFile\"\r\n\t}\r\n\r\n\t# Determine the MIME type from the file extension\r\n\t$Extension = [System.IO.Path]::GetExtension(\"$IconFile\").ToLower()\r\n\tswitch ($Extension) {\r\n\t\t\".png\" { $MimeType = \"image/png\" }\r\n\t\t\".jpg\" { $MimeType = \"image/jpeg\" }\r\n\t\t\".jpeg\" { $MimeType = \"image/jpeg\" }\r\n\t\t\".gif\" { $MimeType = \"image/gif\" }\r\n\t\tdefault {\r\n\t\t\tWrite-Host \"Unsupported icon file type '$Extension'. Supported types are .png, .jpg, .jpeg, and .gif.\" -ForegroundColor Red\r\n\t\t\tthrow \"Unsupported icon file type: $Extension\"\r\n\t\t}\r\n\t}\r\n\r\n\t# Read the image file and base64-encode its content\r\n\t$IconContent = [System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes(\"$IconFile\"))\r\n\r\n\t# Construct and return the mimeContent object (used as the app's largeIcon)\r\n\t$Icon = @{\r\n\t\t\"@odata.type\" = \"#microsoft.graph.mimeContent\"\r\n\t\t\"type\"        = $MimeType\r\n\t\t\"value\"       = $IconContent\r\n\t}\r\n\r\n\treturn $Icon\r\n}\r\n\r\n####################################################\r\n# Function to wait for file processing to complete by polling the file upload state\r\nfunction WaitForFileProcessing($fileUri, $stage) {\r\n\t$attempts = 60\r\n\t$waitTimeInSeconds = 1\r\n\t$successState = \"$($stage)Success\"\r\n\t$pendingState = \"$($stage)Pending\"\r\n\r\n\t$file = $null\r\n\twhile ($attempts -gt 0) {\r\n\t\t$file = Invoke-MgGraphRequest -Method GET -Uri $fileUri\r\n\t\tif ($file.uploadState -eq $successState) {\r\n\t\t\tbreak\r\n\t\t}\r\n\t\telseif ($file.uploadState -ne $pendingState) {\r\n\t\t\tthrow \"File upload state is not success: $($file.uploadState)\"\r\n\t\t}\r\n\r\n\t\tStart-Sleep $waitTimeInSeconds\r\n\t\t$attempts--\r\n\t}\r\n\r\n\tif ($null -eq $file) {\r\n\t\tthrow \"File request did not complete in the allotted time.\"\r\n\t}\r\n\r\n\t$file\r\n}\r\n\r\n####################################################\r\n# Function to upload a file to Azure Storage using the SAS URI\r\nfunction UploadFileToAzureStorage($sasUri, $filepath, $blockSizeMB,  $fileUri) {\r\n\t# Chunk size in MiB\r\n\t$chunkSizeInBytes = (1024 * 1024 * $blockSizeMB)\r\n\r\n\t# Read the whole file and find the total chunks.\r\n\t#[byte[]]$bytes = Get-Content $filepath -Encoding byte;\r\n\t# Using ReadAllBytes method as the Get-Content used alot of memory on the machine\r\n\t$fileStream = [System.IO.File]::OpenRead($filepath)\r\n\t$chunks = [Math]::Ceiling($fileStream.Length / $chunkSizeInBytes)\r\n\r\n\t# Upload each chunk.\r\n\t$ids = @()\r\n\t$cc = 1\r\n\t$chunk = 0\r\n\r\n\t# Start the timer for SAS URI renewal\r\n\t$SASRenewalTimer = [System.Diagnostics.Stopwatch]::StartNew()\r\n\r\n\r\n\twhile ($fileStream.Position -lt $fileStream.Length) {\r\n\t\t$id = [System.Convert]::ToBase64String([System.Text.Encoding]::ASCII.GetBytes($chunk.ToString(\"0000\")))\r\n\t\t$ids += $id\r\n\r\n\t\t$size = [Math]::Min($chunkSizeInBytes, $fileStream.Length - $fileStream.Position)\r\n\t\t$body = New-Object byte[] $size\r\n\t\t$fileStream.Read($body, 0, $size) > $null\r\n\t\t$totalBytes += $size\r\n\r\n\t\tWrite-Progress -Activity \"Uploading File to Azure Storage\" -Status \"Uploading chunk $cc of $chunks\" -PercentComplete ($cc / $chunks * 100)\r\n\t\t$cc++\r\n\r\n\t\tUploadAzureStorageChunk $sasUri $id $body | Out-Null\r\n\t\t$chunk++\r\n\r\n\t    # Ensure the SAS Uri is renewed after 450000 msec passed.\r\n\t\tif ($SASRenewalTimer.ElapsedMilliseconds -ge 450000) {\r\n\t\t\tWrite-Host -Message \"SAS Uri renewal is required, attempting to renew\"\r\n\t\t\t$RenewSASURIRequest = Invoke-MgGraphRequest -uri \"$($fileUri)/renewUpload\" -Method \"POST\" -Body \"{}\"\r\n\t\t\t$Stage = \"AzureStorageUriRenewal\"\r\n\t\t\tdo {\r\n\t\t\t\t$GraphRequest = Invoke-MgGraphRequest -uri $fileUri -Method \"GET\"\r\n\t\t\t\tswitch ($GraphRequest.uploadState) {\r\n\t\t\t\t\t\"$($Stage)Pending\" {\r\n\t\t\t\t\t\tWrite-Host -Message \"Intune service request for operation '$($Stage)' is in pending state, sleeping for 10 seconds\"\r\n\t\t\t\t\t\tStart-Sleep -Seconds 10\r\n\t\t\t\t\t}\r\n\t\t\t\t\t\"$($Stage)Failed\" {\r\n\t\t\t\t\t\tWrite-Host -Message \"Intune service request for operation '$($Stage)' failed\"\r\n\t\t\t\t\t\tthrow\r\n\t\t\t\t\t}\r\n\t\t\t\t\t\"$($Stage)TimedOut\" {\r\n\t\t\t\t\t\tWrite-Host -Message \"Intune service request for operation '$($Stage)' timed out\"\r\n\t\t\t\t\t\tthrow\r\n\t\t\t\t\t}\r\n\t\t\t\t}\r\n\t\t\t}\r\n\t\t\tuntil ($GraphRequest.uploadState -like \"$($Stage)Success\")\r\n\t\t\tWrite-Host -Message \"Intune service request for operation '$($Stage)' was successful with uploadState: $($GraphRequest.uploadState)\"\r\n\r\n\t\t\t$SASRenewalTimer.Restart()\r\n\t\t}\r\n\t}\r\n\r\n\t# Stop timer\r\n\t$SASRenewalTimer.Stop()\r\n\r\n\t$fileStream.Close()\r\n\tWrite-Progress -Completed -Activity \"Uploading File to Azure Storage\"\r\n\r\n\t# Finalize the upload.\r\n\tFinalizeAzureStorageUpload $sasUri $ids | Out-Null\r\n}\r\n\r\n\r\n####################################################\r\n# Function to upload a chunk to Azure Storage\r\nfunction UploadAzureStorageChunk($sasUri, $id, $body) {\r\n\t$uri = \"$sasUri&comp=block&blockid=$id\"\r\n\t$request = \"PUT $uri\"\r\n\r\n\t$headers = @{\r\n\t\t\"x-ms-blob-type\" = \"BlockBlob\"\r\n\t\t\"Content-Type\"   = \"application/octet-stream\"\r\n\t}\r\n\r\n\ttry {\r\n\t\tInvoke-WebRequest -Headers $headers $uri -Method Put -Body $body | Out-Null\r\n\t}\r\n\tcatch {\r\n\t\tWrite-Host -ForegroundColor Red $request\r\n\t\tWrite-Host -ForegroundColor Red $_.Exception.Message\r\n\t\tthrow\r\n\t}\r\n}\r\n\r\n####################################################\r\n# Function to finalize the Azure Storage upload\r\nfunction FinalizeAzureStorageUpload($sasUri, $ids) {\r\n\t$uri = \"$sasUri&comp=blocklist\"\r\n\t$request = \"PUT $uri\"\r\n\r\n\t$xml = '<?xml version=\"1.0\" encoding=\"utf-8\"?><BlockList>'\r\n\tforeach ($id in $ids) {\r\n\t\t$xml += \"<Latest>$id</Latest>\"\r\n\t}\r\n\t$xml += '</BlockList>'\r\n\r\n\tif ($logRequestUris) { Write-Host $request; }\r\n\tif ($logContent) { Write-Host -ForegroundColor Gray $xml; }\r\n\r\n\t$headers = @{\r\n\t\t\"Content-Type\" = \"text/plain\"\r\n\t}\r\n\r\n\ttry {\r\n\t\tInvoke-WebRequest $uri -Method Put -Body $xml -Headers $headers\r\n\t}\r\n\tcatch {\r\n\t\tWrite-Host -ForegroundColor Red $request\r\n\t\tWrite-Host -ForegroundColor Red $_.Exception.Message\r\n\t\tthrow\r\n\t}\r\n}\r\n\r\n####################################################\r\n# Function to construct the JSON body for a Win32 app\r\nfunction GetWin32AppBody() {\r\n\tparam\r\n\t(\r\n\t\t[parameter(Mandatory = $true, ParameterSetName = \"MSI\", Position = 1)]\r\n\t\t[Switch]$MSI,\r\n\r\n\t\t[parameter(Mandatory = $true, ParameterSetName = \"EXE\", Position = 1)]\r\n\t\t[Switch]$EXE,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$displayName,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$publisher,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$description,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$filename,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t[string]$SetupFileName,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet('system', 'user')]\r\n\t\t[string]$RunAsAccount,\r\n\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateSet('basedOnReturnCode', 'allow', 'suppress', 'force')]\r\n\t\t[string]$DeviceRestartBehavior,\r\n\r\n\t\t[parameter(Mandatory = $true, ParameterSetName = \"EXE\")]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t$installCommandLine,\r\n\r\n\t\t[parameter(Mandatory = $true, ParameterSetName = \"EXE\")]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t$uninstallCommandLine,\r\n\r\n\t\t[parameter(Mandatory = $true, ParameterSetName = \"MSI\")]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t$MsiPackageType,\r\n\r\n\t\t[parameter(Mandatory = $true, ParameterSetName = \"MSI\")]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t$MsiProductCode,\r\n\r\n\t\t[parameter(Mandatory = $false, ParameterSetName = \"MSI\")]\r\n\t\t$MsiProductName,\r\n\r\n\t\t[parameter(Mandatory = $true, ParameterSetName = \"MSI\")]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t$MsiProductVersion,\r\n\r\n\t\t[parameter(Mandatory = $false, ParameterSetName = \"MSI\")]\r\n\t\t$MsiPublisher,\r\n\r\n\t\t[parameter(Mandatory = $true, ParameterSetName = \"MSI\")]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t$MsiRequiresReboot,\r\n\r\n\t\t[parameter(Mandatory = $true, ParameterSetName = \"MSI\")]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t$MsiUpgradeCode\r\n\t)\r\n\r\n\tif ($MSI) {\r\n\t\t$body = @{ \"@odata.type\" = \"#microsoft.graph.win32LobApp\" }\r\n\t\t$body.applicableArchitectures = \"x64,x86\"\r\n\t\t$body.description = $description\r\n\t\t$body.developer = \"\"\r\n\t\t$body.displayName = $displayName\r\n\t\t$body.fileName = $filename\r\n\t\t$body.installCommandLine = \"msiexec /i `\"$SetupFileName`\"\"\r\n\t\t$body.installExperience = @{\r\n\t\t\t\"runAsAccount\"          = \"$RunAsAccount\"\r\n\t\t\t\"deviceRestartBehavior\" = $DeviceRestartBehavior\r\n\t\t}\r\n\t\t$body.informationUrl = $null\r\n\t\t$body.isFeatured = $false\r\n\t\t$body.minimumSupportedOperatingSystem = @{\"v10_1607\" = $true }\r\n\t\t$body.msiInformation = @{\r\n\t\t\t\"packageType\"    = \"$MsiPackageType\"\r\n\t\t\t\"productCode\"    = \"$MsiProductCode\"\r\n\t\t\t\"productName\"    = \"$MsiProductName\"\r\n\t\t\t\"productVersion\" = \"$MsiProductVersion\"\r\n\t\t\t\"publisher\"      = \"$MsiPublisher\"\r\n\t\t\t\"requiresReboot\" = \"$MsiRequiresReboot\"\r\n\t\t\t\"upgradeCode\"    = \"$MsiUpgradeCode\"\r\n\t\t\t\"@odata.type\"    = \"#microsoft.graph.win32LobAppMsiInformation\"\r\n\t\t}\r\n\t\t$body.notes = \"\"\r\n\t\t$body.owner = \"\"\r\n\t\t$body.privacyInformationUrl = $null\r\n\t\t$body.publisher = $publisher\r\n\t\t$body.runAs32bit = $false\r\n\t\t$body.setupFilePath = $SetupFileName\r\n\t\t$body.uninstallCommandLine = \"msiexec /x `\"$MsiProductCode`\"\"\r\n\t}\r\n\telseif ($EXE) {\r\n\t\t$body = @{ \"@odata.type\" = \"#microsoft.graph.win32LobApp\" }\r\n\t\t$body.description = $description\r\n\t\t$body.developer = \"\"\r\n\t\t$body.displayName = $displayName\r\n\t\t$body.fileName = $filename\r\n\t\t$body.installCommandLine = $installCommandLine\r\n\t\t$body.installExperience = @{\r\n\t\t\t\"runAsAccount\"          = $RunAsAccount\r\n\t\t\t\"deviceRestartBehavior\" = $DeviceRestartBehavior\r\n\t\t}\r\n\t\t$body.informationUrl = $null\r\n\t\t$body.isFeatured = $false\r\n\t\t$body.minimumSupportedOperatingSystem = @{\"v10_1607\" = $true }\r\n\t\t$body.msiInformation = $null\r\n\t\t$body.notes = \"\"\r\n\t\t$body.owner = \"\"\r\n\t\t$body.privacyInformationUrl = $null\r\n\t\t$body.publisher = $publisher\r\n\t\t$body.runAs32bit = $false\r\n\t\t$body.setupFilePath = $SetupFileName\r\n\t\t$body.uninstallCommandLine = $uninstallCommandLine\r\n\t}\r\n\r\n\t$body\r\n}\r\n\r\n####################################################\r\n# Function to test if the source file exists\r\nFunction Test-SourceFile() {\r\n\tparam\r\n\t(\r\n\t\t[parameter(Mandatory = $true)]\r\n\t\t[ValidateNotNullOrEmpty()]\r\n\t\t$SourceFile\r\n\t)\r\n\ttry {\r\n\r\n\t\tif (!(test-path \"$SourceFile\")) {\r\n\t\t\tWrite-Host\r\n\t\t\tWrite-Host \"Source File '$sourceFile' doesn't exist...\" -ForegroundColor Red\r\n\t\t\tthrow\r\n\t\t}\r\n\t}\r\n\r\n\tcatch {\r\n\t\tWrite-Host -ForegroundColor Red $_.Exception.Message\r\n\t\tWrite-Host\r\n\t\tbreak\r\n\t}\r\n}\r\n\r\n####################################################\r\n# Function to get the default return codes\r\nfunction Get-DefaultReturnCodes() {\r\n\t@{\"returnCode\" = 0; \"type\" = \"success\" }, `\r\n\t@{\"returnCode\" = 1707; \"type\" = \"success\" }, `\r\n\t@{\"returnCode\" = 3010; \"type\" = \"softReboot\" }, `\r\n\t@{\"returnCode\" = 1641; \"type\" = \"hardReboot\" }, `\r\n\t@{\"returnCode\" = 1618; \"type\" = \"retry\" }\r\n\r\n}\r\n\r\n####################################################\r\n# Function to extract the IntuneWin XML file from the .intunewin file\r\nFunction Get-IntuneWinXML() {\r\n\tparam\r\n\t(\r\n\t\t[Parameter(Mandatory = $true)]\r\n\t\t$SourceFile,\r\n\r\n\t\t[Parameter(Mandatory = $true)]\r\n\t\t$fileName,\r\n\r\n\t\t[Parameter(Mandatory = $false)]\r\n\t\t[bool]$removeitem = $true\r\n\t)\r\n\r\n\tTest-SourceFile \"$SourceFile\"\r\n\r\n\t$Directory = [System.IO.Path]::GetDirectoryName(\"$SourceFile\")\r\n\r\n\tAdd-Type -Assembly System.IO.Compression.FileSystem\r\n\t$zip = [IO.Compression.ZipFile]::OpenRead(\"$SourceFile\")\r\n\r\n\t$zip.Entries | Where-Object { $_.Name -like \"$filename\" } | ForEach-Object {\r\n\t\t[System.IO.Compression.ZipFileExtensions]::ExtractToFile($_, \"$Directory\\$filename\", $true)\r\n\t}\r\n\r\n\t$zip.Dispose()\r\n\r\n\t[xml]$IntuneWinXML = Get-Content \"$Directory\\$filename\"\r\n\r\n\treturn $IntuneWinXML\r\n\r\n\tif ($removeitem -eq $true) { remove-item \"$Directory\\$filename\" }\r\n}\r\n\r\n####################################################\r\n# Function to extract the IntuneWin file from the .intunewin file\r\nFunction Get-IntuneWinFile() {\r\n\tparam\r\n\t(\r\n\t\t[Parameter(Mandatory = $true)]\r\n\t\t$SourceFile,\r\n\r\n\t\t[Parameter(Mandatory = $true)]\r\n\t\t$fileName,\r\n\r\n\t\t[Parameter(Mandatory = $false)]\r\n\t\t[string]$Folder = \"win32\"\r\n\t)\r\n\r\n\t$Directory = [System.IO.Path]::GetDirectoryName(\"$SourceFile\")\r\n\r\n\tif (!(Test-Path \"$Directory\\$folder\")) {\r\n\t\tNew-Item -ItemType Directory -Path \"$Directory\" -Name \"$folder\" -Force\r\n\t}\r\n\r\n\tAdd-Type -Assembly System.IO.Compression.FileSystem\r\n\t$zip = [IO.Compression.ZipFile]::OpenRead((\"$SourceFile\"))\r\n\t$zip.Entries | Where-Object { $_.Name -like \"$filename\" } | ForEach-Object {\r\n\t\t[System.IO.Compression.ZipFileExtensions]::ExtractToFile($_, \"$Directory\\$folder\\$filename\", $true)\r\n\t}\r\n\r\n\t$zip.Dispose()\r\n\r\n\treturn \"$Directory\\$folder\\$filename\"\r\n\r\n\tif ($removeitem -eq $true) { remove-item \"$Directory\\$filename\" }\r\n}\r\n\r\n####################################################\r\n# Function to create a new app file body containing the file and encryption information\r\nfunction GetAppFileBody($name, $size, $sizeEncrypted, $manifest) {\r\n\t$body = @{ \"@odata.type\" = \"#microsoft.graph.mobileAppContentFile\" }\r\n\t$body.name = $name\r\n\t$body.size = $size\r\n\t$body.sizeEncrypted = $sizeEncrypted\r\n\t$body.manifest = $manifest\r\n\t$body.isDependency = $false\r\n\r\n\t$body\r\n}","teaching":["Update Win32 app content","Updating app content requires reviewing install/uninstall commands, detection, content version and the intended upgrade behavior. Upload success is not install success.","Read only. Check signature, dependencies, application compatibility and authorized pilot.","Design a hypothetical update and test old/new versions and exit codes.",null,"What distinguishes successive uploaded app content revisions?","content version"],"kind":"write-reference-only"},{"repository":"microsoft/mggraph-intune-samples","path":"LOB_Application/iOS_Application_LOB_App.ps1","sha":"9ee1414069b78759d234350773b29a811d98be09","lesson":14,"topic":"iOS line-of-business application publishing","url":"https://github.com/microsoft/mggraph-intune-samples/blob/main/LOB_Application/iOS_Application_LOB_App.ps1","markdown":"<#\n.COPYRIGHT\nCopyright (c) Microsoft Corporation. All rights reserved. Licensed under the MIT license.\nSee LICENSE in the project root for license information.\n#>\n\nImport-Module Microsoft.Graph.Devices.CorporateManagement\n\n<# region Authentication\nTo authenticate, you'll use the Microsoft Graph PowerShell SDK. If you haven't already installed the SDK, see this guide:\nhttps://learn.microsoft.com/en-us/powershell/microsoftgraph/installation?view=graph-powershell-1.0\nThe PowerShell SDK supports two types of authentication: delegated access, and app-only access.\nFor details on using delegated access, see this guide here:\nhttps://learn.microsoft.com/powershell/microsoftgraph/get-started?view=graph-powershell-1.0\nFor details on using app-only access for unattended scenarios, see Use app-only authentication with the Microsoft Graph PowerShell SDK:\nhttps://learn.microsoft.com/powershell/microsoftgraph/app-only?view=graph-powershell-1.0&tabs=azure-portal\n#>\n\n#Path for temp copies of extracted .ipa files\n$ExtractedPath = Join-Path -Path $env:TEMP -ChildPath ([System.IO.Path]::GetRandomFileName())\n\n#Base URL for Graph API calls\n$baseUrl = \"https://graph.microsoft.com/v1.0/deviceAppManagement/\"\n\n$sleep = 30\n\n####################################################\n# Function to get the path to the IPA file\nfunction Get-IpaPath {\n    [CmdletBinding()]\n    param\n    (\n        [Parameter(Mandatory = $true)]\n        [string]\n        $Path\n    )\n    $IpaPath = Get-ChildItem -Path $Path -Filter *.ipa -Recurse -ErrorAction SilentlyContinue\n    if (!$IpaPath) {\n        throw \"No IPA file found in $Path\"\n        return\n    }\n    return $IpaPath.FullName\n}\n\n####################################################\n# Function that uploads a source file chunk to the Intune Service SAS URI location.\nfunction UploadAzureStorageChunk($sasUri, $id, $body) {\n\n    $uri = \"$sasUri&comp=block&blockid=$id\";\n    $request = \"PUT $uri\";\n\n    $headers = @{\n        \"x-ms-blob-type\" = \"BlockBlob\";\n        \"Content-Type\" = \"application/octet-stream\"\n    };\n\n    try {\n        Invoke-WebRequest -Headers $headers $uri -Method Put -Body $body;\n    }\n    catch {\n        Write-Host -ForegroundColor Red $request;\n        Write-Host -ForegroundColor Red $_.Exception.Message;\n        throw;\n    }\n}\n\n####################################################\n# Function that takes all the chunk ids and joins them back together to recreate the file\nfunction FinalizeAzureStorageUpload($sasUri, $ids) {\n    $uri = \"$sasUri&comp=blocklist\";\n    $request = \"PUT $uri\";\n\n    $xml = '<?xml version=\"1.0\" encoding=\"utf-8\"?><BlockList>';\n    foreach ($id in $ids) {\n        $xml += \"<Latest>$id</Latest>\";\n    }\n    $xml += '</BlockList>';\n\n    if ($logRequestUris) { Write-Host $request; }\n    if ($logContent) { Write-Host -ForegroundColor Gray $xml; }\n\n    $headers = @{\n        \"Content-Type\" = \"text/plain\"\n    };\n\n    try {\n        Invoke-WebRequest $uri -Method Put -Body $xml -Headers $headers;\n    }\n    catch {\n        Write-Host -ForegroundColor Red $request;\n        Write-Host -ForegroundColor Red $_.Exception.Message;\n        throw;\n    }\n}\n\n####################################################\n# Function that splits the source file into chunks and calls the upload to the Intune Service SAS URI location, and finalizes the upload\nfunction UploadFileToAzureStorage($sasUri, $filepath, $blockSizeMB) {\n\n    # Chunk size in MiB\n    $chunkSizeInBytes = 1024 * 1024 * $blockSizeMB;\n\n    # Read the whole file and find the total chunks.\n    #[byte[]]$bytes = Get-Content $filepath -Encoding byte;\n    # Using ReadAllBytes method as the Get-Content used alot of memory on the machine\n    $fileStream = [System.IO.File]::OpenRead($filepath)\n    $chunks = [Math]::Ceiling($fileStream.Length / $chunkSizeInBytes)\n\n    # Upload each chunk.\n    $ids = @();\n    $cc = 1\n    $chunk = 0\n    while ($fileStream.Position -lt $fileStream.Length) {\n        $id = [System.Convert]::ToBase64String([System.Text.Encoding]::ASCII.GetBytes($chunk.ToString(\"0000\")));\n        $ids += $id;\n\n        $size = [Math]::Min($chunkSizeInBytes, $fileStream.Length - $fileStream.Position)\n        $body = New-Object byte[] $size\n        $fileStream.Read($body, 0, $size)\n        $totalBytes += $size\n\n        Write-Progress -Activity \"Uploading File to Azure Storage\" -Status \"Uploading chunk $cc of $chunks\" `\n            -PercentComplete ($cc / $chunks * 100)\n        $cc++\n\n        UploadAzureStorageChunk $sasUri $id $body | Out-Null\n        $chunk++\n    }\n\n    Write-Progress -Completed -Activity \"Uploading File to Azure Storage\"\n\n    # Finalize the upload.\n    FinalizeAzureStorageUpload $sasUri $ids | Out-Null\n}\n\n####################################################\n# Function to generate encryption key\nfunction GenerateKey {\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create();\n        $aesProvider = New-Object System.Security.Cryptography.AesCryptoServiceProvider;\n        $aesProvider.GenerateKey();\n        $aesProvider.Key;\n    }\n    finally {\n        if ($null -ne $aesProvider) { $aesProvider.Dispose(); }\n        if ($null -ne $aes) { $aes.Dispose(); }\n    }\n}\n\n####################################################\n# Function to generate HMAC key\nfunction GenerateIV {\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create();\n        $aes.IV;\n    }\n    finally {\n        if ($null -ne $aes) { $aes.Dispose(); }\n    }\n}\n\n####################################################\n# Function to create the encrypted target file compute HMAC value, and return the HMAC value\nfunction EncryptFileWithIV($sourceFile, $targetFile, $encryptionKey, $hmacKey, $initializationVector) {\n    $bufferBlockSize = 1024 * 4;\n    $computedMac = $null;\n\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create();\n        $hmacSha256 = New-Object System.Security.Cryptography.HMACSHA256;\n        $hmacSha256.Key = $hmacKey;\n        $hmacLength = $hmacSha256.HashSize / 8;\n\n        $buffer = New-Object byte[] $bufferBlockSize;\n        $bytesRead = 0;\n\n        $targetStream = [System.IO.File]::Open($targetFile, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::Read);\n        $targetStream.Write($buffer, 0, $hmacLength + $initializationVector.Length);\n\n        try {\n            $encryptor = $aes.CreateEncryptor($encryptionKey, $initializationVector);\n            $sourceStream = [System.IO.File]::Open($sourceFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read);\n            $cryptoStream = New-Object System.Security.Cryptography.CryptoStream -ArgumentList @($targetStream, $encryptor, [System.Security.Cryptography.CryptoStreamMode]::Write);\n\n            $targetStream = $null;\n            while (($bytesRead = $sourceStream.Read($buffer, 0, $bufferBlockSize)) -gt 0) {\n                $cryptoStream.Write($buffer, 0, $bytesRead);\n                $cryptoStream.Flush();\n            }\n            $cryptoStream.FlushFinalBlock();\n        }\n        finally {\n            if ($null -ne $cryptoStream) { $cryptoStream.Dispose(); }\n            if ($null -ne $sourceStream) { $sourceStream.Dispose(); }\n            if ($null -ne $encryptor) { $encryptor.Dispose(); }\n        }\n\n        try {\n            $finalStream = [System.IO.File]::Open($targetFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read)\n\n            $finalStream.Seek($hmacLength, [System.IO.SeekOrigin]::Begin) > $null;\n            $finalStream.Write($initializationVector, 0, $initializationVector.Length);\n            $finalStream.Seek($hmacLength, [System.IO.SeekOrigin]::Begin) > $null;\n\n            $hmac = $hmacSha256.ComputeHash($finalStream);\n            $computedMac = $hmac;\n\n            $finalStream.Seek(0, [System.IO.SeekOrigin]::Begin) > $null;\n            $finalStream.Write($hmac, 0, $hmac.Length);\n        }\n        finally {\n            if ($null -ne $finalStream) { $finalStream.Dispose(); }\n        }\n    }\n    finally {\n        if ($null -ne $targetStream) { $targetStream.Dispose(); }\n        if ($null -ne $aes) { $aes.Dispose(); }\n    }\n\n    $computedMac;\n}\n\n####################################################\n# Function to encrypt file and return encryption info\nfunction EncryptFile($sourceFile, $targetFile) {\n\n    $encryptionKey = GenerateKey;\n    $hmacKey = GenerateKey;\n    $initializationVector = GenerateIV;\n\n    # Create the encrypted target file and compute the HMAC value.\n    $mac = EncryptFileWithIV $sourceFile $targetFile $encryptionKey $hmacKey $initializationVector;\n\n    # Compute the SHA256 hash of the source file and convert the result to bytes.\n    $fileDigest = (Get-FileHash $sourceFile -Algorithm SHA256).Hash;\n    $fileDigestBytes = New-Object byte[] ($fileDigest.Length / 2);\n    for ($i = 0; $i -lt $fileDigest.Length; $i += 2) {\n        $fileDigestBytes[$i / 2] = [System.Convert]::ToByte($fileDigest.Substring($i, 2), 16);\n    }\n\n    # Return an object that will serialize correctly to the file commit Graph API.\n    $encryptionInfo = @{};\n    $encryptionInfo.encryptionKey = [System.Convert]::ToBase64String($encryptionKey);\n    $encryptionInfo.macKey = [System.Convert]::ToBase64String($hmacKey);\n    $encryptionInfo.initializationVector = [System.Convert]::ToBase64String($initializationVector);\n    $encryptionInfo.mac = [System.Convert]::ToBase64String($mac);\n    $encryptionInfo.profileIdentifier = \"ProfileVersion1\";\n    $encryptionInfo.fileDigest = [System.Convert]::ToBase64String($fileDigestBytes);\n    $encryptionInfo.fileDigestAlgorithm = \"SHA256\";\n\n    $fileEncryptionInfo = @{};\n    $fileEncryptionInfo.fileEncryptionInfo = $encryptionInfo;\n\n    $fileEncryptionInfo;\n}\n\n####################################################\n# Function to wait for file processing to complete by polling the file upload state\nfunction WaitForFileProcessing($fileUri, $stage) {\n\n    $attempts = 60;\n    $waitTimeInSeconds = 1;\n    $successState = \"$($stage)Success\";\n    $pendingState = \"$($stage)Pending\";\n\n    $file = $null;\n    while ($attempts -gt 0) {\n        $file = Invoke-MgGraphRequest -Method GET -Uri $fileUri;\n        if ($file.uploadState -eq $successState) {\n            break;\n        }\n        elseif ($file.uploadState -ne $pendingState) {\n            throw \"File upload state is not success: $($file.uploadState)\";\n        }\n\n        Start-Sleep $waitTimeInSeconds;\n        $attempts--;\n    }\n\n    if ($null -eq $file) {\n        throw \"File request did not complete in the allotted time.\";\n    }\n\n    $file;\n\n}\n\n####################################################\n# Function to generate body for mobileAppContentFile\nfunction GetAppFileBody($name, $size, $sizeEncrypted, $manifest) {\n\n    $body = @{ \"@odata.type\" = \"#microsoft.graph.mobileAppContentFile\" };\n    $body.name = $name;\n    $body.size = $size;\n    $body.sizeEncrypted = $sizeEncrypted;\n    $body.manifest = $manifest;\n\n    $body;\n}\n\n####################################################\n# Function to generate body for commit action\nfunction GetAppCommitBody($contentVersionId, $LobType) {\n\n    $body = @{ \"@odata.type\" = \"#$LobType\" };\n    $body.committedContentVersion = $contentVersionId;\n    $body;\n}\n\n####################################################\n# Function to generate body for Intune mobileapp\nfunction Get-iOSAppBody($displayName, $Publisher, $Description, $fileName) {\n    $body = @{ \"@odata.type\" = \"#microsoft.graph.iosLOBApp\" };\n    $body.applicableDeviceType = @{ \"iPad\" = $true; \"iPhoneAndIPod\" = $true }\n    $body.isFeatured = $false;\n    $body.categories = @();\n    $body.displayName = $displayName;\n    $body.publisher = $publisher;\n    $body.description = $description;\n    $body.fileName = $fileName;\n    $body.informationUrl = $null;\n    $body.privacyInformationUrl = $null;\n    $body.developer = \"\";\n    $body.notes = \"\";\n    $body.owner = \"\";\n    $body.bundleId = \"\";\n    $body.buildNumber = \"\";\n    $body.versionNumber = \"\";\n    $body.expirationDateTime = \"\";\n\n    if ($null -eq $minimumSupportedOperatingSystem) {\n        $body.minimumSupportedOperatingSystem = @{ \"v9_0\" = $true };\n    }\n    else {\n        $body.minimumSupportedOperatingSystem = $minimumSupportedOperatingSystem;\n    }\n\n    $ExtractedIPAMetadata = Get-IpaAppInfo $fileName\n    $body.bundleId = $ExtractedIPAMetadata.BundleId;\n    $body.buildNumber = $ExtractedIPAMetadata.BundleVersion;\n    $body.versionNumber = $ExtractedIPAMetadata.BundleShortVersionString;\n    $body.expirationDateTime = $ExtractedIPAMetadata.ExpirationDateTime;\n\n    return $body\n}\n\n####################################################\n# Function to extract the app information from the .ipa file\n## If unable to extract the app information, the function will prompt the user to enter the app information manually\nfunction Get-IpaAppInfo {\n    param (\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [String]$ipaFilePath\n    )\n\n    # Create a temporary directory to extract the app contents\n    New-Item -ItemType Directory -Force -Path $ExtractedPath | Out-Null\n\n    # Extract the .ipa file contents\n    Expand-Archive -Path $ipaFilePath -DestinationPath $ExtractedPath\n\n    # Find the first info.plist path  in the highest location of the directory structure\n\n    $plistPath = (Get-ChildItem -Path $ExtractedPath -Recurse -Filter \"info.plist\" | Select-Object -ExpandProperty FullName)[0]\n\n    if (-not $plistPath) {\n        Write-Output \"Error: Info.plist not found in the .ipa file.\"\n    }\n\n    # Parse the Info.plist file\n    $plistData = Get-Content -Raw -Path $plistPath\n\n    # Extract CFBundleIdentifier from $plistData using regex\n    $bundleId = [regex]::Match($plistData, '(?<=<key>CFBundleIdentifier</key>\\s*<string>)(.*?)(?=</string>)').Value\n    if (($null -eq $bundleId) -or ($bundleId -eq \"\") ) {\n        $bundleId = Read-Host -Prompt \"Unable to extract the app's bundleId (CFBundleIdentifier). Please enter it manually\"\n    }\n\n    # Extract CFBundleVersion from $plistData using regex\n    $bundleVersion = [regex]::Match($plistData, '(?<=<key>CFBundleVersion</key>\\s*<string>)(.*?)(?=</string>)').Value\n    if (($null -eq $bundleVersion) -or ($bundleVersion -eq \"\")) {\n        $bundleVersion = Read-Host -Prompt \"Unable to extract the app's buildNumber (CFBundleVersion). Please enter it manually\"\n    }\n\n    # Extract the CFBundleShortVersionString from $plistData using regex\n    $bundleShortVersionString = [regex]::Match($plistData, '(?<=<key>CFBundleShortVersionString</key>\\s*<string>)(.*?)(?=</string>)').Value\n    if (($null -eq $bundleShortVersionString) -or ($bundleShortVersionString -eq \"\")) {\n        $bundleShortVersionString = Read-Host -Prompt \"Unable to extract the app's versionNumber (CFBundleShortVersionString). Please enter it manually\"\n    }\n\n    # Check if embedded.mobileprovision file exists\n    $MobileProvisionPath = Get-ChildItem -Path $ExtractedPath -Recurse -Filter 'embedded.mobileprovision' | Select-Object -ExpandProperty FullName\n    if (!$MobileProvisionPath) {\n        Write-Host  \"The .ipa file does not contain an embedded.mobileprovision file.\"\n    }\n\n    # Read the contents of the embedded.mobileprovision file\n    $MobileProvisionContent = Get-Content -Path $MobileProvisionPath -Raw\n\n    # Extract the ExpirationDate value\n    $ExpirationDateMatch = [regex]::Match($MobileProvisionContent, '<key>ExpirationDate<\\/key>\\s*<date>(.+)<\\/date>')\n    if (!$ExpirationDateMatch.Success) {\n        Write-Host \"The embedded.mobileprovision file does not contain an ExpirationDate key.\"\n    }\n\n    # Parse and validate the ExpirationDate value\n    $ExpirationDateString = $ExpirationDateMatch.Groups[1].Value\n    try {\n        $ExpirationDate = [DateTime]::Parse($ExpirationDateString)\n    }\n    catch {\n        Write-Host \"The ExpirationDate key in the embedded.mobileprovision file is not a valid date.\"\n    }\n\n    if (($null -eq $ExpirationDate) -or ($ExpirationDate -eq \"\")) {\n        $ExpirationDate = Read-Host -Prompt \"Unable to extract the app's expiration date (ExpirationDate). Please enter it manually in the format yyyy-MM-ddTHH:mm:ssZ\"\n    }\n\n    # Clean up the temporary directory\n    Remove-Item -Path $ExtractedPath -Recurse -Force\n\n\n    # Compare the ExpirationDate with the current date\n    if ($ExpirationDate -lt (Get-Date)) {\n        Write-Error \"The ExpirationDate for this app ($ExpirationDate) has already passed.\" -ErrorAction Stop\n\n    }\n    # Return the extracted values\n    return @{\n        BundleId                 = $bundleId\n        BundleVersion            = $bundleVersion\n        BundleShortVersionString = $bundleShortVersionString\n        ExpirationDateTime       = $ExpirationDate.ToUniversalTime().ToString(\"yyyy-MM-ddTHH:mm:ssZ\")\n    }\n\n}\n\n####################################################\n# Function the kicks off the iOS LOB app upload process by calling the previous functions in proper order\nfunction Invoke-iOSLobAppUpload() {\n    [CmdletBinding()]\n    param (\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [String]$SourceFile,\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [String]$displayName,\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [String]$Publisher,\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [String]$Description,\n        [Parameter()]\n        [UInt32]$BlockSizeMB = 1\n    )\n    try {\n\n        # Check if the file exists and has a .ipa extension\n        if (!(Test-Path $SourceFile) -or (Get-Item $SourceFile).Extension -ne '.ipa') {\n            Write-Error \"The provided path does not exist or is not an .ipa file.\"\n            return\n        }\n        $LOBType = \"microsoft.graph.iosLOBApp\"\n\n        # Creating temp file name from Source File path\n        $tempFile = [System.IO.Path]::GetDirectoryName(\"$SourceFile\") + \"\\\" + [System.IO.Path]::GetFileNameWithoutExtension(\"$SourceFile\") + \"_temp.bin\"\n\n        # Creating filename variable from Source File Path\n        $fileName = [System.IO.Path]::GetFileName(\"$SourceFile\")\n\n        Write-Host \"Creating JSON data to pass to the service...\" -ForegroundColor Yellow\n        $fileName = (Get-Item $SourceFile).Name\n\n        #Creating Intune app body JSON data to pass to the service\n        $body = Get-iOSAppBody $displayName $publisher $description $fileName\n        Write-Output $body\n\n        # Create the Intune application object in the service\n        Write-Host \"Creating application in Intune...\" -ForegroundColor Yellow\n        $mobileApp = New-MgDeviceAppManagementMobileApp -BodyParameter $body\n\n        # Get the content version for the new app (this will always be 1 until the new app is committed).\n        Write-Host \"Creating Content Version in the service for the application...\" -ForegroundColor Yellow\n        $appId = $mobileApp.id;\n        $contentVersionUri = \"$baseUrl/mobileApps/$appId/$LOBType/contentVersions\";\n        $contentVersion = Invoke-MgGraphRequest -Method POST -Uri $contentVersionUri \"{}\" ;\n\n        # Encrypt file and Get File Information\n        Write-Host \"Encrypting the file '$SourceFile'...\" -ForegroundColor Yellow\n        $encryptionInfo = EncryptFile $sourceFile $tempFile;\n        $Size = (Get-Item \"$sourceFile\").Length\n        $EncrySize = (Get-Item \"$tempFile\").Length\n\n        Write-Host \"Creating the manifest file used to install the application on the device...\" -ForegroundColor Yellow\n        [string]$manifestXML = '<?xml version=\"1.0\" encoding=\"UTF-8\"?><!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\"><plist version=\"1.0\"><dict><key>items</key><array><dict><key>assets</key><array><dict><key>kind</key><string>software-package</string><key>url</key><string>{UrlPlaceHolder}</string></dict></array><key>metadata</key><dict><key>AppRestrictionPolicyTemplate</key> <string>http://management.microsoft.com/PolicyTemplates/AppRestrictions/iOS/v1</string><key>AppRestrictionTechnology</key><string>Windows Intune Application Restrictions Technology for iOS</string><key>IntuneMAMVersion</key><string></string><key>CFBundleSupportedPlatforms</key><array><string>iPhoneOS</string></array><key>MinimumOSVersion</key><string>9.0</string><key>bundle-identifier</key><string>bundleid</string><key>bundle-version</key><string>bundleversion</string><key>kind</key><string>software</string><key>subtitle</key><string>LaunchMeSubtitle</string><key>title</key><string>bundletitle</string></dict></dict></array></dict></plist>'\n        $manifestXML = $manifestXML.replace(\"bundleid\", \"$bundleId\")\n        $manifestXML = $manifestXML.replace(\"bundleversion\", \"$versionNumber\")\n        $manifestXML = $manifestXML.replace(\"bundletitle\", \"$displayName\")\n\n        $Bytes = [System.Text.Encoding]::ASCII.GetBytes($manifestXML)\n        $EncodedText = [Convert]::ToBase64String($Bytes)\n\n        # Create a new file for the app.\n        Write-Host \"Creating a new file entry in Azure for the upload...\" -ForegroundColor Yellow\n        $contentVersionId = $contentVersion.id;\n        $fileBody = GetAppFileBody \"$filename\" $Size $EncrySize \"$EncodedText\";\n        $filesUri = \"$baseUrl/mobileApps/$appId/$LOBType/contentVersions/$contentVersionId/files\";\n        $file = Invoke-MgGraphRequest -Method POST -Uri $filesUri ($fileBody | ConvertTo-Json);\n\n        # Wait for the service to process the new file request.\n        Write-Host \"Waiting for the file entry URI to be created...\" -ForegroundColor Yellow\n        $fileId = $file.id;\n        $fileUri = \"$baseUrl/mobileapps/$appId/$LOBType/contentVersions/$contentVersionId/files/$fileId\";\n        $file = WaitForFileProcessing $fileUri \"AzureStorageUriRequest\";\n\n        # Upload the content to Azure Storage.\n        Write-Host \"Uploading file to Azure Storage...\" -f Yellow\n        UploadFileToAzureStorage $file.azureStorageUri $tempFile $BlockSizeMB\n\n        # Commit the file.\n        Write-Host \"Committing the file into Azure Storage...\" -ForegroundColor Yellow\n        $commitFileUri = \"$baseUrl/mobileApps/$appId/$LOBType/contentVersions/$contentVersionId/files/$fileId/commit\";\n        Invoke-MgGraphRequest -Method POST $commitFileUri -Body ($encryptionInfo | ConvertTo-Json);\n\n        # Wait for the service to process the commit file request.\n        Write-Host \"Waiting for the service to process the commit file request...\" -ForegroundColor Yellow\n        $file = WaitForFileProcessing $fileUri \"CommitFile\";\n\n        # Commit the app.\n        Write-Host \"Committing the app body...\" -ForegroundColor Yellow\n        $commitAppBody = GetAppCommitBody $contentVersionId $LOBType;\n        Update-MgDeviceAppMgtMobileApp -MobileAppId $appId -BodyParameter ($commitAppBody | ConvertTo-Json)\n\n        Write-Host \"Sleeping for $sleep seconds to allow patch completion...\" -f Magenta\n        Start-Sleep $sleep\n\n        # Display the app information from the Intune service\n        $FinalAppStatus = (Get-MgDeviceAppManagementMobileApp -MobileAppId $appId)\n        if ($FinalAppStatus.PublishingState -eq \"published\") {\n            Write-Host \"Application '$displayName' has been successfully uploaded to Intune.\" -ForegroundColor Green\n        }\n        else {\n            Write-Host \"Application '$displayName' has failed to upload to Intune.\" -ForegroundColor Red\n        }\n        $FinalAppStatus | Format-List\n    }\n    catch {\n        Write-Error \"Aborting with exception: $($_.Exception.ToString())\";\n\tthrow $_\n    }\n    finally {\n        # Cleaning up temporary files and directories\n        Remove-Item -Path \"$tempFile\" -Force -ErrorAction SilentlyContinue\n        Remove-Item -Path \"$ExtractedPath\" -Force -ErrorAction SilentlyContinue\n    }\n}\n\n## Example\n#Invoke-iOSLobAppUpload -SourceFile \".\\MyLobApp.ipa\" -displayName \"A test application to deploy via Intune\" -Publisher \"Contoso\" -Description \"A test application to deploy via Intune.\"\n","teaching":["iOS line-of-business application publishing","LOB iOS apps have platform-specific packaging, signing and distribution requirements. An app record differs from installed app behavior.","No live upload. Use fictional package identifiers and review current Apple/Intune supported distribution rules.","Trace a fictional app bundle identifier and signing metadata to intended assignment.",null,"What identifies an Apple app independently of its display name?","bundle identifier"],"kind":"write-reference-only"},{"repository":"microsoft/mggraph-intune-samples","path":"LOB_Application/macOS_Application_PKG_Add.ps1","sha":"83e66bfffb06b121afafb63ea71230ea9b87a48d","lesson":14,"topic":"macOS PKG application publishing","url":"https://github.com/microsoft/mggraph-intune-samples/blob/main/LOB_Application/macOS_Application_PKG_Add.ps1","markdown":"<#\n.COPYRIGHT\nCopyright (c) Microsoft Corporation. All rights reserved. Licensed under the MIT license.\nSee LICENSE in the project root for license information.\n#>\n\n#requires -module Microsoft.Graph.Beta.Devices.CorporateManagement\n#requires -module Microsoft.Graph.Authentication\n\n<# region Authentication\nTo authenticate, you'll use the Microsoft Graph PowerShell SDK. If you haven't already installed the SDK, see this guide:\nhttps://learn.microsoft.com/en-us/powershell/microsoftgraph/installation?view=graph-powershell-1.0\nThe PowerShell SDK supports two types of authentication: delegated access, and app-only access.\nFor details on using delegated access, see this guide here:\nhttps://learn.microsoft.com/powershell/microsoftgraph/get-started?view=graph-powershell-1.0\nFor details on using app-only access for unattended scenarmacOS, see Use app-only authentication with the Microsoft Graph PowerShell SDK:\nhttps://learn.microsoft.com/powershell/microsoftgraph/app-only?view=graph-powershell-1.0&tabs=azure-portal\n#>\n\n<#\n.SYNOPSIS\nUploads an unmanaged macOS PKG application to Intune.\n\n.DESCRIPTION\nThis script uploads an unmanaged macOS PKG application to Intune. The script creates a new mobileApp object in the Intune service, uploads the PKG file to Azure Storage, and commits the file to the mobileApp object. Additionally, the script supports preInstall and postInstall scripts when creating the application.\n\n.PARAMETER SourceFile\nThe path to the PKG file to upload.\n\n.PARAMETER displayName\nThe display name of the application.\n\n.PARAMETER Publisher\nThe publisher of the application.\n\n.PARAMETER Description\nThe description of the application.\n\n.PARAMETER primaryBundleId\nThe primary bundle ID of the application that will be used for reporting.\n\n.PARAMETER primaryBundleVersion\nThe primary bundle version of the application.\n\n.PARAMETER includedApps\nAn array of includedApps objects that represent the included applications in the PKG file. Each includedApps object should have the following properties:\n- bundleId: The bundle ID of the included application.\n- bundleVersion: The bundle version of the included application.\n- \"@odata.type\": The type of the included application. This should always be \"microsoft.graph.macOSIncludedApp\".\n\n.PARAMETER minimumSupportedOperatingSystem\nThe minimum supported operating system for the application. The default value is v10_13.\n\n.PARAMETER ignoreVersionDetection\nA boolean value that indicates whether to ignore version detection when uploading the application.\n\n.PARAMETER preInstallScriptPath\nThe path to the preInstall script to run before installing the application.\n\n.PARAMETER postInstallScriptPath\nThe path to the postInstall script to run after installing the application.\n\n.EXAMPLE\n# This example uploads the Remote Help application to Intune.\n\n## First, create an array of includedApps objects that represent the included applications in the PKG file.\n$includedApps = @(\n    @{\n        \"@odata.type\" = \"microsoft.graph.macOSIncludedApp\"\n        bundleId      = \"com.microsoft.remotehelp\"\n        bundleVersion = \"1.0\"\n    }\n)\n\n## Then, run the Invoke-macOSLobAppUpload function with the required parameters.\nInvoke-macOSLobAppUpload -SourceFile \"E:\\Microsoft_Remote_Help_1.0.2409052_installer.pkg\" -displayName \"Remote Help\" -Publisher \"Microsoft\" -Description \"Remote Help for macOS\" -primaryBundleId \"com.microsoft.remotehelp\" -primaryBundleVersion \"1.0\" -includedApps $includedApps -minimumSupportedOperatingSystem @{v10_13 = $true } -ignoreVersionDetection $true\n\n.EXAMPLE\n# This example uploads the Company Portal application to Intune.\n## First, create an array of includedApps objects that represent the included applications in the PKG file.\n$includedApps = @(\n    @{\n        \"@odata.type\" = \"microsoft.graph.macOSIncludedApp\"\n        bundleId      = \"com.microsoft.com.microsoft.CompanyPortalMac\"\n        bundleVersion = \"4.74\"\n    }\n)\n\n## Then, run the Invoke-macOSLobAppUpload function with the required parameters. Note the preInstallScriptPath and postInstallScriptPath parameters are optional.\nInvoke-macOSLobAppUpload -SourceFile \"E:\\CompanyPortal-Installer.pkg\" -displayName \"Company Portal\" -Publisher \"Microsoft\" -Description \"Company Portal for macOS\" -primaryBundleId \"com.microsoft.com.microsoft.CompanyPortalMac\" -primaryBundleVersion \"5.2409.1\" -includedApps $includedApps -minimumSupportedOperatingSystem @{v10_13 = $true } -ignoreVersionDetection $true -preInstallScriptPath \"E:\\preInstall.sh\" -postInstallScriptPath \"E:\\postInstall.sh\"\n#>\nfunction Invoke-macOSLobAppUpload() {\n    [CmdletBinding()]\n    param (\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [String]$SourceFile,\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [String]$displayName,\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [String]$Publisher,\n        [Parameter(Mandatory = $false)]\n        [ValidateNotNullOrEmpty()]\n        [String]$Description,\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [String]$primaryBundleId,\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [String]$primaryBundleVersion,\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [hashtable[]]$includedApps,\n        [Parameter(Mandatory = $false)]\n        [ValidateNotNullOrEmpty()]\n        [Hashtable]$minimumSupportedOperatingSystem,\n        [Parameter(Mandatory = $true)]\n        [ValidateNotNullOrEmpty()]\n        [bool]$ignoreVersionDetection,\n        [Parameter(Mandatory = $false)]\n        [String]$preInstallScriptPath,\n        [Parameter(Mandatory = $false)]\n        [String]$postInstallScriptPath\n    )\n    try {\n        # Check if the file exists and has a .Pkg extension\n        if (!(Test-Path $SourceFile) -or (Get-Item $SourceFile).Extension -ne '.Pkg') {\n            Write-Error \"The provided path does not exist or is not an .Pkg file.\"\n            throw\n        }\n\n        #Check if minmumSupportedOperatingSystem is provided. If not, default to v10_13\n        if ($minimumSupportedOperatingSystem -eq $null) {\n            $minimumSupportedOperatingSystem = @{ v10_13 = $true }\n        }\n\n        # Creating temp file name from Source File path\n        $tempFile = [System.IO.Path]::GetDirectoryName(\"$SourceFile\") + \"\\\" + [System.IO.Path]::GetFileNameWithoutExtension(\"$SourceFile\") + [guid]::NewGuid().ToString() + \"_temp.bin\"\n        $fileName = (Get-Item $SourceFile).Name\n\n        #Creating Intune app body JSON data to pass to the service\n        Write-Host \"Creating JSON data to pass to the service...\" -ForegroundColor Yellow\n        $body = New-macOSAppBody -displayName $displayName -Publisher $Publisher -Description $Description -fileName $fileName -primaryBundleId $primaryBundleId -primaryBundleVersion $primaryBundleVersion -includedApps $includedApps -minimumSupportedOperatingSystem $minimumSupportedOperatingSystem -ignoreVersionDetection $ignoreVersionDetection -preInstallScriptPath $preInstallScriptPath -postInstallScriptPath $postInstallScriptPath \n\n        # Create the Intune application object in the service\n        Write-Host \"Creating application in Intune...\" -ForegroundColor Yellow\n        $mobileApp = New-MgBetaDeviceAppManagementMobileApp -BodyParameter $body\n        $mobileAppId = $mobileApp.id\n\n        # Get the content version for the new app (this will always be 1 until the new app is committed).\n        Write-Host \"Creating Content Version in the service for the application...\" -ForegroundColor Yellow\n        $ContentVersion = New-MgBetaDeviceAppManagementMobileAppAsMacOSPkgAppContentVersion -MobileAppId $mobileAppId -BodyParameter @{}\n        $ContentVersionId = $ContentVersion.id\n\n        # Encrypt file and get file information\n        Write-Host \"Encrypting the copy of file '$SourceFile'...\" -ForegroundColor Yellow\n        \n        $encryptionInfo = EncryptFile $SourceFile $tempFile\n        $Size = (Get-Item \"$SourceFile\").Length\n        $EncrySize = (Get-Item \"$tempFile\").Length\n\n        $ContentVersionFileBody = @{\n            name          = $fileName\n            size          = $Size\n            sizeEncrypted = $EncrySize\n            manifest      = $null\n            isDependency  = $false\n            \"@odata.type\" = \"#microsoft.graph.mobileAppContentFile\"\n        }\n\n        # Create a new file entry in Azure for the upload\n        Write-Host \"Creating a new file entry in Azure for the upload...\" -ForegroundColor Yellow\n        $ContentVersionFile = New-MgBetaDeviceAppManagementMobileAppAsMacOSPkgAppContentVersionFile -MobileAppId $mobileAppId -MobileAppContentId $ContentVersionId -BodyParameter $ContentVersionFileBody\n        $ContentVersionFileId = $ContentVersionFile.id\n\n        # Get the file URI for the upload\n        $fileUri = \"https://graph.microsoft.com/beta/deviceAppManagement/mobileApps/$mobileAppId/microsoft.graph.macOSPkgApp/contentVersions/$contentVersionId/files/$contentVersionFileId\"\n\n        # Wait for the service to process the file upload request.\n        Write-Host \"Waiting for the service to process the file upload request...\" -ForegroundColor Yellow\n        $file = WaitForFileProcessing $fileUri \"AzureStorageUriRequest\"\n        $sasUriRenewTime = $file.azureStorageUriExpirationDateTime.AddMinutes(-3)\n\n        # Upload the content to Azure Storage.\n        Write-Host \"Uploading file to Azure Storage...\" -f Yellow\n        [UInt64]$BlockSizeMB = 4\n        UploadFileToAzureStorage $file.azureStorageUri $sasUriRenewTime $tempFile $BlockSizeMB \n\n        Write-Host \"Committing the file to the service...\" -ForegroundColor Yellow\n        Invoke-MgBetaCommitDeviceAppManagementMobileAppMicrosoftGraphMacOSPkgAppContentVersionFile -MobileAppId $mobileAppId -MobileAppContentId $ContentVersionId -MobileAppContentFileId $ContentVersionFileId -BodyParameter ($encryptionInfo | ConvertTo-Json)\n\n        # Wait for the service to process the commit file request.\n        Write-Host \"Waiting for the service to process the file commit request...\" -ForegroundColor Yellow\n        $file = WaitForFileProcessing $fileUri \"CommitFile\"\n\n        # Commit the app.\n        Write-Host \"Committing the content version...\" -ForegroundColor Yellow\n        $params = @{\n            \"@odata.type\"           = \"#microsoft.graph.macOSPkgApp\"\n            committedContentVersion = \"1\"\n        }\n        \n        Update-MgBetaDeviceAppManagementMobileApp -MobileAppId $mobileAppId -BodyParameter $params\n\n        # Wait for the service to process the commit app request.\n        Write-Host \"Waiting for the service to process the app commit request...\" -ForegroundColor Yellow\n\n        $AppCheckAttempts = 25\n        while ($AppCheckAttempts -gt 0) {\n            $AppCheckAttempts--\n            $AppStatus = Get-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId\n            if ($AppStatus.PublishingState -eq \"published\") {\n                Write-Host \"Application created successfully.\" -ForegroundColor Green\n                break\n            }\n            Start-Sleep -Seconds 3\n        }\n\n        if ($AppStatus.PublishingState -ne \"published\" -and $AppStatus.PublishingState -ne \"processing\") {\n            Write-Host \"Application '$displayName' has failed to upload to Intune.\" -ForegroundColor Red\n            throw \"Application '$displayName' has failed to upload to Intune.\"\n        }\n        else {\n            Write-Host \"Application '$displayName' has been successfully uploaded to Intune.\" -ForegroundColor Green\n            $AppStatus | Format-List\n        }\n    }\n    catch {\n        Write-Host \"Application '$displayName' has failed to upload to Intune.\" -ForegroundColor Red\n        # In the event that the creation of the app record in Intune succeeded, but processing/file upload failed, you can remove the comment block around the code below to delete the app record.\n        # This will allow you to re-run the script without having to manually delete the incomplete app record.\n        # Note: This will only work if the app record was successfully created in Intune.\n\n        <#\n        if ($mobileAppId) {\n            Write-Host \"Removing the incomplete application record from Intune...\" -ForegroundColor Yellow\n            Remove-MgDeviceAppManagementMobileApp -MobileAppId $mobileAppId\n        }\n        #>\n        Write-Error \"Aborting with exception: $($_.Exception.ToString())\"\n        throw $_\n    }\n    finally {\n        # Cleaning up temporary files and directories\n        Remove-Item -Path \"$tempFile\" -Force -ErrorAction SilentlyContinue\n    }\n}\n\n####################################################\n# Function that uploads a source file chunk to the Intune Service SAS URI location.\nfunction UploadAzureStorageChunk($sasUri, $id, $body) {\n    $uri = \"$sasUri&comp=block&blockid=$id\"\n    $request = \"PUT $uri\"\n\n    $headers = @{\n        \"x-ms-blob-type\" = \"BlockBlob\"\n        \"Content-Type\"   = \"application/octet-stream\"\n        \"Connection\"     = \"Keep-Alive\"\n        \"Content-Length\" = $body.Length\n        \"Accept\"         = \"*/*\"\n    }\n\n    try {\n        Invoke-WebRequest -Headers $headers -Uri $uri -Method Put -Body $body -RetryIntervalSec 2 -MaximumRetryCount 300 \n    }\n    catch {\n        Write-Host -ForegroundColor Red $request\n        Write-Host -ForegroundColor Red $_.Exception.Message\n        throw\n    }\n}\n\n####################################################\n# Function that takes all the chunk ids and joins them back together to recreate the file\nfunction FinalizeAzureStorageUpload($sasUri, $ids) {\n    $uri = \"$sasUri&comp=blocklist\"\n    $request = \"PUT $uri\"\n\n    $xml = '<?xml version=\"1.0\" encoding=\"utf-8\"?><BlockList>'\n    foreach ($id in $ids) {\n        $xml += \"<Latest>$id</Latest>\"\n    }\n    $xml += '</BlockList>'\n\n    if ($logRequestUris) { Write-Host $request; }\n    if ($logContent) { Write-Host -ForegroundColor Gray $xml; }\n\n    $headers = @{\n        \"Content-Type\" = \"text/plain\"\n    }\n\n    try {\n        Invoke-WebRequest $uri -Method Put -Body $xml -Headers $headers\n    }\n    catch {\n        Write-Host -ForegroundColor Red $request\n        Write-Host -ForegroundColor Red $_.Exception.Message\n        throw\n    }\n}\n\n####################################################\n# Function that splits the source file into chunks and calls the upload to the Intune Service SAS URI location, and finalizes the upload\nfunction UploadFileToAzureStorage($sasUri, $sasUriRenewTime, $filepath, $blockSizeMB) {\n    # Chunk size in MiB\n    $chunkSizeInBytes = 1024 * 1024 * $blockSizeMB\n    $fileUri = \"https://graph.microsoft.com/beta/deviceAppManagement/mobileApps/$mobileAppId/microsoft.graph.macOSPkgApp/contentVersions/$contentVersionId/files/$contentVersionFileId\"\n\n    # Read the whole file and find the total chunks.\n    $fileStream = [System.IO.File]::OpenRead($filepath)\n    $chunks = [Math]::Ceiling($fileStream.Length / $chunkSizeInBytes)\n\n    # Upload each chunk.\n    $ids = New-Object System.Collections.ArrayList\n    $cc = 1\n    $chunk = 0\n    while ($fileStream.Position -lt $fileStream.Length) {\n        $id = [System.Convert]::ToBase64String([System.Text.Encoding]::ASCII.GetBytes($chunk.ToString(\"0000\")))\n        $ids.Add($id) > $null\n\n        $size = [Math]::Min($chunkSizeInBytes, $fileStream.Length - $fileStream.Position)\n        $body = New-Object byte[] $size\n        $fileStream.Read($body, 0, $size) > $null\n\n        \"Uploading chunk $cc of $chunks\"\n        $cc++\n\n        UploadAzureStorageChunk $sasUri $id $body | Out-Null\n        $chunk++\n\n        # Renew the SAS URI if it is about to expire.\n        if ((Get-Date).ToUniversalTime() -ge $sasUriRenewTime) {\n            Write-Host \"Renewing the SAS URI for the file upload...\" -ForegroundColor Yellow\n            Invoke-MgBetaRenewDeviceAppManagementMobileAppMicrosoftGraphMacOSPkgAppContentVersionFileUpload -MobileAppId $mobileAppId -MobileAppContentId $ContentVersionId -MobileAppContentFileId $ContentVersionFileId\n            $file = WaitForFileProcessing $fileUri \"AzureStorageUriRenewal\"\n            $sasUri = $file.azureStorageUri\n            $sasUriRenewTime = $file.azureStorageUriExpirationDateTime.AddMinutes(-3)\n            Write-Host \"New SAS Uri renewal time: $sasUriRenewTime\" -ForegroundColor Yellow\n        }\n    }\n\n    $fileStream.Close()\n\n    # Finalize the upload.\n    Write-Host \"Finalizing file upload...\" -ForegroundColor Yellow\n    FinalizeAzureStorageUpload $sasUri $ids | Out-Null\n}\n\n####################################################\n# Function to generate encryption key\nfunction GenerateKey {\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create()\n        $aesProvider = New-Object System.Security.Cryptography.AesCryptoServiceProvider\n        $aesProvider.GenerateKey()\n        $aesProvider.Key\n    }\n    finally {\n        if ($null -ne $aesProvider) { $aesProvider.Dispose(); }\n        if ($null -ne $aes) { $aes.Dispose(); }\n    }\n}\n\n####################################################\n# Function to generate HMAC key\nfunction GenerateIV {\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create()\n        $aes.IV\n    }\n    finally {\n        if ($null -ne $aes) { $aes.Dispose(); }\n    }\n}\n\n####################################################\n# Function to create the encrypted target file compute HMAC value, and return the HMAC value\nfunction EncryptFileWithIV($sourceFile, $targetFile, $encryptionKey, $hmacKey, $initializationVector) {\n    $bufferBlockSize = 1024 * 4\n    $computedMac = $null\n\n    try {\n        $aes = [System.Security.Cryptography.Aes]::Create()\n        $hmacSha256 = New-Object System.Security.Cryptography.HMACSHA256\n        $hmacSha256.Key = $hmacKey\n        $hmacLength = $hmacSha256.HashSize / 8\n\n        $buffer = New-Object byte[] $bufferBlockSize\n        $bytesRead = 0\n\n        $targetStream = [System.IO.File]::Open($targetFile, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::Read)\n        $targetStream.Write($buffer, 0, $hmacLength + $initializationVector.Length)\n\n        try {\n            $encryptor = $aes.CreateEncryptor($encryptionKey, $initializationVector)\n            $sourceStream = [System.IO.File]::Open($sourceFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)\n            $cryptoStream = New-Object System.Security.Cryptography.CryptoStream -ArgumentList @($targetStream, $encryptor, [System.Security.Cryptography.CryptoStreamMode]::Write)\n\n            $targetStream = $null\n            while (($bytesRead = $sourceStream.Read($buffer, 0, $bufferBlockSize)) -gt 0) {\n                $cryptoStream.Write($buffer, 0, $bytesRead)\n                $cryptoStream.Flush()\n            }\n            $cryptoStream.FlushFinalBlock()\n        }\n        finally {\n            if ($null -ne $cryptoStream) { $cryptoStream.Dispose(); }\n            if ($null -ne $sourceStream) { $sourceStream.Dispose(); }\n            if ($null -ne $encryptor) { $encryptor.Dispose(); }\n        }\n\n        try {\n            $finalStream = [System.IO.File]::Open($targetFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read)\n            $finalStream.Seek($hmacLength, [System.IO.SeekOrigin]::Begin) > $null\n            $finalStream.Write($initializationVector, 0, $initializationVector.Length)\n            $finalStream.Seek($hmacLength, [System.IO.SeekOrigin]::Begin) > $null\n            $hmac = $hmacSha256.ComputeHash($finalStream)\n            $computedMac = $hmac\n            $finalStream.Seek(0, [System.IO.SeekOrigin]::Begin) > $null\n            $finalStream.Write($hmac, 0, $hmac.Length)\n        }\n        finally {\n            if ($null -ne $finalStream) { $finalStream.Dispose(); }\n        }\n    }\n    finally {\n        if ($null -ne $targetStream) { $targetStream.Dispose(); }\n        if ($null -ne $aes) { $aes.Dispose(); }\n    }\n\n    $computedMac\n}\n\n####################################################\n# Function to encrypt file and return encryption info\nfunction EncryptFile($sourceFile, $targetFile) {\n    $encryptionKey = GenerateKey\n    $hmacKey = GenerateKey\n    $initializationVector = GenerateIV\n\n    # Create the encrypted target file and compute the HMAC value.\n    $mac = EncryptFileWithIV $sourceFile $targetFile $encryptionKey $hmacKey $initializationVector\n\n    # Compute the SHA256 hash of the source file and convert the result to bytes.\n    $fileDigest = (Get-FileHash $sourceFile -Algorithm SHA256).Hash\n    $fileDigestBytes = New-Object byte[] ($fileDigest.Length / 2)\n    for ($i = 0; $i -lt $fileDigest.Length; $i += 2) {\n        $fileDigestBytes[$i / 2] = [System.Convert]::ToByte($fileDigest.Substring($i, 2), 16)\n    }\n\n    # Return an object that will serialize correctly to the file commit Graph API.\n    $encryptionInfo = @{}\n    $encryptionInfo.encryptionKey = [System.Convert]::ToBase64String($encryptionKey)\n    $encryptionInfo.macKey = [System.Convert]::ToBase64String($hmacKey)\n    $encryptionInfo.initializationVector = [System.Convert]::ToBase64String($initializationVector)\n    $encryptionInfo.mac = [System.Convert]::ToBase64String($mac)\n    $encryptionInfo.profileIdentifier = \"ProfileVersion1\"\n    $encryptionInfo.fileDigest = [System.Convert]::ToBase64String($fileDigestBytes)\n    $encryptionInfo.fileDigestAlgorithm = \"SHA256\"\n\n    $fileEncryptionInfo = @{}\n    $fileEncryptionInfo.fileEncryptionInfo = $encryptionInfo\n    $fileEncryptionInfo\n}\n\n####################################################\n# Function to wait for file processing to complete by polling the file upload state\nfunction WaitForFileProcessing($fileUri, $stage) {\n    $attempts = 120\n    $waitTimeInSeconds = 2\n    $successState = \"$($stage)Success\"\n    $renewalSuccessState = \"$($stage)RenewalSuccess\"\n    $renewalPendingState = \"$($stage)RenewalPending\"\n    $pendingState = \"$($stage)Pending\"\n\n    $file = $null\n    while ($attempts -gt 0) {\n        $file = Invoke-MgGraphRequest -Method GET -Uri $fileUri\n        if ($file.uploadState -eq $successState -or $file.uploadState -eq $renewalSuccessState -or $file.uploadState -eq $renewalPendingState) {\n            break\n        }\n        elseif ($file.uploadState -ne $pendingState -and $file.uploadState -ne $renewalPendingState) {\n            throw \"File upload state is not success: $($file.uploadState)\"\n        }\n\n        Start-Sleep $waitTimeInSeconds\n        $attempts--\n    }\n\n    if ($null -eq $file) {\n        throw \"File request did not complete in the allotted time.\"\n    }\n    $file\n}\n\n####################################################\n# Function to generate body for mobileAppContentFile\nfunction GetAppFileBody($name, $size, $sizeEncrypted, $manifest) {\n    $body = @{ \"@odata.type\" = \"#microsoft.graph.macOSPkgApp\" }\n    $body.name = $name\n    $body.size = $size\n    $body.sizeEncrypted = $sizeEncrypted\n    $body.manifest = $manifest\n    $body\n}\n\n####################################################\n# Function to generate body for commit action\nfunction GetAppCommitBody($contentVersionId, $LobType) {\n    $body = @{ \"@odata.type\" = \"#$LobType\" }\n    $body.committedContentVersion = $contentVersionId\n    $body\n}\n\n#Function to encode the pre and post install scripts in base64\nfunction Convert-ScriptToBase64($scriptPath) {\n    $script = Get-Content $scriptPath -Raw\n    $bytes = [System.Text.Encoding]::UTF8.GetBytes($script)\n    $encoded = [System.Convert]::ToBase64String($bytes)\n    return $encoded\n}\n\n####################################################\n# Function to generate body for Intune mobileapp\nfunction New-macOSAppBody() {\n    [CmdletBinding()]\n    param (\n        [Parameter(Mandatory = $true)]\n        [string]$displayName,\n        [Parameter(Mandatory = $true)]\n        [string]$Publisher,\n        [Parameter(Mandatory = $false)]\n        [string]$Description,\n        [Parameter(Mandatory = $true)]\n        [string]$fileName,\n        [Parameter(Mandatory = $true)]\n        [string]$primaryBundleId,\n        [Parameter(Mandatory = $true)]\n        [string]$primaryBundleVersion,\n        [Parameter(Mandatory = $true)]\n        [hashtable[]]$includedApps,\n        [Parameter(Mandatory = $false)]\n        [hashtable]$minimumSupportedOperatingSystem,\n        [Parameter(Mandatory = $true)]\n        [bool]$ignoreVersionDetection,\n        [Parameter(Mandatory = $false)]\n        [string]$preInstallScriptPath,\n        [Parameter(Mandatory = $false)]\n        [string]$postInstallScriptPath\n    )\n\n    $body = @{ \"@odata.type\" = \"#microsoft.graph.macOSPkgApp\" }\n    $body.isFeatured = $false\n    $body.categories = @()\n    $body.displayName = $displayName\n    $body.publisher = $publisher\n    $body.description = $description\n    $body.fileName = $fileName\n    $body.informationUrl = \"\"\n    $body.privacyInformationUrl = \"\"\n    $body.developer = \"\"\n    $body.notes = \"\"\n    $body.owner = \"\"\n    $body.primaryBundleId = $primaryBundleId\n    $body.primaryBundleVersion = $primaryBundleVersion\n    $body.includedApps = $includedApps\n    $body.ignoreVersionDetection = $ignoreVersionDetection\n\n    if ($null -eq $minimumSupportedOperatingSystem) {\n        $body.minimumSupportedOperatingSystem = @{ v10_13 = $true }\n    }\n    else {\n        $body.minimumSupportedOperatingSystem = $minimumSupportedOperatingSystem\n    }\n\n    if ($preInstallScriptPath) {\n        $body.preInstallScript = @{\n            scriptContent = Convert-ScriptToBase64($preInstallScriptPath)\n        }\n    }\n    else {\n        $body.preInstallScript = $null\n    }\n\n    if ($postInstallScriptPath) {\n        $body.postInstallScript = @{\n            scriptContent = Convert-ScriptToBase64($postInstallScriptPath)\n        }\n    }\n    else {\n        $body.postInstallScript = $null\n    }\n    \n    return $body\n}\n","teaching":["macOS PKG application publishing","A macOS package contains installer content and metadata for supported delivery. Signing, applicable requirements and actual installation evidence matter.","Read only. Do not install or upload a package for study; review current supported package type and configuration.","Compare a fictional PKG version and intended device targeting; inspect installation evidence.",null,"Which macOS package format is covered?","pkg"],"kind":"write-reference-only"},{"repository":"microsoft/mggraph-intune-samples","path":"ManagedDevices/Get_DeviceAction_Set.ps1","sha":"36e2f3314153a2036af2aaad6fa3b303b2668fd3","lesson":19,"topic":"Managed device remote action design","url":"https://github.com/microsoft/mggraph-intune-samples/blob/main/ManagedDevices/Get_DeviceAction_Set.ps1","markdown":"<#\r\n.COPYRIGHT\r\nCopyright (c) Microsoft Corporation. All rights reserved. Licensed under the MIT license.\r\nSee LICENSE in the project root for license information.\r\n#>\r\n\r\nImport-Module Microsoft.Graph.DeviceManagement.Actions\r\n\r\n<# region Authentication\r\nTo authenticate, you'll use the Microsoft Graph PowerShell SDK. If you haven't already installed the SDK, see this guide:\r\nhttps://learn.microsoft.com/en-us/powershell/microsoftgraph/installation?view=graph-powershell-1.0 \r\nThe PowerShell SDK supports two types of authentication: delegated access, and app-only access. \r\nFor details on using delegated access, see this guide here:\r\nhttps://learn.microsoft.com/powershell/microsoftgraph/get-started?view=graph-powershell-1.0\r\nFor details on using app-only access for unattended scenarios, see Use app-only authentication with the Microsoft Graph PowerShell SDK:\r\nhttps://learn.microsoft.com/powershell/microsoftgraph/app-only?view=graph-powershell-1.0&tabs=azure-portal \r\n#>\r\n\r\nFunction Get-IntuneRemoteActions() {\r\n\r\n\t<#\r\n\t.SYNOPSIS\r\n\tThis function is used to return available remote actions from the Graph PowerShell SDK\r\n\t.DESCRIPTION\r\n\tThe function scans the installed Graph PowerShell SDK for available remote actions based on specified Graph version and asks the user for a remote action to return the parameters for\r\n\t.EXAMPLE\r\n\tGet-IntuneRemoteActions -MgProfile beta\r\n\tReturns all Graph PowerShell SDK remote actions for the specified Graph beta version\r\n\r\n    Get-IntuneRemoteActions -MgProfile \"v1.0\"\r\n\tReturns all Graph PowerShell SDK remote actions for the specified Graph v1.0 version\r\n\t.NOTES\r\n\tNAME: Get-IntuneRemoteActions\r\n\t#>\r\n\t\r\n\t[cmdletbinding()]\r\n\t\r\n\tparam(\r\n\t\t[Parameter(Mandatory = $false)]\r\n\t\t[string]$MgProfile\r\n\t)\r\n\r\n\tif ($MgProfile -ne \"beta\" -and $MgProfile -ne \"v1.0\") {\r\n\t\t$RemoteActions = Find-MgGraphCommand -Uri \"deviceManagement/managedDevices/.*\" -Method POST \r\n\r\n\t}\r\n\telseif ($MgProfile -eq \"beta\") {\r\n\t\t$RemoteActions = Find-MgGraphCommand -Uri \"deviceManagement/managedDevices/.*\" -Method POST -ApiVersion \"beta\"\r\n\t}\r\n\telseif ($MgProfile -eq \"v1.0\") {\r\n\t\t$RemoteActions = Find-MgGraphCommand -Uri \"deviceManagement/managedDevices/.*\" -Method POST -ApiVersion \"v1.0\"\r\n\t}\r\n\t#Only show results with Module Name DeviceManagement.Actions\r\n\t$RemoteActions = Find-MgGraphCommand -Uri \"deviceManagement/managedDevices/.*\" -Method POST -ApiVersion $MgProfile\r\n\tWrite-Host \"Available Remote Actions:\" -ForegroundColor Green\r\n\t\r\n\t$RemoteActions | Format-Table -Property Command, Uri, Method, ApiVersion \r\n\r\n\t$SelectedCmdlet = Read-Host -Prompt \"Enter the remote action Command name to view available parameters\"\r\n\tWrite-Host\r\n\r\n\tif ($SelectedCmdlet -notin $RemoteActions.Command) {\r\n\t\tWrite-Host \"Command not found. Exiting.\"\r\n\t\texit\r\n\t}\r\n\r\n $Parameters = Get-Command -Name $SelectedCmdlet  | Select-Object -ExpandProperty Parameters\r\n $Parameters.Keys\r\n Write-Host\r\n}\r\n","teaching":["Managed device remote action design","Device actions request service-side management operations on a selected endpoint. Sync, restart, retire and wipe differ in effect and supported platform. Request acceptance is not successful completion.","Potentially disruptive source; never execute it in training. Use fictional IDs, approval and action states.","Classify hypothetical action effects and explain device identity verification before any approved operation.",null,"What must uniquely identify the authorized endpoint before a remote action?","device id"],"kind":"write-reference-only"}]};
